// Hangar Door Buzzer
// Written by a beginner, so I explain everything.
// Goal: when the big hangar door is moving, sound a buzzer
// so people know to stay clear. Arduino Uno, Arduino core only.

// ---- Pin assignments ----
// Pin 2: input from the door controller. HIGH = door is moving.
// Pin 8: output to the buzzer (active buzzer, so just HIGH/LOW).
const int DOOR_PIN = 2;
const int BUZZER_PIN = 8;

// How long the buzzer stays on, then off, in milliseconds.
// 400ms on / 400ms off is a nice slow beep-beep.
const unsigned long BEEP_ON_MS = 400;
const unsigned long BEEP_OFF_MS = 400;

// We remember when we last changed the buzzer state.
unsigned long lastChange = 0;
bool buzzerOn = false;

void setup() {
  // The door controller drives pin 2. We only listen.
  // INPUT (not INPUT_PULLUP) because the controller has its own output.
  pinMode(DOOR_PIN, INPUT);

  // The buzzer is an output. We drive it.
  pinMode(BUZZER_PIN, OUTPUT);

  // Start with the buzzer silent. LOW = off for our buzzer.
  digitalWrite(BUZZER_PIN, LOW);

  // Serial is handy for debugging but not required.
  // Ignore it if you don't have a USB cable plugged in.
  Serial.begin(9600);
}

void loop() {
  // Read the door state every pass through the loop.
  int doorState = digitalRead(DOOR_PIN);

  if (doorState == HIGH) {
    // Door is moving. Beep on and off on a timer.
    unsigned long now = millis();

    if (buzzerOn) {
      // It is on. Check if it has been on long enough.
      if (now - lastChange >= BEEP_ON_MS) {
        digitalWrite(BUZZER_PIN, LOW);
        buzzerOn = false;
        lastChange = now;
      }
    } else {
      // It is off. Check if it has been off long enough.
      if (now - lastChange >= BEEP_OFF_MS) {
        digitalWrite(BUZZER_PIN, HIGH);
        buzzerOn = true;
        lastChange = now;
      }
    }
  } else {
    // Door is stopped. Make sure the buzzer is quiet.
    // We reset the timer too so the next beep starts clean.
    digitalWrite(BUZZER_PIN, LOW);
    buzzerOn = false;
    lastChange = millis();
  }

  // A tiny delay keeps the loop from spinning too fast.
  // 10ms is fine; it won't make the beeps feel late.
  delay(10);
}

// Arcade coin door reader
// Reads two coin slots and a service button, blinks a status LED.

const byte COIN1_PIN = 2;   // left slot switch, to GND
const byte COIN2_PIN = 3;   // right slot switch, to GND
const byte SERVICE_PIN = 4; // service button, to GND
const byte LED_PIN = 13;    // onboard LED

const unsigned long DEBOUNCE_MS = 25;
const unsigned long BLINK_MS = 500;

int credits = 0;

// per-input debounce state
unsigned long lastEdge1 = 0;
unsigned long lastEdge2 = 0;
unsigned long lastEdgeS = 0;
int lastState1 = HIGH;
int lastState2 = HIGH;
int lastStateS = HIGH;

unsigned long lastBlink = 0;
bool ledOn = false;

void setup() {
  pinMode(COIN1_PIN, INPUT_PULLUP);
  pinMode(COIN2_PIN, INPUT_PULLUP);
  pinMode(SERVICE_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
  Serial.println("Coin door ready");
}

void loop() {
  unsigned long now = millis();

  // --- left coin slot ---
  int s1 = digitalRead(COIN1_PIN);
  if (s1 != lastState1 && (now - lastEdge1) > DEBOUNCE_MS) {
    lastEdge1 = now;
    lastState1 = s1;
    if (s1 == LOW) {
      credits++;
      Serial.print("Coin L, credits=");
      Serial.println(credits);
    }
  }

  // --- right coin slot ---
  int s2 = digitalRead(COIN2_PIN);
  if (s2 != lastState2 && (now - lastEdge2) > DEBOUNCE_MS) {
    lastEdge2 = now;
    lastState2 = s2;
    if (s2 == LOW) {
      credits++;
      Serial.print("Coin R, credits=");
      Serial.println(credits);
    }
  }

  // --- service button ---
  int ss = digitalRead(SERVICE_PIN);
  if (ss != lastStateS && (now - lastEdgeS) > DEBOUNCE_MS) {
    lastEdgeS = now;
    lastStateS = ss;
    if (ss == LOW) {
      credits = 0;
      Serial.println("Service: credits cleared");
    }
  }

  // --- status blink ---
  if (now - lastBlink >= BLINK_MS) {
    lastBlink = now;
    ledOn = !ledOn;
    digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
  }
}

/*
 * Barber Chair Lift Limit Controller
 * -----------------------------------
 * Design notes:
 *  - A DC gearmotor raises/lowers the chair. Two momentary buttons command
 *    UP and DOWN. Two limit switches (top and bottom) cut travel in hardware
 *    terms; we also enforce them in software so a stuck switch can't drive
 *    the motor into the frame.
 *  - A dead-man rule: the motor only runs while a direction button is held.
 *  - Direction changes are interlocked with a short settle delay so the H-bridge
 *    never sees a plug-reverse.
 *  - Limit switches are wired normally-closed to GND, so a broken wire reads
 *    as "at limit" (fail-safe). INPUT_PULLUP is used throughout.
 */

// ---- Pin map -------------------------------------------------------------
const uint8_t PIN_BTN_UP     = 2;   // to GND, active LOW
const uint8_t PIN_BTN_DOWN   = 3;   // to GND, active LOW
const uint8_t PIN_LIMIT_TOP  = 4;   // NC switch to GND, LOW = at top
const uint8_t PIN_LIMIT_BOT  = 5;   // NC switch to GND, LOW = at bottom
const uint8_t PIN_MOTOR_UP   = 9;   // H-bridge IN1
const uint8_t PIN_MOTOR_DOWN = 10;  // H-bridge IN2
const uint8_t PIN_LED_STATUS = 13;  // onboard LED, lit while motor runs

// ---- Tuning --------------------------------------------------------------
const uint16_t DEBOUNCE_MS   = 25;   // button/switch debounce window
const uint16_t SETTLE_MS     = 120;  // pause between direction changes

// ---- State ---------------------------------------------------------------
enum Dir { DIR_STOP = 0, DIR_UP, DIR_DOWN };
Dir activeDir = DIR_STOP;
unsigned long lastChangeMs = 0;

// Debounced reads (simple: sample, wait, sample again)
bool readActiveLow(uint8_t pin) {
  if (digitalRead(pin) != LOW) return false;
  delay(DEBOUNCE_MS);
  return digitalRead(pin) == LOW;
}

void stopMotor() {
  digitalWrite(PIN_MOTOR_UP, LOW);
  digitalWrite(PIN_MOTOR_DOWN, LOW);
  digitalWrite(PIN_LED_STATUS, LOW);
  activeDir = DIR_STOP;
}

void runMotor(Dir d) {
  if (d == DIR_UP) {
    digitalWrite(PIN_MOTOR_DOWN, LOW);
    digitalWrite(PIN_MOTOR_UP, HIGH);
  } else {
    digitalWrite(PIN_MOTOR_UP, LOW);
    digitalWrite(PIN_MOTOR_DOWN, HIGH);
  }
  digitalWrite(PIN_LED_STATUS, HIGH);
  activeDir = d;
  lastChangeMs = millis();
}

void setup() {
  pinMode(PIN_BTN_UP, INPUT_PULLUP);
  pinMode(PIN_BTN_DOWN, INPUT_PULLUP);
  pinMode(PIN_LIMIT_TOP, INPUT_PULLUP);
  pinMode(PIN_LIMIT_BOT, INPUT_PULLUP);
  pinMode(PIN_MOTOR_UP, OUTPUT);
  pinMode(PIN_MOTOR_DOWN, OUTPUT);
  pinMode(PIN_LED_STATUS, OUTPUT);
  stopMotor();
}

void loop() {
  bool upHeld   = readActiveLow(PIN_BTN_UP);
  bool downHeld = readActiveLow(PIN_BTN_DOWN);
  bool atTop    = readActiveLow(PIN_LIMIT_TOP);
  bool atBottom = readActiveLow(PIN_LIMIT_BOT);

  // Both buttons: treat as stop (ambiguous command).
  if (upHeld && downHeld) {
    stopMotor();
    return;
  }

  Dir want = DIR_STOP;
  if (upHeld && !atTop)        want = DIR_UP;
  else if (downHeld && !atBottom) want = DIR_DOWN;

  if (want == DIR_STOP) {
    if (activeDir != DIR_STOP) stopMotor();
    return;
  }

  if (want == activeDir) return;  // already running the right way

  // Direction change (or start): honour settle time before energising.
  if (activeDir != DIR_STOP) {
    stopMotor();
    if (millis() - lastChangeMs < SETTLE_MS) return;
  }
  runMotor(want);
}

#include <EEPROM.h>

const byte PIN_HX_DT = 2;
const byte PIN_HX_SCK = 3;
const byte PIN_LED = 13;

const float CAL = 2280.0;
const int ZERO = 8420000L;

long tare = 0;
float lastKg = 0;
unsigned long lastLog = 0;
unsigned long lastBlink = 0;
bool ledOn = false;

long readHX() {
  while (digitalRead(PIN_HX_DT)) {}
  long v = 0;
  for (byte i = 0; i < 24; i++) {
    digitalWrite(PIN_HX_SCK, HIGH);
    v = (v << 1) | (digitalRead(PIN_HX_DT) ? 1 : 0);
    digitalWrite(PIN_HX_SCK, LOW);
  }
  digitalWrite(PIN_HX_SCK, HIGH);
  digitalWrite(PIN_HX_SCK, LOW);
  if (v & 0x800000L) v |= ~0xFFFFFFL;
  return v;
}

void setup() {
  pinMode(PIN_HX_SCK, OUTPUT);
  pinMode(PIN_HX_DT, INPUT);
  pinMode(PIN_LED, OUTPUT);
  Serial.begin(9600);
  tare = (long)EEPROM.get(0, tare);
  if (tare == 0 || tare == -1) tare = ZERO;
  Serial.println(F("hive scale up"));
}

void loop() {
  long raw = readHX();
  float kg = (raw - tare) / CAL;
  if (fabs(kg - lastKg) > 0.02) {
    lastKg = kg;
    Serial.print(millis());
    Serial.print(' ');
    Serial.println(kg, 3);
  }
  if (millis() - lastLog > 60000UL) {
    lastLog = millis();
    Serial.print(F("LOG "));
    Serial.println(kg, 3);
    EEPROM.put(0, tare);
  }
  if (millis() - lastBlink > 500) {
    lastBlink = millis();
    ledOn = !ledOn;
    digitalWrite(PIN_LED, ledOn);
  }
  delay(80);
}

#include <Arduino.h>

const uint8_t RELAY_PIN = 7;
const uint8_t SENSOR_PIN = A0;
const uint8_t LED_PIN = 13;

const float TARGET_C = 18.0;
const float HYST_C = 0.5;
const float MIN_C = 2.0;
const float MAX_C = 30.0;

const unsigned long SAMPLE_MS = 2000;
const unsigned long MIN_ON_MS = 60000;
const unsigned long MIN_OFF_MS = 120000;

float readTempC() {
  int raw = analogRead(SENSOR_PIN);
  float v = raw * (5.0 / 1023.0);
  return (v - 0.5) * 100.0;
}

bool cooling = false;
unsigned long lastSample = 0;
unsigned long lastSwitch = 0;
float tempC = 0.0;

void setCooling(bool on) {
  cooling = on;
  digitalWrite(RELAY_PIN, on ? HIGH : LOW);
  digitalWrite(LED_PIN, on ? HIGH : LOW);
  lastSwitch = millis();
}

void setup() {
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
  Serial.begin(9600);
  lastSwitch = millis();
}

void loop() {
  unsigned long now = millis();
  if (now - lastSample >= SAMPLE_MS) {
    lastSample = now;
    tempC = readTempC();
    Serial.print("T=");
    Serial.print(tempC, 2);
    Serial.print(" C=");
    Serial.println(cooling ? 1 : 0);

    if (tempC < MIN_C || tempC > MAX_C) {
      if (cooling) setCooling(false);
      return;
    }

    if (!cooling) {
      if (tempC > TARGET_C + HYST_C && now - lastSwitch >= MIN_OFF_MS) {
        setCooling(true);
      }
    } else {
      if (tempC < TARGET_C - HYST_C && now - lastSwitch >= MIN_ON_MS) {
        setCooling(false);
      }
    }
  }
}

// Bell tower striker
// Arduino Uno, drives a solenoid through a MOSFET
// Hobbyist build, 2024

const int STRIKE_PIN = 9;      // gate of the MOSFET
const int BUTTON_PIN = 2;      // manual strike button, to GND
const int LED_PIN = 13;        // onboard LED

// timing in milliseconds
const unsigned long STRIKE_MS = 120;   // how long the solenoid is energized
const unsigned long GAP_MS = 400;      // pause between strikes
const unsigned long HOUR_GAP_MS = 1500; // longer pause between hours

int hour = 1;                  // which hour we are on (1..12)
unsigned long lastStrike = 0;
unsigned long lastHour = 0;
bool striking = false;
int strikesLeft = 0;
bool lastButton = HIGH;

void setup() {
  pinMode(STRIKE_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  digitalWrite(STRIKE_PIN, LOW);
  Serial.begin(9600);
  Serial.println("Bell tower ready");
  lastHour = millis();
}

void loop() {
  // manual strike on button press (falling edge)
  bool btn = digitalRead(BUTTON_PIN);
  if (btn == LOW && lastButton == HIGH) {
    startStrikes(1);
  }
  lastButton = btn;

  // every hour, strike the hour count
  if (!striking && millis() - lastHour >= 3600000UL) {
    lastHour = millis();
    startStrikes(hour);
    hour++;
    if (hour > 12) hour = 1;
  }

  // run the strike sequence without blocking too long
  if (striking) {
    unsigned long now = millis();
    if (now - lastStrike >= (strikesLeft > 0 ? GAP_MS : HOUR_GAP_MS)) {
      if (strikesLeft > 0) {
        strikeOnce();
        strikesLeft--;
        lastStrike = now;
      } else {
        striking = false;
        digitalWrite(LED_PIN, LOW);
      }
    }
  }
}

void startStrikes(int n) {
  strikesLeft = n;
  striking = true;
  lastStrike = millis() - GAP_MS; // strike right away
  digitalWrite(LED_PIN, HIGH);
  Serial.print("Striking ");
  Serial.println(n);
}

void strikeOnce() {
  digitalWrite(STRIKE_PIN, HIGH);
  delay(STRIKE_MS);
  digitalWrite(STRIKE_PIN, LOW);
}

#include <EEPROM.h>

const uint8_t BUZZ = 9;
const uint8_t LED = 13;
const uint8_t BTN = 2;
const uint8_t SENSE = A0;

const float VREF = 5.0;
const float T_MIN = 2.0;
const float T_MAX = 6.0;
const float HYST = 0.4;
const unsigned long GRACE = 60000UL;
const unsigned long BLINK = 250UL;

float tempC = 0.0;
bool alarm = false;
bool muted = false;
unsigned long badSince = 0;
unsigned long lastBlink = 0;
bool ledState = false;

float readTemp() {
  long sum = 0;
  for (uint8_t i = 0; i < 8; i++) {
    sum += analogRead(SENSE);
    delay(2);
  }
  float v = (sum / 8.0) * VREF / 1024.0;
  return (v - 0.5) * 100.0;
}

void setup() {
  pinMode(BUZZ, OUTPUT);
  pinMode(LED, OUTPUT);
  pinMode(BTN, INPUT_PULLUP);
  Serial.begin(9600);
  digitalWrite(BUZZ, LOW);
  digitalWrite(LED, LOW);
  if (EEPROM.read(0) != 0xA5) {
    EEPROM.write(0, 0xA5);
    EEPROM.put(1, T_MIN);
    EEPROM.put(5, T_MAX);
  }
}

void loop() {
  tempC = readTemp();

  if (digitalRead(BTN) == LOW) {
    muted = true;
    delay(200);
  }

  bool out = (tempC < T_MIN || tempC > T_MAX);
  bool back = (tempC > T_MIN + HYST && tempC < T_MAX - HYST);

  if (out && !alarm) {
    if (badSince == 0) badSince = millis();
    if (millis() - badSince >= GRACE) {
      alarm = true;
      muted = false;
    }
  } else if (back) {
    alarm = false;
    muted = false;
    badSince = 0;
  }

  if (alarm && !muted) {
    digitalWrite(BUZZ, HIGH);
    if (millis() - lastBlink >= BLINK) {
      lastBlink = millis();
      ledState = !ledState;
      digitalWrite(LED, ledState);
    }
  } else {
    digitalWrite(BUZZ, LOW);
    digitalWrite(LED, alarm ? HIGH : LOW);
  }

  Serial.print(tempC, 2);
  Serial.print(' ');
  Serial.println(alarm ? 1 : 0);
  delay(500);
}

const uint8_t FLOAT_PIN = 2;
const uint8_t PUMP_PIN = 9;
const uint8_t LED_PIN = 13;
const uint8_t MANUAL_PIN = 4;

const unsigned long RUN_MS = 8000;
const unsigned long COOLDOWN_MS = 30000;
const unsigned long DEBOUNCE_MS = 50;

bool lastFloat = false;
bool stableFloat = false;
unsigned long lastChange = 0;
unsigned long pumpStart = 0;
unsigned long lastStop = 0;
bool pumping = false;

void setup() {
  pinMode(FLOAT_PIN, INPUT_PULLUP);
  pinMode(MANUAL_PIN, INPUT_PULLUP);
  pinMode(PUMP_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(PUMP_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
  lastFloat = readFloat();
  stableFloat = lastFloat;
  lastChange = millis();
}

bool readFloat() {
  return digitalRead(FLOAT_PIN) == LOW;
}

bool manualOn() {
  return digitalRead(MANUAL_PIN) == LOW;
}

void startPump() {
  digitalWrite(PUMP_PIN, HIGH);
  digitalWrite(LED_PIN, HIGH);
  pumping = true;
  pumpStart = millis();
}

void stopPump() {
  digitalWrite(PUMP_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
  pumping = false;
  lastStop = millis();
}

void loop() {
  bool f = readFloat();
  unsigned long now = millis();

  if (f != lastFloat) {
    lastFloat = f;
    lastChange = now;
  }
  if (now - lastChange >= DEBOUNCE_MS) {
    stableFloat = f;
  }

  bool want = stableFloat || manualOn();

  if (want && !pumping) {
    if (now - lastStop >= COOLDOWN_MS || lastStop == 0) {
      startPump();
    }
  } else if (!want && pumping) {
    stopPump();
  }

  if (pumping && now - pumpStart >= RUN_MS) {
    stopPump();
  }
}

/*
 * Bowling Pin Reset Model
 * ------------------------
 * Simulates the sweep-and-reset mechanism of a ten-pin bowling machine.
 *
 * Design:
 *   - A servo sweeps a "rake" arm across the pin deck to knock down
 *     standing pins, then returns home.
 *   - A solenoid (via relay) drops a fresh set of pins onto the deck.
 *   - A single push button starts one reset cycle.
 *   - A status LED blinks while the cycle runs and stays solid when idle.
 *
 * Sequence per button press:
 *   1. Sweep rake out (servo 0 -> 90 deg), hold briefly.
 *   2. Sweep rake back home (90 -> 0 deg).
 *   3. Fire pin-drop solenoid for 400 ms.
 *   4. Return to idle.
 *
 * Written by a tidy engineer. Arduino core only, no libraries beyond Servo.
 */

#include <Servo.h>

// ---- Pin assignments ----
const uint8_t PIN_BUTTON   = 2;   // start button, active LOW (INPUT_PULLUP)
const uint8_t PIN_SERVO    = 9;   // rake sweep servo
const uint8_t PIN_SOLENOID = 7;   // pin-drop relay
const uint8_t PIN_STATUS   = 13;  // onboard status LED

// ---- Timing constants (ms) ----
const unsigned long SWEEP_TIME_MS   = 1200;  // time for full 90 deg sweep
const unsigned long SWEEP_HOLD_MS   = 300;   // pause at far end
const unsigned long SOLENOID_MS     = 400;   // pin-drop pulse width
const unsigned long DEBOUNCE_MS     = 50;    // button debounce window
const unsigned long BLINK_MS        = 250;   // status blink half-period

// ---- Servo positions (degrees) ----
const int RAKE_HOME = 0;
const int RAKE_OUT  = 90;

Servo rakeServo;

bool          cycleRunning = false;
unsigned long lastBlink    = 0;
bool          ledState     = false;

void setup() {
  pinMode(PIN_BUTTON, INPUT_PULLUP);
  pinMode(PIN_SOLENOID, OUTPUT);
  pinMode(PIN_STATUS, OUTPUT);
  digitalWrite(PIN_SOLENOID, LOW);

  rakeServo.attach(PIN_SERVO);
  rakeServo.write(RAKE_HOME);

  digitalWrite(PIN_STATUS, HIGH);  // solid = idle
}

void loop() {
  if (!cycleRunning && buttonPressed()) {
    runResetCycle();
  }
  updateStatusLed();
}

// Debounced active-low button check.
bool buttonPressed() {
  if (digitalRead(PIN_BUTTON) == LOW) {
    delay(DEBOUNCE_MS);
    if (digitalRead(PIN_BUTTON) == LOW) {
      while (digitalRead(PIN_BUTTON) == LOW) {
        // wait for release so one press = one cycle
      }
      return true;
    }
  }
  return false;
}

// Full sweep + drop sequence. Blocking by design for simplicity.
void runResetCycle() {
  cycleRunning = true;

  // 1. Sweep rake out to the far end.
  sweepTo(RAKE_OUT, SWEEP_TIME_MS);
  delay(SWEEP_HOLD_MS);

  // 2. Sweep rake back home.
  sweepTo(RAKE_HOME, SWEEP_TIME_MS);

  // 3. Drop a fresh set of pins.
  digitalWrite(PIN_SOLENOID, HIGH);
  delay(SOLENOID_MS);
  digitalWrite(PIN_SOLENOID, LOW);

  cycleRunning = false;
}

// Move the servo gradually so the rake does not slam.
void sweepTo(int targetDeg, unsigned long durationMs) {
  int startDeg = rakeServo.read();
  int steps    = abs(targetDeg - startDeg);
  if (steps == 0) return;

  unsigned long stepDelay = durationMs / steps;
  int dir = (targetDeg > startDeg) ? 1 : -1;

  for (int i = 0; i < steps; i++) {
    rakeServo.write(startDeg + dir * (i + 1));
    delay(stepDelay);
  }
}

// Blink while running, solid when idle.
void updateStatusLed() {
  if (cycleRunning) {
    if (millis() - lastBlink >= BLINK_MS) {
      lastBlink = millis();
      ledState  = !ledState;
      digitalWrite(PIN_STATUS, ledState ? HIGH : LOW);
    }
  } else {
    digitalWrite(PIN_STATUS, HIGH);
    ledState = true;
  }
}

#include <Servo.h>

const uint8_t BTN_PIN = 2;
const uint8_t SERVO_PIN = 9;
const uint8_t LED_PIN = 13;
const uint8_t BUZZ_PIN = 8;

const unsigned long DEBOUNCE_MS = 25;
const unsigned long OPEN_MS = 4000;
const unsigned long CLOSE_MS = 1200;

Servo guard;
bool guardOpen = false;
bool lastBtn = HIGH;
unsigned long lastChange = 0;
unsigned long openStart = 0;

void setup() {
  pinMode(BTN_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZZ_PIN, OUTPUT);
  guard.attach(SERVO_PIN);
  guard.write(0);
  digitalWrite(LED_PIN, LOW);
  digitalWrite(BUZZ_PIN, LOW);
}

void beep(uint16_t ms) {
  digitalWrite(BUZZ_PIN, HIGH);
  delay(ms);
  digitalWrite(BUZZ_PIN, LOW);
}

void openGuard() {
  beep(80);
  guard.write(90);
  guardOpen = true;
  openStart = millis();
  digitalWrite(LED_PIN, HIGH);
}

void closeGuard() {
  guard.write(0);
  guardOpen = false;
  digitalWrite(LED_PIN, LOW);
  beep(40);
}

void loop() {
  bool btn = digitalRead(BTN_PIN);
  unsigned long now = millis();

  if (btn != lastBtn && (now - lastChange) > DEBOUNCE_MS) {
    lastChange = now;
    lastBtn = btn;
    if (btn == LOW) {
      if (!guardOpen) {
        openGuard();
      } else {
        closeGuard();
      }
    }
  }

  if (guardOpen && (now - openStart) > OPEN_MS) {
    closeGuard();
  }

  delay(5);
}

// Canal Lock Model - beginner project
// This controls a model canal lock with two gates and a water pump.
// I'm writing lots of comments because I'm still learning.

// Pin assignments - change these if your wiring is different
const int gateOpenBtn = 2;   // button to open the upstream gate
const int gateCloseBtn = 3;  // button to close the upstream gate
const int pumpBtn = 4;       // button to start/stop the pump

const int gateMotor = 9;     // PWM to the gate motor driver
const int pumpMotor = 10;    // PWM to the pump driver

// We ignore the downstream gate for now - the model only has one
// working gate, the other one is glued shut. Don't worry about it.

int gateState = 0;   // 0 = closed, 1 = open
int pumpState = 0;   // 0 = off, 1 = on

void setup() {
  // Buttons use internal pull-ups, so they read LOW when pressed.
  // That confused me at first - remember LOW means pressed!
  pinMode(gateOpenBtn, INPUT_PULLUP);
  pinMode(gateCloseBtn, INPUT_PULLUP);
  pinMode(pumpBtn, INPUT_PULLUP);

  pinMode(gateMotor, OUTPUT);
  pinMode(pumpMotor, OUTPUT);

  // Make sure everything starts off
  analogWrite(gateMotor, 0);
  analogWrite(pumpMotor, 0);

  Serial.begin(9600);
  Serial.println("Canal lock ready");
}

void loop() {
  // Read the buttons. LOW = pressed because of pull-ups.
  if (digitalRead(gateOpenBtn) == LOW) {
    gateState = 1;
    Serial.println("Gate opening");
    delay(300);  // crude debounce, ignore the proper way for now
  }

  if (digitalRead(gateCloseBtn) == LOW) {
    gateState = 0;
    Serial.println("Gate closing");
    delay(300);
  }

  if (digitalRead(pumpBtn) == LOW) {
    pumpState = !pumpState;  // toggle the pump on and off
    Serial.print("Pump now ");
    Serial.println(pumpState ? "ON" : "OFF");
    delay(300);
  }

  // Drive the gate motor. 180 is a guess at a good speed.
  // If the gate slams, lower this number.
  if (gateState == 1) {
    analogWrite(gateMotor, 180);
  } else {
    analogWrite(gateMotor, 0);
  }

  // Pump runs at full speed when on.
  if (pumpState == 1) {
    analogWrite(pumpMotor, 255);
  } else {
    analogWrite(pumpMotor, 0);
  }

  // Small delay so the loop doesn't spin too fast.
  delay(20);
}

/*
 * Candle Wax Melter Thermostat
 *
 * Keeps a wax melter plate at a target temperature using a
 * thermistor on A0 and a relay on D7. The relay is active-low
 * (LOW = heater on), which is common for cheap relay modules.
 *
 * Design notes:
 *  - Thermistor is a 10k NTC in a divider with a 10k resistor to 5V.
 *  - Beta equation is used; good enough for a melter.
 *  - Simple bang-bang control with hysteresis to avoid relay chatter.
 *  - Serial prints temperature once per second for tuning.
 */

const uint8_t THERMISTOR_PIN = A0;
const uint8_t RELAY_PIN = 7;

const float SERIES_RESISTOR = 10000.0;
const float NOMINAL_RESISTANCE = 10000.0;
const float NOMINAL_TEMPERATURE = 25.0;
const float BETA_COEFFICIENT = 3950.0;

const float TARGET_C = 65.0;
const float HYSTERESIS_C = 2.0;

const unsigned long PRINT_INTERVAL_MS = 1000;
unsigned long lastPrintMs = 0;

bool heaterOn = false;

float readTemperatureC() {
  int raw = analogRead(THERMISTOR_PIN);
  if (raw <= 0) raw = 1;
  if (raw >= 1023) raw = 1022;

  float resistance = SERIES_RESISTOR * (float)raw / (1023.0 - (float)raw);
  float steinhart = resistance / NOMINAL_RESISTANCE;
  steinhart = log(steinhart);
  steinhart /= BETA_COEFFICIENT;
  steinhart += 1.0 / (NOMINAL_TEMPERATURE + 273.15);
  steinhart = 1.0 / steinhart;
  return steinhart - 273.15;
}

void setHeater(bool on) {
  heaterOn = on;
  digitalWrite(RELAY_PIN, on ? LOW : HIGH);
}

void setup() {
  pinMode(RELAY_PIN, OUTPUT);
  setHeater(false);
  Serial.begin(9600);
  Serial.println(F("Wax melter thermostat ready"));
}

void loop() {
  float tempC = readTemperatureC();

  if (!heaterOn && tempC < TARGET_C - HYSTERESIS_C) {
    setHeater(true);
  } else if (heaterOn && tempC > TARGET_C + HYSTERESIS_C) {
    setHeater(false);
  }

  unsigned long now = millis();
  if (now - lastPrintMs >= PRINT_INTERVAL_MS) {
    lastPrintMs = now;
    Serial.print(F("Temp: "));
    Serial.print(tempC, 1);
    Serial.print(F(" C  Heater: "));
    Serial.println(heaterOn ? F("ON") : F("OFF"));
  }

  delay(50);
}

