/*
 * Car Wash Bay Timer
 * -------------------
 * A customer presses the START button; the bay's solenoid valve opens
 * and a countdown runs on a 4-digit display (multiplexed, common cathode).
 * Design notes:
 *   - Time is kept in whole seconds; the loop is non-blocking.
 *   - The valve is fail-safe: it closes on timeout, on STOP, or on reset.
 *   - Display refresh happens every loop pass; digits are lit one at a time.
 *   - A short beep marks the last 10 seconds.
 * Written by a tidy engineer. Arduino core only.
 */

const uint8_t START_PIN   = 2;   // active LOW, internal pull-up
const uint8_t STOP_PIN    = 3;   // active LOW, internal pull-up
const uint8_t VALVE_PIN   = 8;   // relay, HIGH = valve open
const uint8_t BUZZER_PIN  = 9;

// 4-digit multiplexed display: segment pins A..G then DP
const uint8_t SEG_PINS[8] = {4, 5, 6, 7, 10, 11, 12, 13};
const uint8_t DIGIT_PINS[4] = {A0, A1, A2, A3}; // common cathodes, LOW = on

const uint16_t BAY_SECONDS = 300;   // 5 minutes per wash
const uint16_t WARN_SECONDS = 10;   // beep during final 10 s
const uint16_t DEBOUNCE_MS = 30;

// Segment patterns for 0-9, bit0 = A ... bit6 = G
const uint8_t DIGIT_MAP[10] = {
  0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F
};

uint16_t remaining = 0;
bool running = false;
unsigned long lastTick = 0;
unsigned long lastBeep = 0;
bool beepOn = false;

void setup() {
  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(VALVE_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(VALVE_PIN, LOW);
  for (uint8_t i = 0; i < 8; i++) pinMode(SEG_PINS[i], OUTPUT);
  for (uint8_t i = 0; i < 4; i++) {
    pinMode(DIGIT_PINS[i], OUTPUT);
    digitalWrite(DIGIT_PINS[i], HIGH); // off
  }
}

void loop() {
  unsigned long now = millis();

  if (digitalRead(START_PIN) == LOW) {
    delay(DEBOUNCE_MS);
    if (digitalRead(START_PIN) == LOW) {
      remaining = BAY_SECONDS;
      running = true;
      lastTick = now;
      digitalWrite(VALVE_PIN, HIGH);
      while (digitalRead(START_PIN) == LOW) { /* wait for release */ }
    }
  }

  if (digitalRead(STOP_PIN) == LOW) {
    running = false;
    remaining = 0;
    digitalWrite(VALVE_PIN, LOW);
  }

  if (running && now - lastTick >= 1000UL) {
    lastTick += 1000UL;
    if (remaining > 0) remaining--;
    if (remaining == 0) {
      running = false;
      digitalWrite(VALVE_PIN, LOW);
    }
  }

  // Beep once per second during the warning window.
  if (running && remaining <= WARN_SECONDS && remaining > 0) {
    if (now - lastBeep >= 500UL) {
      lastBeep = now;
      beepOn = !beepOn;
      digitalWrite(BUZZER_PIN, beepOn ? HIGH : LOW);
    }
  } else {
    digitalWrite(BUZZER_PIN, LOW);
    beepOn = false;
  }

  refreshDisplay(remaining);
}

void refreshDisplay(uint16_t secs) {
  uint8_t digits[4];
  digits[0] = (secs / 60) / 10;
  digits[1] = (secs / 60) % 10;
  digits[2] = (secs % 60) / 10;
  digits[3] = (secs % 60) % 10;

  for (uint8_t d = 0; d < 4; d++) {
    for (uint8_t i = 0; i < 4; i++) digitalWrite(DIGIT_PINS[i], HIGH);
    uint8_t pat = DIGIT_MAP[digits[d] % 10];
    for (uint8_t s = 0; s < 7; s++) {
      digitalWrite(SEG_PINS[s], (pat >> s) & 1);
    }
    digitalWrite(SEG_PINS[7], LOW); // decimal point off
    digitalWrite(DIGIT_PINS[d], LOW);
    delay(2);
  }
}

const uint8_t SEND_PIN = 2;
const uint8_t ECHO_PIN = 3;
const uint8_t LED_PIN = 13;

const float TANK_DEPTH_CM = 60.0;
const float SENSOR_OFFSET_CM = 5.0;
const float EMPTY_CM = 55.0;

unsigned long lastRead = 0;
const unsigned long READ_MS = 500;

float readDistanceCm() {
  digitalWrite(SEND_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(SEND_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(SEND_PIN, LOW);
  unsigned long dur = pulseIn(ECHO_PIN, HIGH, 30000UL);
  if (dur == 0) return -1.0;
  return dur * 0.0343 / 2.0;
}

void setup() {
  pinMode(SEND_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
  Serial.println(F("Tank gauge v1"));
}

void loop() {
  if (millis() - lastRead < READ_MS) return;
  lastRead = millis();

  float d = readDistanceCm();
  if (d < 0) {
    Serial.println(F("err"));
    return;
  }

  float level = EMPTY_CM - (d - SENSOR_OFFSET_CM);
  if (level < 0) level = 0;
  if (level > TANK_DEPTH_CM) level = TANK_DEPTH_CM;

  int pct = (int)((level / TANK_DEPTH_CM) * 100.0 + 0.5);

  Serial.print(F("d="));
  Serial.print(d, 1);
  Serial.print(F(" lvl="));
  Serial.print(level, 1);
  Serial.print(F(" pct="));
  Serial.println(pct);

  digitalWrite(LED_PIN, pct < 15 ? HIGH : LOW);
}

/*
 * Carousel Speed Governor
 * ------------------------
 * Measures the rotation period of a carousel using a hall-effect
 * sensor (or reed switch) that pulses once per revolution.
 *
 * Design notes:
 *  - We time the interval between successive pulses with micros().
 *  - A simple proportional governor drives a PWM output to a
 *    motor driver: too slow -> more PWM, too fast -> less PWM.
 *  - The first revolution is ignored because we have no previous
 *    timestamp yet.
 *  - A timeout resets the measurement if the carousel stalls.
 *
 * Wiring:
 *  - Sensor signal -> D2 (INT0), INPUT_PULLUP, active LOW.
 *  - Motor driver PWM -> D9 (Timer1, ~490 Hz).
 *  - Status LED -> D13.
 */

const uint8_t  SENSOR_PIN      = 2;
const uint8_t  MOTOR_PIN       = 9;
const uint8_t  LED_PIN         = 13;

const uint32_t TARGET_PERIOD_US = 2000000UL;  // 2 s per revolution = 30 rpm
const uint32_t STALL_TIMEOUT_US = 5000000UL;  // 5 s without a pulse = stalled

const int PWM_MIN = 0;
const int PWM_MAX = 255;
const int PWM_START = 120;

const float KP = 0.00008;  // PWM counts per microsecond of error

volatile uint32_t lastPulseUs = 0;
volatile uint32_t periodUs    = 0;
volatile bool     newPeriod   = false;

int pwmOut = PWM_START;

void onPulse() {
  uint32_t now = micros();
  if (lastPulseUs != 0) {
    periodUs  = now - lastPulseUs;
    newPeriod = true;
  }
  lastPulseUs = now;
}

void setup() {
  pinMode(SENSOR_PIN, INPUT_PULLUP);
  pinMode(MOTOR_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);

  attachInterrupt(digitalPinToInterrupt(SENSOR_PIN), onPulse, FALLING);

  analogWrite(MOTOR_PIN, pwmOut);
}

void loop() {
  static uint32_t lastCheckUs = 0;
  uint32_t now = micros();

  // Stall detection: no pulse for too long.
  if (lastPulseUs != 0 && (now - lastPulseUs) > STALL_TIMEOUT_US) {
    pwmOut = PWM_MAX;  // kick it
    lastPulseUs = now;
    digitalWrite(LED_PIN, HIGH);
  }

  if (newPeriod) {
    noInterrupts();
    uint32_t p = periodUs;
    newPeriod = false;
    interrupts();

    float error = (float)TARGET_PERIOD_US - (float)p;
    float adj   = KP * error;

    pwmOut += (int)adj;
    if (pwmOut < PWM_MIN) pwmOut = PWM_MIN;
    if (pwmOut > PWM_MAX) pwmOut = PWM_MAX;

    analogWrite(MOTOR_PIN, pwmOut);
    digitalWrite(LED_PIN, LOW);
  }

  // Housekeeping tick, keeps loop from spinning too hot.
  if (now - lastCheckUs > 10000UL) {
    lastCheckUs = now;
  }
}

// cheese cave humidifier
// DHT22 on pin 2, relay on pin 7, status LED on 13

#include <DHT.h>

#define DHTPIN 2
#define DHTTYPE DHT22
#define RELAY 7
#define LED 13

DHT dht(DHTPIN, DHTTYPE);

const float targetLow = 80.0;   // start misting below this RH
const float targetHigh = 88.0;  // stop above this
const unsigned long minOn = 20000;   // don't short-cycle the mist maker
const unsigned long minOff = 60000;

bool misting = false;
unsigned long lastSwitch = 0;
float humidity = 0;

void setup() {
  pinMode(RELAY, OUTPUT);
  pinMode(LED, OUTPUT);
  digitalWrite(RELAY, LOW);
  digitalWrite(LED, LOW);
  Serial.begin(9600);
  dht.begin();
  delay(2000); // sensor settle
}

void loop() {
  // read every 2.5s, DHT22 is slow
  static unsigned long lastRead = 0;
  if (millis() - lastRead > 2500) {
    lastRead = millis();
    float h = dht.readHumidity();
    if (!isnan(h)) {
      humidity = h;
    }
    Serial.print("RH: ");
    Serial.println(humidity);
  }

  unsigned long now = millis();

  if (!misting && humidity < targetLow) {
    if (now - lastSwitch > minOff) {
      misting = true;
      lastSwitch = now;
      digitalWrite(RELAY, HIGH);
      digitalWrite(LED, HIGH);
    }
  } else if (misting && humidity > targetHigh) {
    if (now - lastSwitch > minOn) {
      misting = false;
      lastSwitch = now;
      digitalWrite(RELAY, LOW);
      digitalWrite(LED, LOW);
    }
  }

  // safety: never mist longer than 5 min straight
  if (misting && now - lastSwitch > 300000UL) {
    misting = false;
    lastSwitch = now;
    digitalWrite(RELAY, LOW);
    digitalWrite(LED, LOW);
  }
}

// Chromatography Pump Timer
// Written by a beginner, so lots of comments. Sorry in advance.

// We use pin 7 to drive the pump relay. The relay module is active-LOW
// (most cheap blue relay boards are), so LOW = pump ON, HIGH = pump OFF.
const int PUMP_PIN = 7;

// Start button on pin 2, wired to GND with the internal pullup enabled.
// So the pin reads HIGH when idle and LOW when pressed.
const int START_BTN = 2;

// Stop button on pin 3, same wiring.
const int STOP_BTN = 3;

// How long the pump runs, in milliseconds. 90 seconds for now.
// Change this number if you want a different run time.
const unsigned long RUN_TIME_MS = 90000UL;

// Ignore the analog pins and the onboard LED for now, we don't need them.
// Also ignore debouncing libraries - we do a crude delay-based debounce below.

unsigned long startTime = 0;
bool pumping = false;

void setup() {
  // Relay pin is an output. Set it HIGH first so the pump stays OFF
  // during boot (active-low relay, remember).
  pinMode(PUMP_PIN, OUTPUT);
  digitalWrite(PUMP_PIN, HIGH);

  // Buttons are inputs with pullups, so no external resistors needed.
  pinMode(START_BTN, INPUT_PULLUP);
  pinMode(STOP_BTN, INPUT_PULLUP);

  // Serial is just for debugging. You can ignore it in normal use.
  Serial.begin(9600);
  Serial.println("Pump timer ready");
}

void loop() {
  // Check the stop button first - safety first!
  if (digitalRead(STOP_BTN) == LOW) {
    delay(30); // crude debounce, ignore bounce for 30 ms
    if (digitalRead(STOP_BTN) == LOW) {
      stopPump();
      // Wait for the button to be released so we don't spam stopPump().
      while (digitalRead(STOP_BTN) == LOW) {
        delay(10);
      }
    }
  }

  // Start button only works if we are not already pumping.
  if (!pumping && digitalRead(START_BTN) == LOW) {
    delay(30);
    if (digitalRead(START_BTN) == LOW) {
      startPump();
      while (digitalRead(START_BTN) == LOW) {
        delay(10);
      }
    }
  }

  // If pumping, check whether the run time has elapsed.
  // Using millis() instead of delay() so the stop button still works.
  if (pumping) {
    unsigned long elapsed = millis() - startTime;
    if (elapsed >= RUN_TIME_MS) {
      stopPump();
      Serial.println("Run complete");
    }
  }
}

void startPump() {
  digitalWrite(PUMP_PIN, LOW); // LOW turns the relay ON
  pumping = true;
  startTime = millis();
  Serial.println("Pump started");
}

void stopPump() {
  digitalWrite(PUMP_PIN, HIGH); // HIGH turns the relay OFF
  pumping = false;
  Serial.println("Pump stopped");
}

// Coffee Roaster Drum Timer
// Written by a beginner. This sketch runs a drum motor for a set time
// and beeps when the roast is done. Read the comments, they explain things.

// --- Pin setup ---
// The motor driver's signal pin goes to pin 9 (PWM capable, but we just use HIGH/LOW).
const int motorPin = 9;
// The start button goes to pin 2. We use INPUT_PULLUP so we don't need a resistor.
// IMPORTANT: with INPUT_PULLUP, the button reads LOW when pressed. Don't forget that!
const int buttonPin = 2;
// The buzzer goes to pin 8.
const int buzzerPin = 8;
// A status LED on pin 13 (the one on the board, handy for testing).
const int ledPin = 13;

// --- Timing ---
// Roast time in milliseconds. 8 minutes = 8 * 60 * 1000 = 480000 ms.
// Change this number if you want a longer or shorter roast.
const unsigned long roastTime = 480000UL;

// Variables to remember state between loops.
// 'unsigned long' because millis() gets big and a normal int would overflow.
unsigned long startTime = 0;
bool roasting = false;

// We remember the last button reading so we only react to a fresh press.
// (Ignore this if you don't care about double-triggering, but it's good practice.)
int lastButton = HIGH;

void setup() {
  // Set the motor pin as an output so we can drive it.
  pinMode(motorPin, OUTPUT);
  // Button pin as input with the internal pull-up resistor enabled.
  pinMode(buttonPin, INPUT_PULLUP);
  // Buzzer and LED are outputs.
  pinMode(buzzerPin, OUTPUT);
  pinMode(ledPin, OUTPUT);

  // Make sure everything starts off.
  digitalWrite(motorPin, LOW);
  digitalWrite(buzzerPin, LOW);
  digitalWrite(ledPin, LOW);

  // Open the serial port so we can watch what's happening.
  // You don't have to use this, but it helps when debugging.
  Serial.begin(9600);
  Serial.println("Roaster ready. Press the button to start.");
}

void loop() {
  // Read the button. Remember: LOW means pressed because of INPUT_PULLUP.
  int button = digitalRead(buttonPin);

  // Only start if the button was just pressed (went from HIGH to LOW)
  // and we aren't already roasting. Ignore holding the button down.
  if (button == LOW && lastButton == HIGH && !roasting) {
    roasting = true;
    startTime = millis();
    digitalWrite(motorPin, HIGH);
    digitalWrite(ledPin, HIGH);
    Serial.println("Roasting started!");
  }
  lastButton = button;

  // If we are roasting, check whether the time is up.
  if (roasting) {
    // millis() wraps around after about 49 days, but a roast is way shorter,
    // so plain subtraction is fine here.
    if (millis() - startTime >= roastTime) {
      // Time's up: stop the motor and LED.
      digitalWrite(motorPin, LOW);
      digitalWrite(ledPin, LOW);
      roasting = false;
      Serial.println("Roast done!");

      // Beep three times so you hear it from across the room.
      for (int i = 0; i < 3; i++) {
        digitalWrite(buzzerPin, HIGH);
        delay(200);
        digitalWrite(buzzerPin, LOW);
        delay(200);
      }
    }
  }
}

// Darkroom safelight timer
// Press button, safelight turns on for set time then off

const int LED_PIN = 9;      // safelight relay/LED
const int BUTTON_PIN = 2;   // start button
const int POT_PIN = A0;     // time adjust

const unsigned long MIN_TIME = 5000;   // 5 sec
const unsigned long MAX_TIME = 120000; // 2 min

bool running = false;
unsigned long startMillis = 0;
unsigned long runTime = 0;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  digitalWrite(LED_PIN, LOW);
  Serial.begin(9600);
}

void loop() {
  // read pot and map to time
  int potVal = analogRead(POT_PIN);
  unsigned long setTime = map(potVal, 0, 1023, MIN_TIME, MAX_TIME);

  // button pressed (active low)
  if (digitalRead(BUTTON_PIN) == LOW && !running) {
    delay(20); // debounce
    if (digitalRead(BUTTON_PIN) == LOW) {
      running = true;
      runTime = setTime;
      startMillis = millis();
      digitalWrite(LED_PIN, HIGH);
      Serial.print("Start, time ms: ");
      Serial.println(runTime);
      while (digitalRead(BUTTON_PIN) == LOW) {
        // wait for release
      }
    }
  }

  if (running) {
    if (millis() - startMillis >= runTime) {
      digitalWrite(LED_PIN, LOW);
      running = false;
      Serial.println("Done");
    }
  }
}

/*
 * Dental Chair Lamp Timer
 * ------------------------
 * The lamp on a dental chair should switch itself off after a set
 * period so it does not cook the patient or waste bulb life.
 *
 * Design:
 *  - A push button toggles the lamp on/off.
 *  - When on, the lamp runs for LAMP_ON_MS, then turns off.
 *  - Pressing the button while on resets the timer (restart the period).
 *  - A status LED mirrors the lamp output.
 *  - Debounce is done with a simple millis() timestamp.
 *
 * Written with the Arduino core only; no external libraries.
 */

const uint8_t  BUTTON_PIN      = 2;      // active-low push button to GND
const uint8_t  LAMP_PIN        = 9;      // drives relay / MOSFET gate
const uint8_t  STATUS_LED_PIN  = 13;     // onboard LED mirrors lamp

const uint32_t LAMP_ON_MS      = 120000UL; // 2 minutes of light
const uint32_t DEBOUNCE_MS     = 30UL;

bool     lampOn        = false;
uint32_t lampStartMs   = 0;

int      lastButtonRead = HIGH;
uint32_t lastChangeMs   = 0;

void setLamp(bool on) {
  lampOn = on;
  digitalWrite(LAMP_PIN, on ? HIGH : LOW);
  digitalWrite(STATUS_LED_PIN, on ? HIGH : LOW);
  if (on) {
    lampStartMs = millis();
  }
}

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LAMP_PIN, OUTPUT);
  pinMode(STATUS_LED_PIN, OUTPUT);
  setLamp(false);
}

void loop() {
  // --- debounced button handling ---
  int reading = digitalRead(BUTTON_PIN);
  if (reading != lastButtonRead) {
    lastChangeMs = millis();
    lastButtonRead = reading;
  }

  if ((millis() - lastChangeMs) > DEBOUNCE_MS) {
    static int stableState = HIGH;
    if (reading != stableState) {
      stableState = reading;
      if (stableState == LOW) {          // button pressed
        if (lampOn) {
          // Already on: restart the timer instead of turning off.
          lampStartMs = millis();
        } else {
          setLamp(true);
        }
      }
    }
  }

  // --- auto-off timeout ---
  if (lampOn && (millis() - lampStartMs >= LAMP_ON_MS)) {
    setLamp(false);
  }
}

const uint8_t BUZ = 9;
const uint8_t BTN = 2;
const uint8_t LED = 13;

const unsigned long DEBOUNCE = 25;
const unsigned long BEEP_ON = 180;
const unsigned long BEEP_OFF = 120;
const uint8_t BEEPS = 3;
const unsigned long HOLD_MS = 4000;

bool lastRaw = HIGH;
bool stable = HIGH;
unsigned long lastEdge = 0;
unsigned long pressStart = 0;
bool pressed = false;

uint8_t beepCount = 0;
bool buzOn = false;
unsigned long buzTimer = 0;
bool alarm = false;

void setup() {
  pinMode(BUZ, OUTPUT);
  pinMode(LED, OUTPUT);
  pinMode(BTN, INPUT_PULLUP);
  digitalWrite(BUZ, LOW);
  digitalWrite(LED, LOW);
  Serial.begin(9600);
}

void loop() {
  bool raw = digitalRead(BTN);
  unsigned long now = millis();

  if (raw != lastRaw) {
    lastEdge = now;
    lastRaw = raw;
  }
  if ((now - lastEdge) > DEBOUNCE && raw != stable) {
    stable = raw;
    if (stable == LOW) {
      pressed = true;
      pressStart = now;
      Serial.println(F("press"));
    } else {
      pressed = false;
      Serial.println(F("release"));
    }
  }

  if (pressed && !alarm && (now - pressStart) > HOLD_MS) {
    alarm = true;
    beepCount = 0;
    buzOn = true;
    buzTimer = now;
    digitalWrite(BUZ, HIGH);
    digitalWrite(LED, HIGH);
    Serial.println(F("alarm"));
  }

  if (alarm) {
    if (buzOn && (now - buzTimer) >= BEEP_ON) {
      buzOn = false;
      buzTimer = now;
      digitalWrite(BUZ, LOW);
      beepCount++;
      if (beepCount >= BEEPS) {
        alarm = false;
        digitalWrite(LED, LOW);
        Serial.println(F("done"));
      }
    } else if (!buzOn && (now - buzTimer) >= BEEP_OFF) {
      buzOn = true;
      buzTimer = now;
      digitalWrite(BUZ, HIGH);
    }
  }
}

// Escape Room Lock Puzzle
// Written by a beginner, so lots of comments. Read them!

// ---- PIN SETUP ----
// The keypad is wired as 4 rows and 4 columns.
// Rows go to pins 2,3,4,5. Columns go to pins 6,7,8,9.
// IGNORE the fact that some keypads have 3 columns; ours has 4.
const int rowPins[4] = {2, 3, 4, 5};
const int colPins[4] = {6, 7, 8, 9};

// The secret code is 1-2-3-4. Change this if you want.
const char secretCode[] = "1234";
char entered[5];      // 4 digits plus a null terminator
int enteredCount = 0;

// The lock solenoid is on pin 10. HIGH = unlocked.
const int lockPin = 10;

// Green LED on pin 11, red LED on pin 12.
// IGNORE the buzzer on pin 13 for now, we don't use it.
const int greenLed = 11;
const int redLed = 12;

// This is the keypad layout. Each row is one row of buttons.
const char keys[4][4] = {
  {'1', '2', '3', 'A'},
  {'4', '5', '6', 'B'},
  {'7', '8', '9', 'C'},
  {'*', '0', '#', 'D'}
};

void setup() {
  // Set up the row pins as outputs and drive them HIGH.
  for (int i = 0; i < 4; i++) {
    pinMode(rowPins[i], OUTPUT);
    digitalWrite(rowPins[i], HIGH);
  }
  // Column pins are inputs with pull-ups. A pressed button pulls one LOW.
  for (int i = 0; i < 4; i++) {
    pinMode(colPins[i], INPUT_PULLUP);
  }
  pinMode(lockPin, OUTPUT);
  digitalWrite(lockPin, LOW);   // start locked
  pinMode(greenLed, OUTPUT);
  pinMode(redLed, OUTPUT);
  digitalWrite(greenLed, LOW);
  digitalWrite(redLed, LOW);
  Serial.begin(9600);           // handy for debugging
}

// This function scans the keypad and returns the pressed key, or 0 if none.
char scanKeypad() {
  for (int r = 0; r < 4; r++) {
    // Drive one row LOW at a time.
    digitalWrite(rowPins[r], LOW);
    for (int c = 0; c < 4; c++) {
      if (digitalRead(colPins[c]) == LOW) {
        delay(20);              // simple debounce, not perfect
        if (digitalRead(colPins[c]) == LOW) {
          digitalWrite(rowPins[r], HIGH);  // restore row
          return keys[r][c];
        }
      }
    }
    digitalWrite(rowPins[r], HIGH);
  }
  return 0;
}

void loop() {
  char key = scanKeypad();
  if (key == 0) return;         // nothing pressed, keep waiting

  Serial.print("Key: ");
  Serial.println(key);

  if (key == '*') {
    // Star clears whatever was typed so far.
    enteredCount = 0;
    entered[0] = '\0';
    return;
  }

  if (key == '#') {
    // Hash submits the code.
    entered[enteredCount] = '\0';
    if (strcmp(entered, secretCode) == 0) {
      // Correct! Unlock for 5 seconds.
      digitalWrite(lockPin, HIGH);
      digitalWrite(greenLed, HIGH);
      delay(5000);
      digitalWrite(lockPin, LOW);
      digitalWrite(greenLed, LOW);
    } else {
      // Wrong. Flash red for 1 second.
      digitalWrite(redLed, HIGH);
      delay(1000);
      digitalWrite(redLed, LOW);
    }
    enteredCount = 0;
    entered[0] = '\0';
    return;
  }

  // Otherwise it's a digit. Store it if there's room.
  if (enteredCount < 4) {
    entered[enteredCount] = key;
    enteredCount++;
  }
  // IGNORE extra digits after 4; they just get dropped.
}

#include <Arduino.h>

const uint8_t SSR_PIN = 9;
const uint8_t NTC_PIN = A0;
const uint8_t LED_PIN = 13;

const float SETPOINT = 93.0;
const float HYST = 1.5;
const float NTC_R0 = 100000.0;
const float NTC_B = 3950.0;
const float NTC_T0 = 298.15;
const float SERIES_R = 10000.0;

bool heating = false;
unsigned long lastRead = 0;
float tempC = 0.0;

float readTemp() {
  int raw = analogRead(NTC_PIN);
  if (raw <= 0) raw = 1;
  if (raw >= 1023) raw = 1022;
  float rNtc = SERIES_R * (float)raw / (1023.0 - (float)raw);
  float invT = 1.0 / NTC_T0 + (1.0 / NTC_B) * log(rNtc / NTC_R0);
  return (1.0 / invT) - 273.15;
}

void setup() {
  pinMode(SSR_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(SSR_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
  Serial.begin(9600);
}

void loop() {
  if (millis() - lastRead >= 500) {
    lastRead = millis();
    tempC = readTemp();

    if (!heating && tempC < SETPOINT - HYST) {
      heating = true;
    } else if (heating && tempC > SETPOINT + HYST) {
      heating = false;
    }

    digitalWrite(SSR_PIN, heating ? HIGH : LOW);
    digitalWrite(LED_PIN, heating ? HIGH : LOW);

    Serial.print(tempC, 2);
    Serial.print(" C ");
    Serial.println(heating ? "HEAT" : "IDLE");
  }
}

/*
 * Fire Pit Igniter Interlock
 * --------------------------
 * Design notes:
 *  - A momentary push button (active LOW, internal pull-up) requests ignition.
 *  - A thermocouple-style flame sensor drives an analog input; we treat a
 *    reading above FLAME_THRESHOLD as "flame present".
 *  - The igniter relay is only allowed to energize while the button is held
 *    AND no flame is already detected. This prevents dumping gas onto an
 *    already-lit fire.
 *  - A hard safety timeout (MAX_IGNITE_MS) cuts the relay even if the button
 *    sticks, so a jammed button cannot run the igniter forever.
 *  - The onboard LED mirrors relay state for bench testing.
 */

const uint8_t  BUTTON_PIN      = 2;   // to GND when pressed
const uint8_t  FLAME_PIN       = A0;  // analog flame sensor
const uint8_t  RELAY_PIN       = 8;   // igniter relay, active HIGH
const uint8_t  STATUS_LED_PIN  = 13;  // onboard LED

const int      FLAME_THRESHOLD = 400; // ADC counts; tune per sensor
const unsigned long MAX_IGNITE_MS = 8000UL;
const unsigned long DEBOUNCE_MS   = 30UL;

bool          igniting      = false;
unsigned long igniteStartMs = 0;
unsigned long lastEdgeMs    = 0;
int           lastButton    = HIGH;

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(STATUS_LED_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, LOW);
  digitalWrite(STATUS_LED_PIN, LOW);
  Serial.begin(9600);
}

bool flamePresent() {
  return analogRead(FLAME_PIN) > FLAME_THRESHOLD;
}

void setIgniter(bool on) {
  igniting = on;
  digitalWrite(RELAY_PIN, on ? HIGH : LOW);
  digitalWrite(STATUS_LED_PIN, on ? HIGH : LOW);
  if (on) {
    igniteStartMs = millis();
    Serial.println(F("Igniter ON"));
  } else {
    Serial.println(F("Igniter OFF"));
  }
}

void loop() {
  // Debounced button read.
  int raw = digitalRead(BUTTON_PIN);
  if (raw != lastButton) {
    lastEdgeMs = millis();
    lastButton = raw;
  }
  bool buttonHeld = (lastButton == LOW) &&
                    (millis() - lastEdgeMs >= DEBOUNCE_MS);

  bool flame = flamePresent();

  if (buttonHeld && !flame) {
    if (!igniting) {
      setIgniter(true);
    } else if (millis() - igniteStartMs >= MAX_IGNITE_MS) {
      // Safety timeout: button may be stuck.
      setIgniter(false);
    }
  } else {
    if (igniting) {
      setIgniter(false);
    }
  }

  delay(5);
}

/*
 * Fish Ladder Gate Controller
 * ---------------------------
 * Controls a motorized gate at the top of a fish ladder. The gate opens
 * for a fixed "pass window" every time the upstream level sensor sees
 * water above the trigger threshold, then closes again. A limit switch
 * on the gate stops the motor if the gate is already fully open.
 *
 * Design notes:
 *  - Motor is driven through a relay module (active LOW).
 *  - Level sensor is a float switch wired to GND when water is present.
 *  - All timing is non-blocking via millis().
 */

const uint8_t PIN_LEVEL_SENSOR = 2;   // float switch, INPUT_PULLUP, LOW = water
const uint8_t PIN_GATE_LIMIT   = 3;   // limit switch, INPUT_PULLUP, LOW = fully open
const uint8_t PIN_MOTOR_RELAY  = 8;   // relay, LOW = motor runs (opens gate)
const uint8_t PIN_STATUS_LED   = 13;  // onboard LED, mirrors gate state

const unsigned long PASS_WINDOW_MS = 15000UL;  // gate stays open 15 s
const unsigned long MOTOR_MAX_MS   = 20000UL;  // safety cutoff for motor
const unsigned long DEBOUNCE_MS    = 50UL;

enum GateState { GATE_CLOSED, GATE_OPENING, GATE_OPEN, GATE_CLOSING };

GateState state = GATE_CLOSED;
unsigned long stateSince = 0;
unsigned long lastSensorChange = 0;
bool lastSensorReading = HIGH;
bool sensorStable = HIGH;

void setMotor(bool run) {
  // Relay is active LOW.
  digitalWrite(PIN_MOTOR_RELAY, run ? LOW : HIGH);
}

void enterState(GateState next) {
  state = next;
  stateSince = millis();
  switch (state) {
    case GATE_OPENING: setMotor(true);  break;
    case GATE_CLOSING: setMotor(true);  break;
    default:           setMotor(false); break;
  }
  digitalWrite(PIN_STATUS_LED, (state == GATE_OPEN) ? HIGH : LOW);
}

bool waterPresent() {
  // Debounce the float switch so splashes don't chatter the gate.
  bool reading = digitalRead(PIN_LEVEL_SENSOR);
  if (reading != lastSensorReading) {
    lastSensorChange = millis();
    lastSensorReading = reading;
  }
  if ((millis() - lastSensorChange) > DEBOUNCE_MS) {
    sensorStable = reading;
  }
  return sensorStable == LOW;
}

void setup() {
  pinMode(PIN_LEVEL_SENSOR, INPUT_PULLUP);
  pinMode(PIN_GATE_LIMIT, INPUT_PULLUP);
  pinMode(PIN_MOTOR_RELAY, OUTPUT);
  pinMode(PIN_STATUS_LED, OUTPUT);
  setMotor(false);
  digitalWrite(PIN_STATUS_LED, LOW);
  enterState(GATE_CLOSED);
}

void loop() {
  bool water = waterPresent();
  bool atLimit = (digitalRead(PIN_GATE_LIMIT) == LOW);
  unsigned long elapsed = millis() - stateSince;

  switch (state) {
    case GATE_CLOSED:
      if (water) enterState(GATE_OPENING);
      break;

    case GATE_OPENING:
      if (atLimit || elapsed > MOTOR_MAX_MS) {
        enterState(GATE_OPEN);
      }
      break;

    case GATE_OPEN:
      if (elapsed > PASS_WINDOW_MS) enterState(GATE_CLOSING);
      break;

    case GATE_CLOSING:
      // No lower limit switch: run the motor for a fixed close time.
      if (elapsed > MOTOR_MAX_MS) enterState(GATE_CLOSED);
      break;
  }
}

// Forge Blower Speed Knob
// A beginner's sketch: turn a knob, the blower spins faster or slower.
// Written with lots of comments so I remember what everything does.

// --- Pin setup ---
// The potentiometer (the knob) is wired as a voltage divider.
// Its middle wiper goes to A0. The outer legs go to 5V and GND.
const int KNOB_PIN = A0;

// The blower motor is driven through a transistor on pin 9.
// Pin 9 is special: it supports PWM (pulse-width modulation), which is
// how we fake an analog voltage to control motor speed.
const int MOTOR_PIN = 9;

// --- Tuning values ---
// The knob reads 0..1023. The motor wants 0..255.
// We map between them. IGNORE the tiny dead zone at the very bottom:
// below this value the motor just buzzes and doesn't turn, so we cut it off.
const int DEAD_ZONE = 20;   // in 0..255 motor units
const int MAX_SPEED = 255;  // full blast

// A little smoothing so the motor doesn't jitter when the knob is still.
// IGNORE the fact that this is a very simple filter; it's good enough.
int smoothed = 0;

void setup() {
  // The motor pin is an output. The knob pin is an input by default,
  // so we don't strictly need to set it, but I do it anyway to be clear.
  pinMode(MOTOR_PIN, OUTPUT);
  pinMode(KNOB_PIN, INPUT);

  // Start with the blower off. Safety first!
  analogWrite(MOTOR_PIN, 0);

  // Serial is only for debugging. IGNORE it in normal use.
  Serial.begin(9600);
}

void loop() {
  // Step 1: read the knob. This gives 0..1023.
  int raw = analogRead(KNOB_PIN);

  // Step 2: convert to motor range 0..255.
  int speed = map(raw, 0, 1023, 0, MAX_SPEED);

  // Step 3: apply the dead zone. If the knob is barely turned,
  // just stop the motor instead of letting it buzz.
  if (speed < DEAD_ZONE) {
    speed = 0;
  }

  // Step 4: smooth it a little. Move a quarter of the way each loop.
  // This is integer math, so it rounds down. That's fine.
  smoothed = smoothed + (speed - smoothed) / 4;

  // Step 5: send it to the motor.
  analogWrite(MOTOR_PIN, smoothed);

  // Debug print. IGNORE unless you have the Serial Monitor open.
  Serial.print("knob=");
  Serial.print(raw);
  Serial.print("  motor=");
  Serial.println(smoothed);

  // Small delay so the serial output isn't a wall of text.
  delay(50);
}

#include <LiquidCrystal.h>

LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

const int thermPin = A0;
const int heatPin = 9;
const int btnPin = 7;
const int ledPin = 13;

const float RAMP = 2.5;      // C per minute
const float HOLD = 516.0;    // C
const unsigned long HOLD_MS = 1800000UL;

float temp = 0;
float target = 20;
unsigned long lastTick = 0;
unsigned long holdStart = 0;
bool holding = false;
bool done = false;

float readTemp() {
  int raw = analogRead(thermPin);
  float v = raw * 5.0 / 1024.0;
  return (v - 0.5) * 100.0;
}

void setup() {
  pinMode(heatPin, OUTPUT);
  pinMode(ledPin, OUTPUT);
  pinMode(btnPin, INPUT_PULLUP);
  lcd.begin(16, 2);
  lcd.print("Annealer");
  delay(800);
  lcd.clear();
  lastTick = millis();
}

void loop() {
  unsigned long now = millis();
  float dt = (now - lastTick) / 60000.0;
  lastTick = now;

  temp = readTemp();

  if (!done) {
    if (!holding) {
      target += RAMP * dt;
      if (target >= HOLD) {
        target = HOLD;
        holding = true;
        holdStart = now;
      }
    } else {
      if (now - holdStart >= HOLD_MS) {
        done = true;
        holding = false;
      }
    }
  }

  if (done) {
    digitalWrite(heatPin, LOW);
    digitalWrite(ledPin, (now / 500) % 2);
  } else {
    if (temp < target - 1.0) {
      digitalWrite(heatPin, HIGH);
      digitalWrite(ledPin, HIGH);
    } else if (temp > target + 1.0) {
      digitalWrite(heatPin, LOW);
      digitalWrite(ledPin, LOW);
    }
  }

  if (digitalRead(btnPin) == LOW) {
    done = false;
    holding = false;
    target = temp;
    holdStart = 0;
    delay(200);
  }

  lcd.setCursor(0, 0);
  lcd.print("T:");
  lcd.print(temp, 1);
  lcd.print("  ");
  lcd.setCursor(0, 1);
  lcd.print("S:");
  lcd.print(target, 1);
  lcd.print(done ? " D" : (holding ? " H" : " R"));
  lcd.print("   ");

  delay(200);
}

/*
 * Ham Radio Transmit Timeout Timer
 *
 * Purpose: prevent a stuck PTT from holding the transmitter on
 * indefinitely (FCC 97.119 / good operating practice).
 *
 * Design:
 *   - PTT is read on D2 (active LOW, internal pull-up).
 *   - A timeout LED on D13 lights while transmitting.
 *   - If PTT is held longer than MAX_TX_MS, the radio is keyed off
 *     by driving the KEY line (D7) HIGH and the LED blinks until
 *     PTT is released. This is a "soft" lockout: releasing PTT
 *     clears the fault.
 *   - Timing uses millis() so the loop stays responsive.
 */

const uint8_t  PTT_PIN        = 2;   // active LOW
const uint8_t  KEY_PIN        = 7;   // HIGH = unkeyed
const uint8_t  TX_LED_PIN     = 13;

const uint32_t MAX_TX_MS      = 180000UL;  // 3 minutes
const uint32_t BLINK_MS       = 250UL;

bool     transmitting = false;
bool     timedOut     = false;
uint32_t txStartMs    = 0;
uint32_t lastBlinkMs  = 0;
bool     ledState     = false;

void keyOff() {
  digitalWrite(KEY_PIN, HIGH);
}

void keyOn() {
  digitalWrite(KEY_PIN, LOW);
}

void setup() {
  pinMode(PTT_PIN, INPUT_PULLUP);
  pinMode(KEY_PIN, OUTPUT);
  pinMode(TX_LED_PIN, OUTPUT);
  keyOff();
  digitalWrite(TX_LED_PIN, LOW);
}

void loop() {
  bool ptt = (digitalRead(PTT_PIN) == LOW);
  uint32_t now = millis();

  if (ptt && !transmitting) {
    // Rising edge of PTT: start a fresh transmission.
    transmitting = true;
    timedOut     = false;
    txStartMs    = now;
    keyOn();
    digitalWrite(TX_LED_PIN, HIGH);
  }

  if (!ptt && transmitting) {
    // PTT released: end transmission and clear any fault.
    transmitting = false;
    timedOut     = false;
    keyOff();
    digitalWrite(TX_LED_PIN, LOW);
  }

  if (transmitting && !timedOut) {
    if ((now - txStartMs) >= MAX_TX_MS) {
      timedOut = true;
      keyOff();
      lastBlinkMs = now;
      ledState = false;
    }
  }

  if (timedOut) {
    // Blink the LED to show the timeout fault.
    if ((now - lastBlinkMs) >= BLINK_MS) {
      lastBlinkMs = now;
      ledState = !ledState;
      digitalWrite(TX_LED_PIN, ledState ? HIGH : LOW);
    }
  }
}

/*
 * Hovercraft Lift Fan Controller
 * --------------------------------
 * Design notes:
 *  - A single brushless lift fan is driven through an ESC via a servo-style
 *    PWM signal on pin 9 (50 Hz, 1000-2000 us pulse).
 *  - A pushbutton on pin 2 toggles the fan between idle and full lift.
 *  - A potentiometer on A0 trims the lift level (0-100%).
 *  - An LED on pin 13 mirrors the fan state for the operator.
 *  - The ESC is armed by holding the throttle at minimum for 3 seconds
 *    after power-up, per typical ESC arming behavior.
 *  - Button is debounced in software; no external pull-up needed.
 */

#include <Servo.h>

const uint8_t  FAN_PIN        = 9;
const uint8_t  BUTTON_PIN     = 2;
const uint8_t  TRIM_PIN       = A0;
const uint8_t  STATUS_LED_PIN = 13;

const int ESC_MIN_US = 1000;
const int ESC_MAX_US = 2000;

const unsigned long ARM_HOLD_MS    = 3000;
const unsigned long DEBOUNCE_MS    = 30;
const unsigned long TRIM_INTERVAL  = 50;

Servo fan;

bool fanOn = false;
bool lastButtonReading = HIGH;
bool buttonStable = HIGH;
unsigned long lastDebounceTime = 0;
unsigned long lastTrimTime = 0;
unsigned long bootTime = 0;
bool armed = false;
int liftPercent = 60;

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(STATUS_LED_PIN, OUTPUT);
  digitalWrite(STATUS_LED_PIN, LOW);

  fan.attach(FAN_PIN);
  fan.writeMicroseconds(ESC_MIN_US);

  bootTime = millis();
}

void loop() {
  unsigned long now = millis();

  // Arm the ESC: hold minimum throttle for ARM_HOLD_MS.
  if (!armed) {
    fan.writeMicroseconds(ESC_MIN_US);
    if (now - bootTime >= ARM_HOLD_MS) {
      armed = true;
    }
    return;
  }

  readButton(now);
  updateTrim(now);

  int pulse = ESC_MIN_US;
  if (fanOn) {
    pulse = map(liftPercent, 0, 100, ESC_MIN_US, ESC_MAX_US);
  }
  fan.writeMicroseconds(pulse);
  digitalWrite(STATUS_LED_PIN, fanOn ? HIGH : LOW);
}

void readButton(unsigned long now) {
  bool reading = digitalRead(BUTTON_PIN);
  if (reading != lastButtonReading) {
    lastDebounceTime = now;
    lastButtonReading = reading;
  }
  if ((now - lastDebounceTime) > DEBOUNCE_MS && reading != buttonStable) {
    buttonStable = reading;
    if (buttonStable == LOW) {
      fanOn = !fanOn;
    }
  }
}

void updateTrim(unsigned long now) {
  if (now - lastTrimTime < TRIM_INTERVAL) return;
  lastTrimTime = now;
  int raw = analogRead(TRIM_PIN);
  liftPercent = map(raw, 0, 1023, 0, 100);
  liftPercent = constrain(liftPercent, 0, 100);
}

/*
 * Hydroponic pH Doser
 * -------------------
 * Design notes:
 *  - pH is read on A0 as an analog voltage from a standard pH probe module.
 *  - The probe module outputs 2.5 V at pH 7.0 and ~0.18 V per pH unit.
 *  - A peristaltic pump (pH-down solution) is driven through a relay on D7.
 *  - Dosing is time-based: a fixed shot of pump run time per control cycle.
 *  - A safety timeout caps total pump-on time per cycle so a stuck sensor
 *    cannot dump the whole bottle into the reservoir.
 *  - Serial at 9600 baud reports pH and dosing decisions for tuning.
 */

const uint8_t  PH_PIN          = A0;
const uint8_t  PUMP_PIN        = 7;

const float    PH_NEUTRAL_VOLT = 2.50;   // volts at pH 7.00
const float    PH_VOLT_PER_PH  = 0.18;   // volts per pH unit
const float    PH_TARGET       = 5.80;   // nutrient solution setpoint
const float    PH_DEADBAND     = 0.10;   // do not dose inside this band

const uint16_t DOSE_MS         = 1500;   // pump shot per correction
const uint16_t SETTLE_MS       = 10000;  // wait for mixing before re-reading
const uint16_t MAX_DOSE_MS     = 8000;   // hard cap of pump time per cycle

uint16_t cycleDoseMs = 0;

float readPH() {
  // Average a few samples to knock down probe noise.
  uint32_t sum = 0;
  for (uint8_t i = 0; i < 8; i++) {
    sum += analogRead(PH_PIN);
    delay(10);
  }
  float volts = (sum / 8.0) * (5.0 / 1023.0);
  return 7.0 + (PH_NEUTRAL_VOLT - volts) / PH_VOLT_PER_PH;
}

void pumpOn(uint16_t ms) {
  digitalWrite(PUMP_PIN, HIGH);
  delay(ms);
  digitalWrite(PUMP_PIN, LOW);
}

void setup() {
  pinMode(PUMP_PIN, OUTPUT);
  digitalWrite(PUMP_PIN, LOW);
  Serial.begin(9600);
  Serial.println(F("Hydroponic pH doser ready"));
}

void loop() {
  float ph = readPH();
  Serial.print(F("pH = "));
  Serial.println(ph, 2);

  if (ph > PH_TARGET + PH_DEADBAND) {
    if (cycleDoseMs + DOSE_MS <= MAX_DOSE_MS) {
      Serial.println(F("Dosing pH-down"));
      pumpOn(DOSE_MS);
      cycleDoseMs += DOSE_MS;
    } else {
      Serial.println(F("Dose cap reached, waiting"));
    }
    delay(SETTLE_MS);
  } else {
    // Back in band: reset the per-cycle budget.
    cycleDoseMs = 0;
    delay(1000);
  }
}

/*
 * Ice Rink Resurfacer Gate Controller
 * -----------------------------------
 * Design notes:
 *  - A single DC gearmotor raises/lowers the conditioner gate via a relay H-bridge.
 *  - Two limit switches (UP, DOWN) stop travel; both are wired normally-closed
 *    to ground so a broken wire reads as "at limit" (fail-safe).
 *  - A momentary START button begins a resurface pass: gate lowers, waits for
 *    the operator to hold the pass button, then raises when released.
 *  - All timing is non-blocking via millis() so the E-stop is always polled.
 *  - E-stop is normally-closed to ground; opening it cuts drive immediately.
 */

const uint8_t PIN_BTN_START   = 2;   // momentary, to GND, internal pullup
const uint8_t PIN_BTN_PASS    = 3;   // held during pass, to GND, pullup
const uint8_t PIN_LIMIT_UP    = 4;   // NC switch to GND, pullup
const uint8_t PIN_LIMIT_DOWN  = 5;   // NC switch to GND, pullup
const uint8_t PIN_ESTOP       = 6;   // NC switch to GND, pullup
const uint8_t PIN_RELAY_UP    = 7;   // gate raise relay
const uint8_t PIN_RELAY_DOWN  = 8;   // gate lower relay
const uint8_t PIN_LED_READY   = 13;  // onboard LED

const unsigned long DEBOUNCE_MS   = 25;
const unsigned long LOWER_TIMEOUT = 6000;  // max travel time down
const unsigned long RAISE_TIMEOUT = 6000;  // max travel time up

enum GateState { IDLE, LOWERING, WAIT_PASS, PASSING, RAISING, FAULT };
GateState state = IDLE;
unsigned long stateStart = 0;

bool limitUp()   { return digitalRead(PIN_LIMIT_UP)   == LOW; }
bool limitDown() { return digitalRead(PIN_LIMIT_DOWN) == LOW; }
bool estopOk()   { return digitalRead(PIN_ESTOP)      == HIGH; }

void driveStop() {
  digitalWrite(PIN_RELAY_UP, LOW);
  digitalWrite(PIN_RELAY_DOWN, LOW);
}

void driveUp() {
  digitalWrite(PIN_RELAY_DOWN, LOW);
  digitalWrite(PIN_RELAY_UP, HIGH);
}

void driveDown() {
  digitalWrite(PIN_RELAY_UP, LOW);
  digitalWrite(PIN_RELAY_DOWN, HIGH);
}

void enter(GateState s) {
  state = s;
  stateStart = millis();
  driveStop();
}

void setup() {
  pinMode(PIN_BTN_START, INPUT_PULLUP);
  pinMode(PIN_BTN_PASS, INPUT_PULLUP);
  pinMode(PIN_LIMIT_UP, INPUT_PULLUP);
  pinMode(PIN_LIMIT_DOWN, INPUT_PULLUP);
  pinMode(PIN_ESTOP, INPUT_PULLUP);
  pinMode(PIN_RELAY_UP, OUTPUT);
  pinMode(PIN_RELAY_DOWN, OUTPUT);
  pinMode(PIN_LED_READY, OUTPUT);
  driveStop();
  enter(IDLE);
}

void loop() {
  // E-stop always wins.
  if (!estopOk()) {
    enter(FAULT);
    digitalWrite(PIN_LED_READY, (millis() / 250) % 2);
    return;
  }

  switch (state) {
    case IDLE:
      digitalWrite(PIN_LED_READY, HIGH);
      if (digitalRead(PIN_BTN_START) == LOW && !limitDown()) {
        delay(DEBOUNCE_MS);
        if (digitalRead(PIN_BTN_START) == LOW) enter(LOWERING);
      }
      break;

    case LOWERING:
      digitalWrite(PIN_LED_READY, LOW);
      driveDown();
      if (limitDown()) enter(WAIT_PASS);
      else if (millis() - stateStart > LOWER_TIMEOUT) enter(FAULT);
      break;

    case WAIT_PASS:
      if (digitalRead(PIN_BTN_PASS) == LOW) enter(PASSING);
      break;

    case PASSING:
      // Gate stays down; operator drives the machine.
      if (digitalRead(PIN_BTN_PASS) == HIGH) enter(RAISING);
      break;

    case RAISING:
      driveUp();
      if (limitUp()) enter(IDLE);
      else if (millis() - stateStart > RAISE_TIMEOUT) enter(FAULT);
      break;

    case FAULT:
      driveStop();
      digitalWrite(PIN_LED_READY, (millis() / 250) % 2);
      // Recover only when E-stop is restored and gate is up.
      if (estopOk() && limitUp()) enter(IDLE);
      break;
  }
}

// Kiln over-temp cutoff
// Cuts the relay when the thermocouple reading gets too hot.
// Relay is active LOW on pin 7 (LOW = element on).

const int RELAY_PIN = 7;
const int THERMO_PIN = A0;

// 10mV per degree C, 0C at 0V (simplified)
const float MV_PER_DEG = 10.0;

// cutoff at 1200 C, re-enable only after cooling to 1100 C
const float CUTOFF_C = 1200.0;
const float RESET_C = 1100.0;

bool tripped = false;

void setup() {
  pinMode(RELAY_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, HIGH); // relay off at boot
  Serial.begin(9600);
  Serial.println("Kiln cutoff ready");
}

float readTempC() {
  // average a few samples to smooth noise
  long total = 0;
  for (int i = 0; i < 8; i++) {
    total += analogRead(THERMO_PIN);
    delay(5);
  }
  float avg = total / 8.0;
  float volts = avg * (5.0 / 1023.0);
  float mv = volts * 1000.0;
  return mv / MV_PER_DEG;
}

void loop() {
  float temp = readTempC();

  if (!tripped && temp >= CUTOFF_C) {
    tripped = true;
    digitalWrite(RELAY_PIN, HIGH); // kill element
    Serial.print("TRIP at ");
    Serial.print(temp);
    Serial.println(" C");
  }

  if (tripped && temp <= RESET_C) {
    tripped = false;
    digitalWrite(RELAY_PIN, LOW); // element back on
    Serial.print("RESET at ");
    Serial.print(temp);
    Serial.println(" C");
  }

  if (!tripped) {
    digitalWrite(RELAY_PIN, LOW);
  }

  Serial.print("Temp: ");
  Serial.print(temp);
  Serial.print(" C  relay=");
  Serial.println(tripped ? "OFF" : "ON");

  delay(500);
}

// Lathe Spindle Tachometer
// Reads a slotted optical sensor on the spindle and shows RPM on the Serial Monitor.
// Beginner code: lots of comments, some of them just me thinking out loud.

// --- Pin setup ---
// The sensor output goes to pin 2. Why pin 2? Because it is one of the
// interrupt-capable pins on the Uno (2 and 3). We need an interrupt so we
// never miss a pulse even while the loop() is busy doing other things.
const int SENSOR_PIN = 2;

// --- Timing variables ---
// volatile because these get changed inside the interrupt routine.
// If you forget volatile the compiler may cache them and you get garbage.
volatile unsigned long lastPulseMicros = 0;
volatile unsigned long pulsePeriodMicros = 0;
volatile unsigned int pulseCount = 0;

// How many slots (or reflective marks) are on the spindle? I have one.
// If you tape on 4 marks, change this to 4 and the math fixes itself.
const int SLOTS_PER_REV = 1;

// Ignore pulses closer together than this. The sensor can bounce and
// give two edges for one slot. 2000 us = 500 Hz max, which is plenty
// for a lathe that tops out around 2000 RPM with one slot.
const unsigned long DEBOUNCE_MICROS = 2000;

void setup() {
  Serial.begin(9600);
  pinMode(SENSOR_PIN, INPUT_PULLUP); // sensor is open-collector, so pull it up
  attachInterrupt(digitalPinToInterrupt(SENSOR_PIN), onPulse, FALLING);
  Serial.println("Lathe tach ready. Spin the spindle.");
}

// This runs every time the sensor sees a slot edge.
// Keep it SHORT. No Serial.print in here, ever. It will hang the board.
void onPulse() {
  unsigned long now = micros();
  unsigned long gap = now - lastPulseMicros;

  // First pulse ever, or a bounce. Just remember the time and leave.
  if (lastPulseMicros == 0 || gap < DEBOUNCE_MICROS) {
    lastPulseMicros = now;
    return;
  }

  pulsePeriodMicros = gap;
  lastPulseMicros = now;
  pulseCount++;
}

void loop() {
  // Copy the volatile values once so they cannot change mid-calculation.
  noInterrupts();
  unsigned long period = pulsePeriodMicros;
  unsigned int count = pulseCount;
  interrupts();

  // If we have never seen two pulses, there is nothing to report yet.
  if (period == 0) {
    delay(200);
    return;
  }

  // RPM math: one revolution takes period microseconds per slot,
  // so revs per second = 1e6 / (period * slots), then times 60 for minutes.
  // Doing it in float keeps it readable; the Uno can handle it at 5 Hz.
  float revsPerSecond = 1000000.0 / ((float)period * SLOTS_PER_REV);
  float rpm = revsPerSecond * 60.0;

  Serial.print("RPM: ");
  Serial.print(rpm, 1);
  Serial.print("   pulses: ");
  Serial.println(count);

  // Update about 5 times a second. Faster than that and the numbers
  // just flicker and nobody can read them anyway.
  delay(200);
}

// Laundromat dryer timer
// Written by a beginner. This runs a coin-op dryer for a fixed time.
// Ignore the coin acceptor wiring for now - we just assume coins were paid.

const int START_BUTTON = 2;   // push button to start the cycle, other leg to GND
const int HEATER_RELAY = 8;   // relay that turns the heater on
const int MOTOR_RELAY  = 9;   // relay that turns the drum motor on
const int LED_PIN      = 13;  // built-in LED, just for us to watch

// 30 minutes in milliseconds. 30 * 60 * 1000 = 1800000
const unsigned long DRY_TIME = 1800000UL;

unsigned long startTime = 0;
bool running = false;

void setup() {
  // Buttons use INPUT_PULLUP so we don't need an external resistor.
  // Pressed = LOW, released = HIGH. Easy to get backwards, remember that.
  pinMode(START_BUTTON, INPUT_PULLUP);

  pinMode(HEATER_RELAY, OUTPUT);
  pinMode(MOTOR_RELAY, OUTPUT);
  pinMode(LED_PIN, OUTPUT);

  // Start with everything off. Relays are active HIGH on our board.
  digitalWrite(HEATER_RELAY, LOW);
  digitalWrite(MOTOR_RELAY, LOW);
  digitalWrite(LED_PIN, LOW);

  // Serial is only for debugging. Ignore it in the real machine.
  Serial.begin(9600);
  Serial.println("Dryer ready");
}

void loop() {
  // Read the button. LOW means somebody pressed it.
  if (digitalRead(START_BUTTON) == LOW && !running) {
    // Small delay to ignore contact bounce. Not perfect but fine here.
    delay(50);
    if (digitalRead(START_BUTTON) == LOW) {
      startCycle();
    }
  }

  // If we are running, check if the time is up.
  if (running) {
    unsigned long elapsed = millis() - startTime;

    if (elapsed >= DRY_TIME) {
      stopCycle();
    }
  }
}

void startCycle() {
  running = true;
  startTime = millis();

  // Motor first, then heater. Gives the drum a moment to move.
  digitalWrite(MOTOR_RELAY, HIGH);
  delay(500);
  digitalWrite(HEATER_RELAY, HIGH);
  digitalWrite(LED_PIN, HIGH);

  Serial.println("Cycle started");
}

void stopCycle() {
  // Heater off first so we don't cook the drum, then motor.
  digitalWrite(HEATER_RELAY, LOW);
  delay(200);
  digitalWrite(MOTOR_RELAY, LOW);
  digitalWrite(LED_PIN, LOW);

  running = false;
  Serial.println("Cycle done");
}

// Lighthouse lamp changer
// Swaps to the spare bulb when the main one fails

const int RELAY_MAIN = 7;   // main lamp relay
const int RELAY_SPARE = 8;  // spare lamp relay
const int SENSE_PIN = A0;   // LDR sees the lamp
const int BUTTON_PIN = 2;   // manual swap button

const int LIT_LEVEL = 300;  // above this = lamp is lit
const unsigned long SETTLE_MS = 2000;

bool usingSpare = false;
unsigned long lastCheck = 0;

void setup() {
  pinMode(RELAY_MAIN, OUTPUT);
  pinMode(RELAY_SPARE, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  Serial.begin(9600);
  digitalWrite(RELAY_MAIN, HIGH);  // relays are active low
  digitalWrite(RELAY_SPARE, HIGH);
  delay(500);
  Serial.println("Lamp changer ready");
}

void loop() {
  // manual override
  if (digitalRead(BUTTON_PIN) == LOW) {
    swapLamp();
    delay(500);
  }

  if (millis() - lastCheck > SETTLE_MS) {
    lastCheck = millis();
    int light = analogRead(SENSE_PIN);
    Serial.print("Light: ");
    Serial.println(light);

    if (light < LIT_LEVEL) {
      // lamp looks dead, try the other one
      Serial.println("Lamp out!");
      swapLamp();
    }
  }
}

void swapLamp() {
  if (usingSpare) {
    digitalWrite(RELAY_SPARE, HIGH);
    delay(200);
    digitalWrite(RELAY_MAIN, LOW);
    usingSpare = false;
    Serial.println("Back to main lamp");
  } else {
    digitalWrite(RELAY_MAIN, HIGH);
    delay(200);
    digitalWrite(RELAY_SPARE, LOW);
    usingSpare = true;
    Serial.println("Switched to spare lamp");
  }
  lastCheck = millis();
}

// Magic Trick Servo Cue
// Written by a beginner. This makes a servo arm swing when you press a button.
// The idea: the magician secretly presses a button with their foot,
// the servo moves a hidden flap, and the trick "works by itself".

#include <Servo.h>  // the servo library that comes with Arduino

// ---- Pin setup ----
// I picked pin 9 for the servo because it can do PWM (the ~ symbol).
// Ignore the fact that Servo library can use almost any pin; pin 9 is fine.
const int SERVO_PIN = 9;

// Button goes on pin 2. I used INPUT_PULLUP so I don't need a resistor.
// That means the button reads LOW when pressed and HIGH when not pressed.
// (This confused me at first, so remember: pressed = LOW!)
const int BUTTON_PIN = 2;

// The LED on the board (pin 13) just blinks so I know the code is alive.
// You can ignore the LED entirely for the trick itself.
const int LED_PIN = 13;

Servo flapServo;  // make a servo object called flapServo

// These are the two positions. 20 degrees = flap down (hidden),
// 110 degrees = flap up (reveals the secret compartment).
// I tuned these by hand until it looked right. Change if your servo buzzes.
const int REST_ANGLE = 20;
const int CUE_ANGLE = 110;

// How long the flap stays up, in milliseconds. 1500 = 1.5 seconds.
// Long enough for the audience to see the "magic", short enough to be sneaky.
const unsigned long HOLD_TIME = 1500;

// This remembers when we last moved the servo, so we can time the hold.
unsigned long cueStartTime = 0;
bool cueActive = false;

void setup() {
  // Attach the servo and put it at rest right away.
  flapServo.attach(SERVO_PIN);
  flapServo.write(REST_ANGLE);

  // Button pin with internal pull-up. No external resistor needed.
  pinMode(BUTTON_PIN, INPUT_PULLUP);

  // LED is just for me, not part of the trick.
  pinMode(LED_PIN, OUTPUT);

  // Give the servo a moment to get to rest before anything else happens.
  // 500 ms is plenty. (I read that servos need time; maybe not, but harmless.)
  delay(500);
}

void loop() {
  // Blink the onboard LED so I can tell the Arduino didn't freeze.
  // Ignore this for the magic part. It's just a heartbeat.
  digitalWrite(LED_PIN, HIGH);
  delay(50);
  digitalWrite(LED_PIN, LOW);

  // Read the button. Remember: LOW means pressed because of INPUT_PULLUP.
  int buttonState = digitalRead(BUTTON_PIN);

  // If the button is pressed AND we aren't already doing a cue, start one.
  if (buttonState == LOW && cueActive == false) {
    flapServo.write(CUE_ANGLE);   // swing the flap up
    cueStartTime = millis();      // remember when we started
    cueActive = true;             // don't start again until we finish
  }

  // If a cue is running, check if enough time has passed.
  if (cueActive == true) {
    if (millis() - cueStartTime >= HOLD_TIME) {
      flapServo.write(REST_ANGLE);  // put the flap back down
      cueActive = false;            // ready for the next press
    }
  }

  // Small delay so the loop isn't too fast. 10 ms is fine.
  // This also helps debounce the button a little bit (not perfectly).
  delay(10);
}

// Milking parlour gate controller
// Written by a beginner - comments explain every step.
// Arduino Uno, Arduino core only (no extra libraries).

// ---- Pin assignments ----
// Ignore pins 0 and 1: they are the serial/USB pins, don't touch them.
const int BUTTON_PIN = 2;   // gate open/close push button (to GND, uses internal pullup)
const int LIMIT_OPEN = 3;   // limit switch, gate fully open (to GND)
const int LIMIT_SHUT = 4;   // limit switch, gate fully shut (to GND)
const int MOTOR_OPEN = 5;   // relay/driver input that opens the gate
const int MOTOR_SHUT = 6;   // relay/driver input that shuts the gate
const int BUZZER_PIN = 7;   // little buzzer so cows know the gate moves

// ---- State variables ----
// We remember whether the gate is supposed to be open or shut.
bool gateOpen = false;

// Debounce stuff: buttons can flicker, so we ignore very fast changes.
// Ignore the exact numbers, they just worked in testing.
unsigned long lastPress = 0;
const unsigned long DEBOUNCE_MS = 50;

void setup() {
  // Set the motor pins as outputs - these drive the relays.
  pinMode(MOTOR_OPEN, OUTPUT);
  pinMode(MOTOR_SHUT, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);

  // Buttons and switches are inputs. INPUT_PULLUP means the pin reads
  // HIGH when nothing is pressed, LOW when pressed to ground.
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LIMIT_OPEN, INPUT_PULLUP);
  pinMode(LIMIT_SHUT, INPUT_PULLUP);

  // Make sure both motor directions are off at startup.
  digitalWrite(MOTOR_OPEN, LOW);
  digitalWrite(MOTOR_SHUT, LOW);

  // Serial is handy for debugging but not needed for the gate.
  // Ignore the baud rate, it only matters if you open the monitor.
  Serial.begin(9600);
}

void loop() {
  // Step 1: read the button. LOW means pressed because of the pullup.
  bool pressed = (digitalRead(BUTTON_PIN) == LOW);

  // Step 2: only react if enough time passed since the last press.
  // This stops one press from counting as five.
  if (pressed && (millis() - lastPress > DEBOUNCE_MS)) {
    lastPress = millis();
    gateOpen = !gateOpen;   // flip the wanted state
    Serial.print("Button pressed, gate should now be ");
    Serial.println(gateOpen ? "OPEN" : "SHUT");
  }

  // Step 3: actually move the gate toward the wanted state.
  if (gateOpen) {
    openGate();
  } else {
    shutGate();
  }
}

// This function runs the motor to open the gate until the open limit hits.
void openGate() {
  // If the open limit switch is already pressed, we are done. Stop.
  if (digitalRead(LIMIT_OPEN) == LOW) {
    digitalWrite(MOTOR_OPEN, LOW);
    digitalWrite(MOTOR_SHUT, LOW);
    return;
  }

  // Otherwise drive open, and make sure shut is off (never both!).
  digitalWrite(MOTOR_SHUT, LOW);
  digitalWrite(MOTOR_OPEN, HIGH);
  tone(BUZZER_PIN, 1000);   // beep while moving
}

// Same idea for shutting the gate.
void shutGate() {
  if (digitalRead(LIMIT_SHUT) == LOW) {
    digitalWrite(MOTOR_OPEN, LOW);
    digitalWrite(MOTOR_SHUT, LOW);
    return;
  }

  digitalWrite(MOTOR_OPEN, LOW);
  digitalWrite(MOTOR_SHUT, HIGH);
  tone(BUZZER_PIN, 700);
}

// Model Train Block Signal
// Written by a beginner - go easy on me!
// This controls a red/green signal for a model train block.
// A train passing a sensor turns the signal red, then it goes green again.

// ---- Pin setup ----
// Red LED on pin 8, green LED on pin 9 (through 220 ohm resistors!)
const int RED_PIN = 8;
const int GREEN_PIN = 9;

// The sensor is a simple switch/IR detector on pin 2.
// We use INPUT_PULLUP so the pin reads HIGH when nothing is there.
// IMPORTANT: ignore the fact that a real IR sensor might need its own
// power and signal conditioning - for this test we just treat it as a switch.
const int SENSOR_PIN = 2;

// How long the signal stays red after the train passes (milliseconds).
// 5000 ms = 5 seconds. Change this to taste.
const unsigned long RED_TIME = 5000;

// We remember when the train was last seen.
unsigned long lastSeen = 0;

// A flag so we know if we are currently in the red state.
bool isRed = false;

void setup() {
  // Set the LED pins as outputs so we can drive them.
  pinMode(RED_PIN, OUTPUT);
  pinMode(GREEN_PIN, OUTPUT);

  // Sensor pin as input with the internal pull-up resistor enabled.
  pinMode(SENSOR_PIN, INPUT_PULLUP);

  // Start with a green (clear) signal.
  digitalWrite(RED_PIN, LOW);
  digitalWrite(GREEN_PIN, HIGH);

  // Serial is handy for debugging. You can ignore it if you want,
  // it does not affect the signal at all.
  Serial.begin(9600);
  Serial.println("Block signal ready");
}

void loop() {
  // Read the sensor. With INPUT_PULLUP, LOW means the train is present.
  int sensorState = digitalRead(SENSOR_PIN);

  if (sensorState == LOW) {
    // Train detected! Go red and remember the time.
    if (!isRed) {
      Serial.println("Train in block - RED");
    }
    isRed = true;
    lastSeen = millis();
  }

  // If we are red and enough time has passed since the last detection,
  // go back to green. Note: millis() rolls over after ~49 days; for a
  // model train that is fine, so I am ignoring that edge case.
  if (isRed && (millis() - lastSeen >= RED_TIME)) {
    isRed = false;
    Serial.println("Block clear - GREEN");
  }

  // Actually drive the LEDs based on the state.
  if (isRed) {
    digitalWrite(RED_PIN, HIGH);
    digitalWrite(GREEN_PIN, LOW);
  } else {
    digitalWrite(RED_PIN, LOW);
    digitalWrite(GREEN_PIN, HIGH);
  }

  // Small delay so we do not spam the serial monitor.
  // This does not hurt the timing much (20 ms).
  delay(20);
}

/*
 * Museum Case Humidity Alarm
 * ---------------------------
 * Design notes:
 *  - A DHT11 sensor on D2 reports relative humidity once per second.
 *  - The case is considered "too damp" when RH exceeds HUMIDITY_LIMIT_PCT
 *    for HUMIDITY_TRIP_COUNT consecutive samples. Requiring several samples
 *    in a row filters out the DHT11's occasional noisy readings.
 *  - A red LED on D9 and a piezo on D8 announce the alarm.
 *  - The alarm latches until the humidity falls below HUMIDITY_CLEAR_PCT,
 *    giving the conservator hysteresis so the buzzer doesn't chatter.
 *  - Serial output at 9600 baud is for bench diagnostics only.
 *
 * Written with the Arduino core only (no external DHT library).
 */

#include <Arduino.h>

// ---- Pin assignments -------------------------------------------------
const uint8_t DHT_PIN        = 2;   // DHT11 data line
const uint8_t ALARM_LED_PIN  = 9;   // red LED, active high
const uint8_t BUZZER_PIN     = 8;   // piezo buzzer

// ---- Alarm thresholds ------------------------------------------------
const uint8_t  HUMIDITY_LIMIT_PCT = 65;  // trip above this RH
const uint8_t  HUMIDITY_CLEAR_PCT = 60;  // clear below this RH
const uint8_t  HUMIDITY_TRIP_COUNT = 3;  // consecutive samples to trip
const uint32_t SAMPLE_INTERVAL_MS  = 1000;

// ---- State -----------------------------------------------------------
bool     alarmActive   = false;
uint8_t  overLimitRuns = 0;
uint32_t lastSampleMs  = 0;

// Read the DHT11. Returns humidity in whole percent, or 255 on error.
// This is a minimal bit-banged implementation; it is not robust to
// interrupts but is fine for a slow museum monitor.
uint8_t readHumidity() {
  uint8_t data[5] = {0, 0, 0, 0, 0};

  // Start signal: pull low ~18 ms, then release.
  pinMode(DHT_PIN, OUTPUT);
  digitalWrite(DHT_PIN, LOW);
  delay(18);
  digitalWrite(DHT_PIN, HIGH);
  delayMicroseconds(30);
  pinMode(DHT_PIN, INPUT_PULLUP);

  // Wait for the sensor's response pulse.
  uint32_t timeout = micros();
  while (digitalRead(DHT_PIN) == HIGH) {
    if (micros() - timeout > 100) return 255;
  }
  timeout = micros();
  while (digitalRead(DHT_PIN) == LOW) {
    if (micros() - timeout > 100) return 255;
  }
  timeout = micros();
  while (digitalRead(DHT_PIN) == HIGH) {
    if (micros() - timeout > 100) return 255;
  }

  // Read 40 bits: 16 humidity, 16 temperature, 8 checksum.
  for (uint8_t i = 0; i < 40; i++) {
    timeout = micros();
    while (digitalRead(DHT_PIN) == LOW) {
      if (micros() - timeout > 100) return 255;
    }
    uint32_t highStart = micros();
    while (digitalRead(DHT_PIN) == HIGH) {
      if (micros() - highStart > 100) return 255;
    }
    uint32_t highLen = micros() - highStart;
    if (highLen > 40) {
      data[i / 8] |= (1 << (7 - (i % 8)));
    }
  }

  uint8_t checksum = data[0] + data[1] + data[2] + data[3];
  if (checksum != data[4]) return 255;
  return data[0];
}

void setup() {
  pinMode(ALARM_LED_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(ALARM_LED_PIN, LOW);
  digitalWrite(BUZZER_PIN, LOW);
  Serial.begin(9600);
  Serial.println(F("Museum humidity monitor starting"));
}

void loop() {
  uint32_t now = millis();
  if (now - lastSampleMs < SAMPLE_INTERVAL_MS) return;
  lastSampleMs = now;

  uint8_t rh = readHumidity();
  if (rh == 255) {
    Serial.println(F("DHT read error"));
    return;
  }

  Serial.print(F("RH = "));
  Serial.print(rh);
  Serial.println('%');

  if (rh > HUMIDITY_LIMIT_PCT) {
    if (overLimitRuns < 255) overLimitRuns++;
    if (overLimitRuns >= HUMIDITY_TRIP_COUNT) alarmActive = true;
  } else {
    overLimitRuns = 0;
    if (rh < HUMIDITY_CLEAR_PCT) alarmActive = false;
  }

  if (alarmActive) {
    digitalWrite(ALARM_LED_PIN, HIGH);
    tone(BUZZER_PIN, 2000);
  } else {
    digitalWrite(ALARM_LED_PIN, LOW);
    noTone(BUZZER_PIN);
  }
}

// Mushroom Grow Room Humidifier
// Written by a beginner, so lots of comments. Read them!
// Goal: keep the grow room humid around 90% using a mist maker.
// Ignore the stuff about the LCD backlight, I left it in by accident.

// ---- Pin setup ----
// DHT22 data pin goes to D7. It reads temp and humidity.
const int DHT_PIN = 7;
// Relay that switches the humidifier sits on D9.
const int HUMIDIFIER_PIN = 9;
// A little push button on D2 to force misting for a bit (not really needed).
const int BUTTON_PIN = 2;

// ---- Settings you can tweak ----
// Mushrooms like it damp. Turn on below 88%, off above 93%.
const float HUM_ON = 88.0;
const float HUM_OFF = 93.0;
// Don't let the mister run forever if the sensor is broken.
const unsigned long MAX_MIST_MS = 120000; // 2 minutes

// ---- State variables ----
bool misting = false;
unsigned long mistStart = 0;

void setup() {
  // Start the serial monitor so we can watch numbers.
  Serial.begin(9600);
  // Relay pin is an output. Most relay boards are active LOW,
  // so HIGH means OFF. We set it HIGH first so it stays off at boot.
  pinMode(HUMIDIFIER_PIN, OUTPUT);
  digitalWrite(HUMIDIFIER_PIN, HIGH);
  // Button uses the internal pull-up, so pressed = LOW.
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  Serial.println("Humidifier starting up...");
}

// Fake-ish sensor read. In a real build you'd use the DHT library,
// but the Arduino core alone can't talk DHT22 easily, so this is a
// placeholder that returns a slowly wandering number. Replace it later!
float readHumidity() {
  // Use a simple sawtooth based on millis so it changes over time.
  unsigned long t = millis() / 1000; // seconds
  float h = 85.0 + (t % 12);        // goes 85..96 then wraps
  return h;
}

void loop() {
  float humidity = readHumidity();

  // Print so we can debug in the serial monitor.
  Serial.print("Humidity: ");
  Serial.print(humidity);
  Serial.println(" %");

  // Button override: hold it to force misting on.
  bool forced = (digitalRead(BUTTON_PIN) == LOW);

  // Decide whether to mist.
  if (forced) {
    if (!misting) {
      misting = true;
      mistStart = millis();
      digitalWrite(HUMIDIFIER_PIN, LOW); // LOW = relay ON
      Serial.println("Button held: misting");
    }
  } else if (!misting && humidity < HUM_ON) {
    // Too dry, start misting.
    misting = true;
    mistStart = millis();
    digitalWrite(HUMIDIFIER_PIN, LOW);
    Serial.println("Dry: mist ON");
  } else if (misting && humidity > HUM_OFF) {
    // Damp enough, stop.
    misting = false;
    digitalWrite(HUMIDIFIER_PIN, HIGH);
    Serial.println("Damp: mist OFF");
  }

  // Safety: never mist longer than MAX_MIST_MS in one go.
  if (misting && (millis() - mistStart > MAX_MIST_MS)) {
    misting = false;
    digitalWrite(HUMIDIFIER_PIN, HIGH);
    Serial.println("Safety timeout: mist OFF");
  }

  // Wait a bit. DHT22 can't be read faster than ~2 seconds anyway.
  delay(2000);
}

const byte PIN_OPEN_SW = 2;
const byte PIN_CLOSED_SW = 3;
const byte PIN_MOTOR = 9;
const byte PIN_LED = 13;
const byte PIN_ESTOP = 4;

const unsigned long DEBOUNCE_MS = 25;
const unsigned long MAX_TRAVEL_MS = 45000UL;

bool lastOpen = false, lastClosed = false;
unsigned long lastOpenChange = 0, lastClosedChange = 0;
unsigned long moveStart = 0;
bool moving = false;
bool wantOpen = false;

bool debounce(byte pin, bool &last, unsigned long &t) {
  bool r = digitalRead(pin);
  if (r != last) {
    t = millis();
    last = r;
  }
  return last;
}

void stopMotor() {
  digitalWrite(PIN_MOTOR, LOW);
  moving = false;
}

void setup() {
  pinMode(PIN_OPEN_SW, INPUT_PULLUP);
  pinMode(PIN_CLOSED_SW, INPUT_PULLUP);
  pinMode(PIN_ESTOP, INPUT_PULLUP);
  pinMode(PIN_MOTOR, OUTPUT);
  pinMode(PIN_LED, OUTPUT);
  digitalWrite(PIN_MOTOR, LOW);
  Serial.begin(9600);
}

void loop() {
  bool openSw = debounce(PIN_OPEN_SW, lastOpen, lastOpenChange);
  bool closedSw = debounce(PIN_CLOSED_SW, lastClosed, lastClosedChange);
  bool estop = digitalRead(PIN_ESTOP) == LOW;

  if (estop) {
    stopMotor();
    digitalWrite(PIN_LED, (millis() / 250) % 2);
    return;
  }

  if (Serial.available()) {
    char c = Serial.read();
    if (c == 'o' && closedSw && !moving) {
      wantOpen = true;
      moving = true;
      moveStart = millis();
      digitalWrite(PIN_MOTOR, HIGH);
    } else if (c == 'c' && openSw && !moving) {
      wantOpen = false;
      moving = true;
      moveStart = millis();
      digitalWrite(PIN_MOTOR, HIGH);
    } else if (c == 's') {
      stopMotor();
    }
  }

  if (moving) {
    if (wantOpen && openSw) stopMotor();
    else if (!wantOpen && closedSw) stopMotor();
    else if (millis() - moveStart > MAX_TRAVEL_MS) {
      stopMotor();
      Serial.println(F("timeout"));
    }
  }

  digitalWrite(PIN_LED, moving);
}

// Orchard irrigation zone controller
// Waters one zone when soil gets dry, with a manual override button

const int SOIL_PIN = A0;      // analog soil moisture sensor
const int BUTTON_PIN = 2;     // manual water button, to GND
const int VALVE_PIN = 9;      // relay/solenoid driver
const int LED_PIN = 13;       // onboard LED shows watering

const int DRY_THRESHOLD = 600;  // above this = dry
const int WET_THRESHOLD = 400;  // below this = wet enough

bool watering = false;
unsigned long lastCheck = 0;
const unsigned long CHECK_MS = 2000;

void setup() {
  pinMode(VALVE_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  digitalWrite(VALVE_PIN, LOW);
  Serial.begin(9600);
  Serial.println("Orchard zone ready");
}

void loop() {
  // manual button: water while held
  if (digitalRead(BUTTON_PIN) == LOW) {
    setWatering(true);
    delay(50);
    return;
  }

  if (millis() - lastCheck >= CHECK_MS) {
    lastCheck = millis();
    int soil = analogRead(SOIL_PIN);
    Serial.print("soil: ");
    Serial.println(soil);

    if (!watering && soil > DRY_THRESHOLD) {
      setWatering(true);
    } else if (watering && soil < WET_THRESHOLD) {
      setWatering(false);
    }
  }
}

void setWatering(bool on) {
  watering = on;
  digitalWrite(VALVE_PIN, on ? HIGH : LOW);
  digitalWrite(LED_PIN, on ? HIGH : LOW);
}

const uint8_t PIN_TACH = 2;
const uint8_t PIN_RELAY = 7;
const uint8_t PIN_LED = 13;
const uint8_t PIN_BTN = 4;

const unsigned long PULSES_PER_REV = 2;
const unsigned long MIN_RPM = 300;
const unsigned long START_GRACE_MS = 4000;
const unsigned long STOP_DELAY_MS = 1500;
const unsigned long DEBOUNCE_MS = 30;

volatile unsigned long pulses = 0;
unsigned long lastSample = 0;
unsigned long rpm = 0;
unsigned long runStart = 0;
unsigned long lastEdge = 0;
bool running = false;
bool fault = false;
bool btnPrev = false;
unsigned long btnTime = 0;

void tachISR() {
  pulses++;
  lastEdge = millis();
}

void setup() {
  pinMode(PIN_RELAY, OUTPUT);
  pinMode(PIN_LED, OUTPUT);
  pinMode(PIN_BTN, INPUT_PULLUP);
  pinMode(PIN_TACH, INPUT_PULLUP);
  digitalWrite(PIN_RELAY, LOW);
  digitalWrite(PIN_LED, LOW);
  attachInterrupt(digitalPinToInterrupt(PIN_TACH), tachISR, FALLING);
  Serial.begin(9600);
}

void loop() {
  unsigned long now = millis();

  bool btn = !digitalRead(PIN_BTN);
  if (btn != btnPrev && now - btnTime > DEBOUNCE_MS) {
    btnTime = now;
    btnPrev = btn;
    if (btn) {
      if (fault) {
        fault = false;
      } else {
        running = !running;
        if (running) runStart = now;
      }
    }
  }

  if (now - lastSample >= 1000) {
    noInterrupts();
    unsigned long p = pulses;
    pulses = 0;
    interrupts();
    lastSample = now;
    rpm = (p * 60UL) / PULSES_PER_REV;
  }

  if (running && !fault) {
    digitalWrite(PIN_RELAY, HIGH);
    if (now - runStart > START_GRACE_MS && rpm < MIN_RPM) {
      fault = true;
      running = false;
      digitalWrite(PIN_RELAY, LOW);
    }
  } else {
    digitalWrite(PIN_RELAY, LOW);
  }

  if (fault) {
    digitalWrite(PIN_LED, (now / 250) & 1);
  } else {
    digitalWrite(PIN_LED, running ? HIGH : LOW);
  }

  if (running && rpm == 0 && now - lastEdge > STOP_DELAY_MS && now - runStart > START_GRACE_MS) {
    fault = true;
    running = false;
    digitalWrite(PIN_RELAY, LOW);
  }
}

// Pachinko Ball Counter
// Counts balls rolling past an IR beam sensor and shows the total
// on a 4-digit TM1637-style display... wait, no, we only use the
// Arduino core here, so instead we blink the count out on an LED
// and print it over Serial. Keep it simple!

// ---- Pin setup ----
// The IR beam sensor output goes here. It reads LOW when a ball
// blocks the beam (most of these modules are active-low).
const int SENSOR_PIN = 2;

// A little LED so you can see activity without a serial monitor.
const int LED_PIN = 13;

// ---- Counting state ----
unsigned long ballCount = 0;

// Debounce: a ball is a physical object, so the beam can flicker
// as it passes. We ignore any new trigger within this many ms.
const unsigned long DEBOUNCE_MS = 40;
unsigned long lastTriggerMs = 0;

// We remember the last reading so we only count on a CHANGE
// (falling edge). Counting every loop while LOW would count
// one ball thousands of times. That's the classic beginner bug.
int lastReading = HIGH;

void setup() {
  // Sensor module output is open-collector-ish, so enable the
  // internal pull-up. If your module has its own pull-up this is
  // harmless. If it's push-pull, also harmless.
  pinMode(SENSOR_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);

  Serial.begin(9600);
  Serial.println("Pachinko ball counter ready");
  Serial.println("Count will print here and blink on pin 13.");
}

void loop() {
  int reading = digitalRead(SENSOR_PIN);
  unsigned long now = millis();

  // Only react when the beam goes from clear (HIGH) to blocked (LOW).
  if (reading == LOW && lastReading == HIGH) {
    // Debounce check. unsigned subtraction handles millis() rollover
    // correctly, which is why we don't just compare now > lastTriggerMs.
    if (now - lastTriggerMs >= DEBOUNCE_MS) {
      ballCount++;
      lastTriggerMs = now;

      // Blink the LED briefly so you can see each ball counted.
      digitalWrite(LED_PIN, HIGH);
      delay(5);
      digitalWrite(LED_PIN, LOW);

      Serial.print("Ball #");
      Serial.println(ballCount);
    }
  }

  lastReading = reading;

  // Nothing else to do. We deliberately do NOT delay() in the main
  // loop, because a slow loop could miss a fast ball. The debounce
  // window above is the only intentional delay.
}

// Planetarium Dome Lights
// Written by a beginner. This sketch fades a ring of LEDs
// to look like a slow starry night. Read the comments!

// ---- Pin setup ----
// We use PWM pins (the ones with a ~ next to them on the board).
// Pin 9 = warm white LEDs, Pin 10 = blue LEDs, Pin 11 = red LEDs.
// Ignore pins 0 and 1 - those are for USB serial and messing with
// them can break uploading.
const int warmPin = 9;
const int bluePin = 10;
const int redPin  = 11;

// A button on pin 2 to switch between "night" and "off".
// We use INPUT_PULLUP so we don't need an extra resistor.
const int buttonPin = 2;

// ---- Timing ----
// How long each fade step takes. Bigger = slower.
const int stepDelay = 40;

// Keep track of whether the dome is on.
bool domeOn = true;

void setup() {
  // Set the LED pins as outputs so we can drive them.
  pinMode(warmPin, OUTPUT);
  pinMode(bluePin, OUTPUT);
  pinMode(redPin, OUTPUT);

  // Button pin: pull-up means it reads HIGH when not pressed.
  pinMode(buttonPin, INPUT_PULLUP);

  // Start dark so we don't flash the audience.
  analogWrite(warmPin, 0);
  analogWrite(bluePin, 0);
  analogWrite(redPin, 0);
}

void loop() {
  // Check the button first. LOW means pressed because of the pull-up.
  if (digitalRead(buttonPin) == LOW) {
    domeOn = !domeOn;      // flip the state
    delay(300);            // crude debounce - ignore for now, it works
  }

  if (domeOn) {
    nightSky();
  } else {
    allOff();
  }
}

// Fade warm and blue up and down together, with a little red shimmer.
void nightSky() {
  // Go from 0 to 255 in steps of 5.
  for (int b = 0; b <= 255; b += 5) {
    analogWrite(warmPin, b / 2);   // warm stays dimmer
    analogWrite(bluePin, b);       // blue is the main glow
    analogWrite(redPin, b / 8);    // tiny red for warmth
    delay(stepDelay);
  }

  // Now fade back down. Same idea, counting backwards.
  for (int b = 255; b >= 0; b -= 5) {
    analogWrite(warmPin, b / 2);
    analogWrite(bluePin, b);
    analogWrite(redPin, b / 8);
    delay(stepDelay);
  }
}

// Turn everything off cleanly.
void allOff() {
  analogWrite(warmPin, 0);
  analogWrite(bluePin, 0);
  analogWrite(redPin, 0);
}

#include <Arduino.h>

const uint8_t PIN_HALL = 2;
const uint8_t PIN_LATCH = 7;
const uint8_t PIN_CLK = 8;
const uint8_t PIN_DATA = 9;

volatile uint32_t pulseCount = 0;
volatile uint32_t lastPulseUs = 0;

const uint8_t SEG[10] = {
  0b00111111, 0b00000110, 0b01011011, 0b01001111, 0b01100110,
  0b01101101, 0b01111101, 0b00000111, 0b01111111, 0b01101111
};

void onPulse() {
  uint32_t now = micros();
  if (now - lastPulseUs > 2000) {
    pulseCount++;
    lastPulseUs = now;
  }
}

void shiftOut595(uint8_t val) {
  for (int8_t i = 7; i >= 0; i--) {
    digitalWrite(PIN_CLK, LOW);
    digitalWrite(PIN_DATA, (val >> i) & 1);
    digitalWrite(PIN_CLK, HIGH);
  }
  digitalWrite(PIN_LATCH, LOW);
  digitalWrite(PIN_LATCH, HIGH);
}

void showNumber(uint16_t n) {
  if (n > 999) n = 999;
  uint8_t h = n / 100;
  uint8_t t = (n / 10) % 10;
  uint8_t o = n % 10;
  uint8_t pattern = 0;
  if (h) pattern |= SEG[h];
  if (h || t) pattern |= SEG[t] << 0;
  pattern |= SEG[o];
  shiftOut595(pattern);
}

void setup() {
  pinMode(PIN_HALL, INPUT_PULLUP);
  pinMode(PIN_LATCH, OUTPUT);
  pinMode(PIN_CLK, OUTPUT);
  pinMode(PIN_DATA, OUTPUT);
  digitalWrite(PIN_LATCH, LOW);
  digitalWrite(PIN_CLK, LOW);
  attachInterrupt(digitalPinToInterrupt(PIN_HALL), onPulse, FALLING);
  Serial.begin(9600);
}

void loop() {
  static uint32_t lastCalc = 0;
  static uint16_t rpm = 0;
  uint32_t now = millis();
  if (now - lastCalc >= 500) {
    uint32_t elapsed = now - lastCalc;
    lastCalc = now;
    noInterrupts();
    uint32_t count = pulseCount;
    pulseCount = 0;
    interrupts();
    uint32_t pulsesPerMin = (count * 60000UL) / elapsed;
    rpm = (uint16_t)(pulsesPerMin / 2);
    Serial.print("rpm=");
    Serial.println(rpm);
  }
  showNumber(rpm);
  delay(20);
}

/*
 * Pressure Washer Dwell Timer
 * ----------------------------
 * Purpose: after the trigger is released, keep the pump off for a fixed
 * dwell period so the pressure bleeds off before the next start.
 *
 * Design notes:
 *  - Trigger input is active-LOW with the internal pull-up (switch to GND).
 *  - A press starts the pump immediately; releasing it starts the dwell.
 *  - During dwell the pump stays off; a new press is ignored until dwell ends.
 *  - Status LED mirrors the pump output.
 *  - All timing is non-blocking via millis().
 */

const uint8_t TRIGGER_PIN = 2;   // trigger switch, to GND
const uint8_t PUMP_PIN    = 8;   // relay / MOSFET gate
const uint8_t LED_PIN     = 13;  // onboard status LED

const unsigned long DWELL_MS = 5000;  // 5 s bleed-off dwell
const unsigned long DEBOUNCE_MS = 30;

bool pumpOn = false;
bool dwellActive = false;
unsigned long dwellStart = 0;

bool lastRaw = HIGH;
bool stableState = HIGH;
unsigned long lastChange = 0;

void setup() {
  pinMode(TRIGGER_PIN, INPUT_PULLUP);
  pinMode(PUMP_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(PUMP_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
}

// Returns true on a fresh HIGH->LOW edge (press).
bool triggerPressed() {
  bool raw = digitalRead(TRIGGER_PIN);
  if (raw != lastRaw) {
    lastChange = millis();
    lastRaw = raw;
  }
  if ((millis() - lastChange) > DEBOUNCE_MS && raw != stableState) {
    stableState = raw;
    return stableState == LOW;
  }
  return false;
}

void setPump(bool on) {
  pumpOn = on;
  digitalWrite(PUMP_PIN, on ? HIGH : LOW);
  digitalWrite(LED_PIN, on ? HIGH : LOW);
}

void loop() {
  bool pressed = triggerPressed();

  if (dwellActive) {
    if (millis() - dwellStart >= DWELL_MS) {
      dwellActive = false;
    }
    // Ignore presses while dwelling.
    return;
  }

  if (pressed) {
    setPump(true);
  } else if (stableState == HIGH && pumpOn) {
    // Trigger released: stop pump and begin dwell.
    setPump(false);
    dwellActive = true;
    dwellStart = millis();
  }
}

// Printing Press Sheet Counter
// Written by a beginner, so I'm explaining everything as I go.
// This counts sheets passing a sensor on a printing press.

// ---- Pin setup ----
// The sensor is a slotted optical sensor (photointerrupter) on pin 2.
// It pulls LOW when a sheet blocks the beam.
const int SENSOR_PIN = 2;

// The reset button is on pin 4, wired to GND with the internal pullup.
const int RESET_BUTTON = 4;

// The big count display is a 16x2 LCD in 4-bit mode.
// (I'm using the Arduino core only, so I talk to it with the LiquidCrystal
// library that ships with the IDE. That's still "core" enough for me.)
#include <LiquidCrystal.h>
LiquidCrystal lcd(7, 8, 9, 10, 11, 12);

// ---- State variables ----
volatile unsigned long sheetCount = 0;  // volatile because ISR changes it
volatile bool newSheetFlag = false;     // set by ISR, cleared in loop

// Debounce: sheets can't physically be closer than ~20 ms apart on this press.
// Anything faster is probably electrical noise from the motor, so ignore it.
const unsigned long DEBOUNCE_MS = 20;
volatile unsigned long lastPulseMs = 0;

// ---- Interrupt service routine ----
// The sensor goes LOW when a sheet passes. We count on the FALLING edge.
// Keep this SHORT - no Serial prints, no LCD writes in here!
void onSheetDetected() {
  unsigned long now = millis();
  if (now - lastPulseMs < DEBOUNCE_MS) {
    return;  // too soon, probably noise - ignore it
  }
  lastPulseMs = now;
  sheetCount++;
  newSheetFlag = true;
}

void setup() {
  // Sensor input with pullup so it reads HIGH when nothing is there.
  pinMode(SENSOR_PIN, INPUT_PULLUP);

  // Reset button: INPUT_PULLUP means pressed = LOW.
  pinMode(RESET_BUTTON, INPUT_PULLUP);

  // LCD is 16 columns, 2 rows.
  lcd.begin(16, 2);
  lcd.print("Sheets:");
  lcd.setCursor(0, 1);
  lcd.print("0");

  // Attach the interrupt. FALLING = beam broken.
  attachInterrupt(digitalPinToInterrupt(SENSOR_PIN), onSheetDetected, FALLING);
}

void loop() {
  // Only redraw the LCD when a new sheet actually arrived.
  // Redrawing every loop would make the display flicker like crazy.
  if (newSheetFlag) {
    newSheetFlag = false;

    // Clear just the number row, then print the count.
    lcd.setCursor(0, 1);
    lcd.print("                ");  // 16 spaces to wipe old digits
    lcd.setCursor(0, 1);
    lcd.print(sheetCount);
  }

  // Reset button: hold it down to zero the counter.
  // I'm not debouncing this one - a human press is slow enough.
  if (digitalRead(RESET_BUTTON) == LOW) {
    // Disable interrupts while we touch the shared variable.
    noInterrupts();
    sheetCount = 0;
    interrupts();

    lcd.setCursor(0, 1);
    lcd.print("                ");
    lcd.setCursor(0, 1);
    lcd.print("0");

    // Wait for the button to be released so we don't reset repeatedly.
    while (digitalRead(RESET_BUTTON) == LOW) {
      delay(10);
    }
  }
}

/*
 * Rocket Launch Countdown Box
 * ---------------------------
 * Design notes:
 *  - A single button arms the countdown; a second press aborts it.
 *  - Countdown runs from T_MINUS_START seconds down to zero.
 *  - A green LED is lit while idle/armed-ready, a red LED while counting,
 *    and both blink together when the countdown reaches zero (LAUNCH).
 *  - A piezo buzzer gives a short beep each second during the count.
 *  - Button is debounced in software; active-low with internal pull-up.
 *  - All timing is non-blocking via millis() so the button stays responsive.
 */

const uint8_t BUTTON_PIN   = 2;   // to GND when pressed
const uint8_t GREEN_LED_PIN = 8;
const uint8_t RED_LED_PIN   = 9;
const uint8_t BUZZER_PIN    = 10;

const uint8_t  T_MINUS_START   = 10;     // seconds
const uint16_t DEBOUNCE_MS     = 30;
const uint16_t BEEP_MS         = 60;
const uint16_t LAUNCH_BLINK_MS = 250;

enum State { IDLE, COUNTING, LAUNCH };
State state = IDLE;

uint8_t  secondsLeft = T_MINUS_START;
uint32_t lastSecondTick = 0;
uint32_t lastBlink = 0;
bool     blinkOn = false;

bool     lastButtonReading = HIGH;
bool     buttonStable = HIGH;
uint32_t lastDebounceTime = 0;

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(GREEN_LED_PIN, OUTPUT);
  pinMode(RED_LED_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(GREEN_LED_PIN, HIGH);  // ready
  digitalWrite(RED_LED_PIN, LOW);
}

// Returns true once per clean press (falling edge after debounce).
bool buttonPressed() {
  bool reading = digitalRead(BUTTON_PIN);
  if (reading != lastButtonReading) {
    lastDebounceTime = millis();
    lastButtonReading = reading;
  }
  if ((millis() - lastDebounceTime) > DEBOUNCE_MS && reading != buttonStable) {
    buttonStable = reading;
    if (buttonStable == LOW) return true;
  }
  return false;
}

void beep() {
  tone(BUZZER_PIN, 2000, BEEP_MS);
}

void startCountdown() {
  state = COUNTING;
  secondsLeft = T_MINUS_START;
  lastSecondTick = millis();
  digitalWrite(GREEN_LED_PIN, LOW);
  digitalWrite(RED_LED_PIN, HIGH);
  beep();
}

void abortCountdown() {
  state = IDLE;
  noTone(BUZZER_PIN);
  digitalWrite(RED_LED_PIN, LOW);
  digitalWrite(GREEN_LED_PIN, HIGH);
}

void loop() {
  if (buttonPressed()) {
    if (state == IDLE) {
      startCountdown();
    } else {
      abortCountdown();
    }
  }

  if (state == COUNTING) {
    if (millis() - lastSecondTick >= 1000) {
      lastSecondTick += 1000;
      if (secondsLeft > 0) {
        secondsLeft--;
        beep();
      }
      if (secondsLeft == 0) {
        state = LAUNCH;
        lastBlink = millis();
        blinkOn = true;
      }
    }
  } else if (state == LAUNCH) {
    if (millis() - lastBlink >= LAUNCH_BLINK_MS) {
      lastBlink = millis();
      blinkOn = !blinkOn;
      digitalWrite(GREEN_LED_PIN, blinkOn);
      digitalWrite(RED_LED_PIN, blinkOn);
    }
  }
}

// Roller coaster block brake model
// Brake arm on servo, train sensor on pin 2

#include <Servo.h>

Servo brake;
const int sensorPin = 2;
const int servoPin = 9;
const int ledPin = 13;

bool trainPresent = false;
unsigned long lastTrigger = 0;

void setup() {
  pinMode(sensorPin, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);
  brake.attach(servoPin);
  brake.write(0);   // brakes released
  Serial.begin(9600);
  Serial.println("Block brake ready");
}

void loop() {
  int s = digitalRead(sensorPin);

  // sensor is active low (beam broken = train)
  if (s == LOW && !trainPresent) {
    trainPresent = true;
    lastTrigger = millis();
    digitalWrite(ledPin, HIGH);
    brake.write(90);   // apply brake
    Serial.println("Train detected - braking");
  }

  if (s == HIGH && trainPresent) {
    trainPresent = false;
    digitalWrite(ledPin, LOW);
    Serial.println("Train cleared");
  }

  // release brake after 3 seconds of no train
  if (!trainPresent && (millis() - lastTrigger > 3000)) {
    brake.write(0);
  }

  delay(10);
}

/*
 * Sailboat Anchor Drag Alarm
 * ---------------------------
 * Design: a magnetic reed switch on the bow roller is closed while the
 * anchor chain is taut and the boat sits over her anchor. If the boat
 * drags, the chain angle changes and the reed opens. We debounce the
 * switch, and if it stays open longer than DRAG_TRIP_MS we sound a
 * piezo alarm and light a red LED. A pushbutton silences the alarm for
 * MUTE_MS so the crew can deal with the situation without going deaf.
 *
 * Wiring:
 *   Reed switch: one leg to D2, other leg to GND (INPUT_PULLUP).
 *                Closed (taut chain) = LOW.
 *   Mute button: D3 to GND (INPUT_PULLUP), pressed = LOW.
 *   Red LED:     D7 -> 220R -> LED -> GND.
 *   Piezo:       D8 -> piezo -> GND.
 */

const uint8_t REED_PIN      = 2;
const uint8_t MUTE_PIN      = 3;
const uint8_t LED_PIN       = 7;
const uint8_t PIEZO_PIN     = 8;

const unsigned long DEBOUNCE_MS   = 50;
const unsigned long DRAG_TRIP_MS  = 3000;   // chain slack this long = dragging
const unsigned long MUTE_MS       = 60000;  // silence for one minute
const unsigned long BEEP_ON_MS    = 200;
const unsigned long BEEP_OFF_MS   = 800;

bool          reedStable   = true;   // true = chain taut
bool          reedLast     = true;
unsigned long reedChangeAt = 0;
unsigned long slackSince   = 0;
bool          dragging     = false;

bool          muteLast     = true;
unsigned long muteUntil    = 0;

bool          beepOn       = false;
unsigned long beepAt       = 0;

void setup() {
  pinMode(REED_PIN, INPUT_PULLUP);
  pinMode(MUTE_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  pinMode(PIEZO_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
  digitalWrite(PIEZO_PIN, LOW);
}

void loop() {
  unsigned long now = millis();

  // --- debounce the reed switch ---
  bool reedRaw = (digitalRead(REED_PIN) == HIGH);  // HIGH = open = slack
  if (reedRaw != reedLast) {
    reedLast = reedRaw;
    reedChangeAt = now;
  }
  if (now - reedChangeAt >= DEBOUNCE_MS && reedRaw != reedStable) {
    reedStable = reedRaw;
    if (reedStable) {
      slackSince = now;          // chain just went slack
    } else {
      dragging = false;          // chain taut again, all good
    }
  }

  // --- drag detection ---
  if (reedStable && !dragging && (now - slackSince >= DRAG_TRIP_MS)) {
    dragging = true;
  }

  // --- mute button (edge triggered) ---
  bool muteRaw = (digitalRead(MUTE_PIN) == HIGH);
  if (!muteRaw && muteLast) {
    muteUntil = now + MUTE_MS;
  }
  muteLast = muteRaw;

  // --- outputs ---
  bool muted = (long)(muteUntil - now) > 0;
  if (dragging && !muted) {
    digitalWrite(LED_PIN, HIGH);
    if (beepOn && now - beepAt >= BEEP_ON_MS) {
      beepOn = false;
      beepAt = now;
      digitalWrite(PIEZO_PIN, LOW);
    } else if (!beepOn && now - beepAt >= BEEP_OFF_MS) {
      beepOn = true;
      beepAt = now;
      digitalWrite(PIEZO_PIN, HIGH);
    }
  } else {
    digitalWrite(LED_PIN, dragging ? HIGH : LOW);
    digitalWrite(PIEZO_PIN, LOW);
    beepOn = false;
    beepAt = now;
  }
}

/*
 * Sauna Heater Timeout Controller
 *
 * Design notes:
 *  - A single push button toggles the heater on and off.
 *  - When on, the heater is allowed to run for MAX_ON_MS (30 minutes).
 *  - After the timeout the heater is forced off and the button must be
 *    pressed again to restart. This is a safety limit, not a thermostat.
 *  - The button uses INPUT_PULLUP, so a press reads LOW.
 *  - A simple debounce ignores transitions closer than DEBOUNCE_MS.
 *  - The heater output drives a relay through a transistor; active HIGH.
 */

const uint8_t  BUTTON_PIN      = 2;
const uint8_t  HEATER_PIN      = 8;
const uint8_t  STATUS_LED_PIN  = 13;

const uint32_t DEBOUNCE_MS     = 50;
const uint32_t MAX_ON_MS       = 30UL * 60UL * 1000UL;  // 30 minutes

bool          heaterOn       = false;
bool          lastButtonRead = HIGH;
uint32_t      lastDebounceMs = 0;
uint32_t      heaterStartMs  = 0;

void setHeater(bool on) {
  heaterOn = on;
  digitalWrite(HEATER_PIN, on ? HIGH : LOW);
  digitalWrite(STATUS_LED_PIN, on ? HIGH : LOW);
  if (on) {
    heaterStartMs = millis();
  }
}

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(HEATER_PIN, OUTPUT);
  pinMode(STATUS_LED_PIN, OUTPUT);
  setHeater(false);
}

void loop() {
  // --- Button handling with debounce ---
  bool reading = digitalRead(BUTTON_PIN);
  if (reading != lastButtonRead) {
    lastDebounceMs = millis();
    lastButtonRead = reading;
  }

  if ((millis() - lastDebounceMs) >= DEBOUNCE_MS) {
    static bool stableState = HIGH;
    if (reading != stableState) {
      stableState = reading;
      if (stableState == LOW) {          // falling edge = press
        setHeater(!heaterOn);
      }
    }
  }

  // --- Safety timeout ---
  if (heaterOn && (millis() - heaterStartMs >= MAX_ON_MS)) {
    setHeater(false);
  }
}

const uint8_t PIN_GUARD = 2;
const uint8_t PIN_START = 3;
const uint8_t PIN_STOP = 4;
const uint8_t PIN_MOTOR = 9;
const uint8_t PIN_LED = 13;

const unsigned long DEBOUNCE_MS = 25;
const unsigned long START_HOLD_MS = 400;
const unsigned long GUARD_GRACE_MS = 150;

bool motorOn = false;
bool lastGuard = false;
unsigned long guardLowSince = 0;
unsigned long startSince = 0;
bool startHeld = false;

void setup() {
  pinMode(PIN_GUARD, INPUT_PULLUP);
  pinMode(PIN_START, INPUT_PULLUP);
  pinMode(PIN_STOP, INPUT_PULLUP);
  pinMode(PIN_MOTOR, OUTPUT);
  pinMode(PIN_LED, OUTPUT);
  digitalWrite(PIN_MOTOR, LOW);
  digitalWrite(PIN_LED, LOW);
  lastGuard = digitalRead(PIN_GUARD);
}

void loop() {
  bool guard = digitalRead(PIN_GUARD);
  bool start = digitalRead(PIN_START);
  bool stop = digitalRead(PIN_STOP);

  if (guard != lastGuard) {
    delay(DEBOUNCE_MS);
    guard = digitalRead(PIN_GUARD);
    lastGuard = guard;
  }

  if (guard == LOW) {
    if (guardLowSince == 0) guardLowSince = millis();
  } else {
    guardLowSince = 0;
  }

  if (stop == LOW) {
    motorOn = false;
    startHeld = false;
  }

  if (start == LOW) {
    if (!startHeld) {
      startHeld = true;
      startSince = millis();
    } else if (!motorOn && (millis() - startSince) >= START_HOLD_MS) {
      if (guard == HIGH) {
        motorOn = true;
      }
    }
  } else {
    startHeld = false;
  }

  if (motorOn && guard == LOW) {
    if ((millis() - guardLowSince) > GUARD_GRACE_MS) {
      motorOn = false;
    }
  }

  digitalWrite(PIN_MOTOR, motorOn ? HIGH : LOW);
  digitalWrite(PIN_LED, motorOn ? HIGH : LOW);
}

/*
 * Seismograph Drum Logger
 * -----------------------
 * Design notes:
 *  - An analog accelerometer (e.g. ADXL335) is read on A0.
 *  - We sample at a fixed interval and track a slow-moving baseline so
 *    that DC offset / temperature drift does not trigger false events.
 *  - When the deviation from baseline exceeds THRESHOLD, we log the peak
 *    and a timestamp over Serial, mimicking a drum recorder pen trace.
 *  - A status LED blinks on each logged event.
 *
 * Written by a tidy engineer. Arduino core only.
 */

const uint8_t  SENSOR_PIN      = A0;
const uint8_t  LED_PIN         = 13;
const uint16_t SAMPLE_MS       = 10;    // 100 Hz sampling
const uint16_t THRESHOLD       = 40;    // ADC counts above baseline
const uint16_t BASELINE_SHIFT  = 6;     // slow IIR: ~1/64 per sample
const uint16_t EVENT_HOLD_MS   = 250;   // debounce / event window

uint16_t baseline = 512;   // mid-scale guess
uint16_t peak     = 0;
bool     inEvent  = false;
unsigned long lastSample = 0;
unsigned long eventStart = 0;

void setup() {
  Serial.begin(9600);
  pinMode(LED_PIN, OUTPUT);
  Serial.println(F("Seismograph drum logger ready"));
}

void loop() {
  unsigned long now = millis();
  if (now - lastSample < SAMPLE_MS) return;
  lastSample = now;

  uint16_t raw = analogRead(SENSOR_PIN);

  // Track baseline only when quiet, so events don't drag it.
  if (!inEvent) {
    baseline = baseline - (baseline >> BASELINE_SHIFT)
             + (raw >> BASELINE_SHIFT);
  }

  int16_t dev = (int16_t)raw - (int16_t)baseline;
  uint16_t mag = (uint16_t)(dev < 0 ? -dev : dev);

  if (mag > THRESHOLD) {
    if (!inEvent) {
      inEvent = true;
      eventStart = now;
      peak = mag;
      digitalWrite(LED_PIN, HIGH);
    } else if (mag > peak) {
      peak = mag;
    }
  } else if (inEvent && (now - eventStart) > EVENT_HOLD_MS) {
    inEvent = false;
    digitalWrite(LED_PIN, LOW);
    Serial.print(F("EVENT t="));
    Serial.print(eventStart);
    Serial.print(F("ms peak="));
    Serial.println(peak);
  }
}

// Server rack fan controller
// Reads a thermistor on A0, drives a 4-wire fan PWM on pin 9
// and reports over Serial. Hobbyist build, be gentle.

const int THERM_PIN = A0;
const int FAN_PIN = 9;
const int LED_PIN = 13;

// thermistor is 10k NTC with 10k pullup to 5V
const float SERIES_R = 10000.0;
const float NOMINAL_R = 10000.0;
const float NOMINAL_T = 25.0;
const float B_COEF = 3950.0;

// fan curve
const float T_MIN = 30.0;   // below this, fan off
const float T_MAX = 60.0;   // above this, full blast
const int PWM_MIN = 60;     // fan stalls below this
const int PWM_MAX = 255;

unsigned long lastPrint = 0;

float readTempC() {
  int raw = analogRead(THERM_PIN);
  if (raw <= 0) raw = 1;
  if (raw >= 1023) raw = 1022;
  float r = SERIES_R * (float)raw / (1023.0 - (float)raw);
  float steinhart = r / NOMINAL_R;
  steinhart = log(steinhart);
  steinhart /= B_COEF;
  steinhart += 1.0 / (NOMINAL_T + 273.15);
  steinhart = 1.0 / steinhart;
  steinhart -= 273.15;
  return steinhart;
}

int tempToPwm(float t) {
  if (t < T_MIN) return 0;
  if (t >= T_MAX) return PWM_MAX;
  float frac = (t - T_MIN) / (T_MAX - T_MIN);
  int pwm = PWM_MIN + (int)(frac * (PWM_MAX - PWM_MIN));
  return pwm;
}

void setup() {
  pinMode(FAN_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
  Serial.println("Rack fan ctrl v0.3");
  analogWrite(FAN_PIN, 0);
}

void loop() {
  float t = readTempC();
  int pwm = tempToPwm(t);
  analogWrite(FAN_PIN, pwm);

  // blink LED if we're hot
  if (t > 50.0) {
    digitalWrite(LED_PIN, HIGH);
  } else {
    digitalWrite(LED_PIN, LOW);
  }

  if (millis() - lastPrint > 1000) {
    lastPrint = millis();
    Serial.print("T=");
    Serial.print(t, 1);
    Serial.print("C PWM=");
    Serial.println(pwm);
  }

  delay(100);
}

const uint8_t PIN_PEDAL = A0;
const uint8_t PIN_MOTOR = 9;
const uint8_t PIN_LED = 13;

const int PEDAL_MIN = 120;
const int PEDAL_MAX = 900;
const int DEADBAND = 25;
const unsigned long START_MS = 150;
const unsigned long STOP_MS = 400;

int lastRaw = 0;
int filtered = 0;
unsigned long lastChange = 0;
bool running = false;

void setup() {
  pinMode(PIN_MOTOR, OUTPUT);
  pinMode(PIN_LED, OUTPUT);
  Serial.begin(9600);
  filtered = analogRead(PIN_PEDAL);
  lastRaw = filtered;
}

int readPedal() {
  long sum = 0;
  for (uint8_t i = 0; i < 8; i++) {
    sum += analogRead(PIN_PEDAL);
    delayMicroseconds(200);
  }
  return (int)(sum / 8);
}

int toSpeed(int raw) {
  if (raw <= PEDAL_MIN) return 0;
  if (raw >= PEDAL_MAX) return 255;
  long span = PEDAL_MAX - PEDAL_MIN;
  long v = raw - PEDAL_MIN;
  return (int)((v * 255L) / span);
}

void loop() {
  int raw = readPedal();
  filtered = (filtered * 3 + raw) / 4;

  if (abs(filtered - lastRaw) > DEADBAND) {
    lastRaw = filtered;
    lastChange = millis();
  }

  int speed = toSpeed(filtered);
  unsigned long now = millis();

  if (speed > 0) {
    if (!running && (now - lastChange) >= START_MS) {
      running = true;
    }
    if (running) {
      analogWrite(PIN_MOTOR, speed);
      digitalWrite(PIN_LED, HIGH);
    } else {
      analogWrite(PIN_MOTOR, 0);
      digitalWrite(PIN_LED, LOW);
    }
  } else {
    if (running && (now - lastChange) >= STOP_MS) {
      running = false;
    }
    analogWrite(PIN_MOTOR, 0);
    digitalWrite(PIN_LED, LOW);
  }

  static unsigned long lastPrint = 0;
  if (now - lastPrint > 250) {
    lastPrint = now;
    Serial.print(filtered);
    Serial.print(' ');
    Serial.print(speed);
    Serial.print(' ');
    Serial.println(running ? 1 : 0);
  }
}

const uint8_t TRIG = 9;
const uint8_t ECHO = 10;
const uint8_t BUZZ = 6;
const uint8_t LED = 7;
const uint8_t ARM = 2;

const unsigned long PING_MS = 200;
const unsigned long BEEP_MS = 400;
const unsigned long HYST_MS = 3000;

unsigned long lastPing = 0;
unsigned long lastBeep = 0;
unsigned long lastChange = 0;
bool alarm = false;
bool beepOn = false;

long readCm() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long d = pulseIn(ECHO, HIGH, 30000UL);
  if (d == 0) return -1;
  return (long)(d / 58UL);
}

void setup() {
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(BUZZ, OUTPUT);
  pinMode(LED, OUTPUT);
  pinMode(ARM, INPUT_PULLUP);
  digitalWrite(BUZZ, LOW);
  digitalWrite(LED, LOW);
  Serial.begin(9600);
}

void loop() {
  unsigned long now = millis();

  if (now - lastPing >= PING_MS) {
    lastPing = now;
    long cm = readCm();
    if (cm > 0) {
      Serial.print(F("cm="));
      Serial.println(cm);
      bool want = (cm <= 40);
      if (want != alarm && now - lastChange >= HYST_MS) {
        alarm = want;
        lastChange = now;
      }
    }
  }

  bool armed = (digitalRead(ARM) == LOW);

  if (alarm && armed) {
    digitalWrite(LED, HIGH);
    if (now - lastBeep >= BEEP_MS) {
      lastBeep = now;
      beepOn = !beepOn;
      digitalWrite(BUZZ, beepOn ? HIGH : LOW);
    }
  } else {
    digitalWrite(LED, LOW);
    digitalWrite(BUZZ, LOW);
    beepOn = false;
  }
}

// ski lift gate counter
// counts people through the turnstile, shows on serial

const int beamPin = 2;      // IR beam, LOW when broken
const int ledPin = 13;      // onboard LED blinks per count
const int resetPin = 7;     // button to zero the count

int count = 0;
int lastBeam = HIGH;
unsigned long lastBlink = 0;
bool ledOn = false;

void setup() {
  pinMode(beamPin, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);
  pinMode(resetPin, INPUT_PULLUP);
  Serial.begin(9600);
  Serial.println("Ski lift gate counter ready");
}

void loop() {
  int beam = digitalRead(beamPin);

  // beam broken = someone passing
  if (beam == LOW && lastBeam == HIGH) {
    count++;
    Serial.print("Count: ");
    Serial.println(count);
    ledOn = true;
    lastBlink = millis();
    digitalWrite(ledPin, HIGH);
    delay(50); // debounce the beam a bit
  }
  lastBeam = beam;

  // turn LED back off after 100ms
  if (ledOn && millis() - lastBlink > 100) {
    digitalWrite(ledPin, LOW);
    ledOn = false;
  }

  // reset button
  if (digitalRead(resetPin) == LOW) {
    count = 0;
    Serial.println("Count reset");
    delay(300);
  }
}

/*
 * Sous Vide Bath Controller
 * -------------------------
 * Design notes:
 *  - A 10k NTC thermistor (B=3950) sits in a divider with a 10k resistor to 5V.
 *  - A relay on D9 switches the 120V heater; it is active HIGH.
 *  - A piezo on D8 gives a short beep when the target is reached.
 *  - Control is a simple bang-bang with 0.5 C hysteresis; good enough for a
 *    well-insulated pot and far simpler than PID tuning.
 *  - Serial at 9600 prints temperature once per second for debugging.
 */

const uint8_t  THERMISTOR_PIN = A0;
const uint8_t  HEATER_PIN     = 9;
const uint8_t  BUZZER_PIN     = 8;

const float    SERIES_RESISTOR = 10000.0;  // ohms, divider partner
const float    NOMINAL_R       = 10000.0;  // thermistor at 25 C
const float    NOMINAL_TEMP_C  = 25.0;
const float    BETA           = 3950.0;

const float    TARGET_C       = 63.0;      // medium-rare steak
const float    HYSTERESIS_C   = 0.5;

bool  heaterOn   = false;
bool  beeped     = false;
unsigned long lastPrint = 0;

float readTemperatureC() {
  int raw = analogRead(THERMISTOR_PIN);
  if (raw <= 0) raw = 1;
  if (raw >= 1023) raw = 1022;

  // Thermistor is on the high side: R_therm = R_series * raw / (1023 - raw)
  float rTherm = SERIES_RESISTOR * (float)raw / (1023.0 - (float)raw);

  float steinhart = rTherm / NOMINAL_R;
  steinhart = log(steinhart);
  steinhart /= BETA;
  steinhart += 1.0 / (NOMINAL_TEMP_C + 273.15);
  steinhart = 1.0 / steinhart;
  return steinhart - 273.15;
}

void setHeater(bool on) {
  heaterOn = on;
  digitalWrite(HEATER_PIN, on ? HIGH : LOW);
}

void setup() {
  pinMode(HEATER_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  setHeater(false);
  Serial.begin(9600);
  Serial.println(F("Sous vide controller ready"));
}

void loop() {
  float tempC = readTemperatureC();

  if (!heaterOn && tempC < TARGET_C - HYSTERESIS_C) {
    setHeater(true);
  } else if (heaterOn && tempC > TARGET_C + HYSTERESIS_C) {
    setHeater(false);
  }

  if (!beeped && tempC >= TARGET_C - HYSTERESIS_C) {
    tone(BUZZER_PIN, 2000, 150);
    beeped = true;
  }

  unsigned long now = millis();
  if (now - lastPrint >= 1000) {
    lastPrint = now;
    Serial.print(F("T="));
    Serial.print(tempC, 2);
    Serial.print(F(" C  heater="));
    Serial.println(heaterOn ? F("ON") : F("OFF"));
  }

  delay(100);
}

// Tanning Bed Timeout Controller
// Written by a beginner, so I explain everything.
// Goal: turn on the tanning lamps, but NEVER let them run longer
// than the allowed time. Safety first!

// ---- Pin setup ----
// Pin 7 drives the relay that switches the lamps.
// (Ignore pin 13's LED - it's just the onboard LED and not used here.)
const int LAMP_RELAY_PIN = 7;

// Pin 2 is the start button. We use INPUT_PULLUP so the button
// connects to GND when pressed. That means pressed = LOW.
const int START_BUTTON_PIN = 2;

// Pin 3 is the stop button, also wired to GND, also INPUT_PULLUP.
const int STOP_BUTTON_PIN = 3;

// ---- Timing ----
// The maximum session is 20 minutes = 20 * 60 * 1000 ms.
// I use unsigned long because millis() returns unsigned long.
const unsigned long MAX_SESSION_MS = 20UL * 60UL * 1000UL;

// How long the lamps have been on. Reset when we start.
unsigned long sessionStart = 0;

// Are the lamps on right now?
bool lampsOn = false;

void setup() {
  // Relay pin is an output. LOW = relay off = lamps off.
  pinMode(LAMP_RELAY_PIN, OUTPUT);
  digitalWrite(LAMP_RELAY_PIN, LOW);

  // Buttons are inputs with internal pull-ups.
  pinMode(START_BUTTON_PIN, INPUT_PULLUP);
  pinMode(STOP_BUTTON_PIN, INPUT_PULLUP);

  // Serial is only for debugging. You can ignore it in normal use.
  Serial.begin(9600);
  Serial.println("Tanning bed controller ready");
}

void loop() {
  // Read the buttons. Remember: LOW means pressed.
  bool startPressed = (digitalRead(START_BUTTON_PIN) == LOW);
  bool stopPressed = (digitalRead(STOP_BUTTON_PIN) == LOW);

  // STOP always wins. If stop is pressed, kill the lamps immediately.
  if (stopPressed && lampsOn) {
    turnLampsOff();
    Serial.println("Stopped by button");
  }

  // Start only if the lamps are currently off.
  // (If they're already on, pressing start does nothing - that's fine.)
  if (startPressed && !lampsOn) {
    lampsOn = true;
    sessionStart = millis();
    digitalWrite(LAMP_RELAY_PIN, HIGH);
    Serial.println("Session started");
  }

  // If the lamps are on, check whether the max time has passed.
  if (lampsOn) {
    unsigned long elapsed = millis() - sessionStart;
    if (elapsed >= MAX_SESSION_MS) {
      turnLampsOff();
      Serial.println("Timeout - lamps off");
    }
  }

  // Small delay so button reads are not too twitchy.
  // This is not real debouncing, but it's good enough for a beginner.
  delay(50);
}

// Helper to turn the lamps off and remember the state.
void turnLampsOff() {
  digitalWrite(LAMP_RELAY_PIN, LOW);
  lampsOn = false;
}

// Tattoo machine foot switch
// Press pedal -> machine runs. Tap twice quickly -> stays on (lock).
// Hold 1.5s -> off. Uses a relay on D8 and a pedal on D2.

const int PEDAL_PIN = 2;   // pedal switch to GND, internal pullup
const int RELAY_PIN = 8;   // relay module input
const int LED_PIN   = 13;  // onboard led mirrors relay

const unsigned long DEBOUNCE_MS = 25;
const unsigned long HOLD_MS     = 1500;
const unsigned long TAP_MS      = 350;  // max gap between two taps

bool pedalDown = false;
bool lastReading = false;
unsigned long lastChange = 0;
unsigned long pressStart = 0;
unsigned long lastRelease = 0;

bool machineOn = false;
bool locked = false;
int tapCount = 0;

void setup() {
  pinMode(PEDAL_PIN, INPUT_PULLUP);
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
  Serial.begin(9600);
  Serial.println("foot switch ready");
}

void setMachine(bool on) {
  machineOn = on;
  digitalWrite(RELAY_PIN, on ? HIGH : LOW);
  digitalWrite(LED_PIN, on ? HIGH : LOW);
}

void loop() {
  // pedal is active low because of pullup
  bool reading = (digitalRead(PEDAL_PIN) == LOW);
  unsigned long now = millis();

  if (reading != lastReading) {
    lastChange = now;
    lastReading = reading;
  }

  if ((now - lastChange) >= DEBOUNCE_MS && reading != pedalDown) {
    pedalDown = reading;

    if (pedalDown) {
      pressStart = now;
      // count taps for the double tap lock
      if ((now - lastRelease) < TAP_MS) {
        tapCount++;
      } else {
        tapCount = 1;
      }
      if (!locked) setMachine(true);
    } else {
      lastRelease = now;
      if (!locked) setMachine(false);
    }
  }

  // hold to turn everything off
  if (pedalDown && (now - pressStart) >= HOLD_MS) {
    if (machineOn || locked) {
      locked = false;
      tapCount = 0;
      setMachine(false);
      Serial.println("hold: off");
    }
  }

  // two quick taps = lock on
  if (tapCount >= 2 && !locked) {
    locked = true;
    tapCount = 0;
    setMachine(true);
    Serial.println("locked on");
  }

  // forget old taps
  if (!pedalDown && (now - lastRelease) > TAP_MS) {
    tapCount = 0;
  }
}

/*
 * Telescope Dew Heater Controller
 * --------------------------------
 * Design notes:
 *  - A single N-channel MOSFET (via a gate resistor) switches 12V into a
 *    resistive heater strap wrapped around the telescope objective.
 *  - A 10k NTC thermistor in a divider senses strap temperature; we use the
 *    simple B-parameter (beta) equation, good enough for dew control.
 *  - PWM is slow (about 490 Hz on pin 9) so the MOSFET stays in switching mode
 *    and the strap thermal mass smooths the ripple.
 *  - Control is bang-bang with hysteresis: heat below SETPOINT - HYST, stop
 *    above SETPOINT + HYST. Simple, robust, and no PID tuning needed.
 *  - A heartbeat LED blinks once per second so you can tell it is alive.
 */

const uint8_t  HEATER_PIN     = 9;    // PWM output to MOSFET gate driver
const uint8_t  THERMISTOR_PIN = A0;   // NTC divider midpoint
const uint8_t  LED_PIN        = 13;   // onboard heartbeat LED

const float    SERIES_R       = 10000.0; // divider fixed resistor, ohms
const float    NOMINAL_R      = 10000.0; // thermistor resistance at 25C
const float    NOMINAL_T      = 25.0;    // nominal temperature, Celsius
const float    BETA           = 3950.0;  // thermistor beta coefficient
const float    SETPOINT_C     = 12.0;    // target strap temperature
const float    HYST_C         = 1.0;     // hysteresis band, +/- degrees
const uint8_t  HEATER_DUTY    = 200;     // PWM duty when heating (0-255)
const uint32_t SAMPLE_MS      = 500;     // temperature sample period
const uint32_t BLINK_MS       = 1000;    // heartbeat period

float    currentTempC = 0.0;
bool     heaterOn     = false;
uint32_t lastSampleMs = 0;
uint32_t lastBlinkMs  = 0;
bool     ledState     = false;

float readThermistorC() {
  int raw = analogRead(THERMISTOR_PIN);
  if (raw <= 0) raw = 1;          // avoid divide-by-zero at the rail
  if (raw >= 1023) raw = 1022;    // avoid infinite resistance

  // Thermistor is on the high side: R_ntc = R_series * raw / (1023 - raw)
  float rNtc = SERIES_R * (float)raw / (1023.0 - (float)raw);

  // Beta equation: 1/T = 1/T0 + (1/B) * ln(R/R0), temperatures in Kelvin
  float invT = 1.0 / (NOMINAL_T + 273.15)
             + (1.0 / BETA) * log(rNtc / NOMINAL_R);
  float tempK = 1.0 / invT;
  return tempK - 273.15;
}

void setup() {
  pinMode(HEATER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  analogWrite(HEATER_PIN, 0);
  Serial.begin(9600);
  Serial.println(F("Dew heater starting"));
}

void loop() {
  uint32_t now = millis();

  if (now - lastSampleMs >= SAMPLE_MS) {
    lastSampleMs = now;
    currentTempC = readThermistorC();

    if (!heaterOn && currentTempC < SETPOINT_C - HYST_C) {
      heaterOn = true;
      analogWrite(HEATER_PIN, HEATER_DUTY);
    } else if (heaterOn && currentTempC > SETPOINT_C + HYST_C) {
      heaterOn = false;
      analogWrite(HEATER_PIN, 0);
    }

    Serial.print(F("T="));
    Serial.print(currentTempC, 1);
    Serial.print(F("C heater="));
    Serial.println(heaterOn ? F("ON") : F("OFF"));
  }

  if (now - lastBlinkMs >= BLINK_MS) {
    lastBlinkMs = now;
    ledState = !ledState;
    digitalWrite(LED_PIN, ledState ? HIGH : LOW);
  }
}

/*
 * Theatre Fog Machine Trigger
 * ---------------------------
 * Design notes:
 *  - A momentary pushbutton on D2 (INPUT_PULLUP, active LOW) requests a fog burst.
 *  - The fog machine's remote input is driven by D9 through an NPN transistor
 *    (or opto-isolator); HIGH = trigger asserted.
 *  - A burst is held for BURST_MS, then a cooldown of COOLDOWN_MS is enforced
 *    so the heater can recover. Requests during cooldown are ignored.
 *  - A status LED on D13 mirrors the trigger output.
 *  - Debounce is done with a simple timestamp, no libraries.
 */

const uint8_t  BUTTON_PIN   = 2;
const uint8_t  TRIGGER_PIN  = 9;
const uint8_t  LED_PIN      = 13;

const uint32_t BURST_MS     = 3000;   // how long fog is sprayed
const uint32_t COOLDOWN_MS  = 5000;   // heater recovery time
const uint32_t DEBOUNCE_MS  = 30;

enum State { IDLE, BURSTING, COOLING };

State    state          = IDLE;
uint32_t stateStart     = 0;
uint32_t lastButtonEdge = 0;
int      lastButtonRead = HIGH;

void setTrigger(bool on) {
  digitalWrite(TRIGGER_PIN, on ? HIGH : LOW);
  digitalWrite(LED_PIN,     on ? HIGH : LOW);
}

void enterState(State s) {
  state      = s;
  stateStart = millis();
  setTrigger(s == BURSTING);
}

void setup() {
  pinMode(BUTTON_PIN,  INPUT_PULLUP);
  pinMode(TRIGGER_PIN, OUTPUT);
  pinMode(LED_PIN,     OUTPUT);
  setTrigger(false);
}

void loop() {
  uint32_t now = millis();

  // Debounced falling-edge detection on the button.
  int reading = digitalRead(BUTTON_PIN);
  if (reading != lastButtonRead) {
    lastButtonEdge = now;
    lastButtonRead = reading;
  }
  bool pressed = (reading == LOW) && (now - lastButtonEdge >= DEBOUNCE_MS);

  switch (state) {
    case IDLE:
      if (pressed) enterState(BURSTING);
      break;

    case BURSTING:
      if (now - stateStart >= BURST_MS) enterState(COOLING);
      break;

    case COOLING:
      if (now - stateStart >= COOLDOWN_MS) enterState(IDLE);
      break;
  }
}

/*
 * Tortoise Basking Lamp Controller
 * ---------------------------------
 * Design: a single basking lamp is switched by a relay on D7. A thermistor
 * on A0 senses the basking spot. The lamp turns ON when the spot is cooler
 * than TARGET_LOW_C and OFF when it is warmer than TARGET_HIGH_C, giving a
 * small hysteresis band so the relay does not chatter. A safety cutoff
 * forces the lamp off if the spot exceeds MAX_SAFE_C. Readings are averaged
 * over several samples to reject noise. Serial prints state for debugging.
 */

const uint8_t LAMP_PIN = 7;
const uint8_t THERMISTOR_PIN = A0;

const float TARGET_LOW_C = 30.0;
const float TARGET_HIGH_C = 34.0;
const float MAX_SAFE_C = 42.0;

const uint8_t SAMPLES = 8;
const unsigned long LOOP_INTERVAL_MS = 1000;

// Thermistor divider: 10k series resistor to 5V, thermistor to GND.
const float SERIES_RESISTOR = 10000.0;
const float NOMINAL_RESISTANCE = 10000.0;
const float NOMINAL_TEMP_C = 25.0;
const float BETA = 3950.0;

bool lampOn = false;
unsigned long lastCheck = 0;

float readTemperatureC() {
  long total = 0;
  for (uint8_t i = 0; i < SAMPLES; i++) {
    total += analogRead(THERMISTOR_PIN);
    delay(5);
  }
  float raw = total / (float)SAMPLES;
  if (raw <= 0.0) raw = 1.0;
  if (raw >= 1023.0) raw = 1022.0;

  float resistance = SERIES_RESISTOR * (raw / (1023.0 - raw));
  float steinhart = resistance / NOMINAL_RESISTANCE;
  steinhart = log(steinhart);
  steinhart /= BETA;
  steinhart += 1.0 / (NOMINAL_TEMP_C + 273.15);
  steinhart = 1.0 / steinhart;
  return steinhart - 273.15;
}

void setLamp(bool on) {
  lampOn = on;
  digitalWrite(LAMP_PIN, on ? HIGH : LOW);
}

void setup() {
  pinMode(LAMP_PIN, OUTPUT);
  digitalWrite(LAMP_PIN, LOW);
  Serial.begin(9600);
  Serial.println(F("Tortoise basking lamp controller ready"));
}

void loop() {
  unsigned long now = millis();
  if (now - lastCheck < LOOP_INTERVAL_MS) return;
  lastCheck = now;

  float tempC = readTemperatureC();

  if (tempC > MAX_SAFE_C) {
    setLamp(false);
  } else if (tempC < TARGET_LOW_C) {
    setLamp(true);
  } else if (tempC > TARGET_HIGH_C) {
    setLamp(false);
  }

  Serial.print(F("Temp C: "));
  Serial.print(tempC, 1);
  Serial.print(F("  Lamp: "));
  Serial.println(lampOn ? F("ON") : F("OFF"));
}

#include <LiquidCrystal.h>

LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

const uint8_t BTN = 7;
const uint8_t BUZ = 8;
const uint8_t RELAY = 9;

const uint16_t PRESETS[] = {30, 60, 120, 180, 300, 480};
const uint8_t NPRESET = sizeof(PRESETS) / sizeof(PRESETS[0]);

uint8_t idx = 1;
bool running = false;
uint32_t remainMs = 0;
uint32_t lastTick = 0;
bool lastBtn = HIGH;
uint32_t btnDown = 0;
bool longFired = false;

void showTime(uint32_t ms) {
  uint16_t s = (ms + 999) / 1000;
  lcd.setCursor(0, 1);
  lcd.print(' ');
  lcd.print(s / 60);
  lcd.print(':');
  if (s % 60 < 10) lcd.print('0');
  lcd.print(s % 60);
  lcd.print("   ");
}

void draw() {
  lcd.setCursor(0, 0);
  if (running) lcd.print("CLEANING    ");
  else lcd.print("READY       ");
  showTime(running ? remainMs : (uint32_t)PRESETS[idx] * 1000UL);
}

void beep(uint16_t ms) {
  digitalWrite(BUZ, HIGH);
  delay(ms);
  digitalWrite(BUZ, LOW);
}

void start() {
  remainMs = (uint32_t)PRESETS[idx] * 1000UL;
  running = true;
  digitalWrite(RELAY, HIGH);
  lastTick = millis();
  draw();
}

void stop() {
  running = false;
  digitalWrite(RELAY, LOW);
  draw();
}

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  pinMode(BUZ, OUTPUT);
  pinMode(RELAY, OUTPUT);
  digitalWrite(RELAY, LOW);
  lcd.begin(16, 2);
  lcd.print("Ultrasonic");
  delay(800);
  lcd.clear();
  draw();
}

void loop() {
  bool b = digitalRead(BTN);
  uint32_t now = millis();

  if (b == LOW && lastBtn == HIGH) {
    btnDown = now;
    longFired = false;
  }
  if (b == LOW && !longFired && now - btnDown > 700) {
    longFired = true;
    if (running) stop();
    else {
      idx = (idx + 1) % NPRESET;
      draw();
      beep(40);
    }
  }
  if (b == HIGH && lastBtn == LOW && !longFired) {
    if (running) stop();
    else start();
  }
  lastBtn = b;

  if (running) {
    uint32_t d = now - lastTick;
    lastTick = now;
    if (d >= remainMs) {
      remainMs = 0;
      stop();
      for (uint8_t i = 0; i < 3; i++) { beep(150); delay(120); }
    } else {
      remainMs -= d;
      static uint32_t acc = 0;
      acc += d;
      if (acc >= 250) { acc = 0; showTime(remainMs); }
    }
  }
}

#include <Arduino.h>

const uint8_t PIN_TEMP = A0;
const uint8_t PIN_WIND = 2;
const uint8_t PIN_RELAY = 7;
const uint8_t PIN_LED = 13;
const uint8_t PIN_BTN = 4;

const int TEMP_ON = 2;
const int TEMP_OFF = 5;
const unsigned long WIND_MIN_MS = 1500;
const unsigned long START_DELAY = 3000;
const unsigned long MIN_RUN = 60000;

bool running = false;
bool manual = false;
unsigned long lastEdge = 0;
unsigned long runStart = 0;
unsigned long pendingStart = 0;
bool pending = false;

int readTempC() {
  int raw = analogRead(PIN_TEMP);
  return map(raw, 0, 1023, -10, 40);
}

bool windOk() {
  return (millis() - lastEdge) < WIND_MIN_MS;
}

void windISR() {
  lastEdge = millis();
}

void startFan() {
  digitalWrite(PIN_RELAY, HIGH);
  digitalWrite(PIN_LED, HIGH);
  running = true;
  runStart = millis();
  pending = false;
}

void stopFan() {
  digitalWrite(PIN_RELAY, LOW);
  digitalWrite(PIN_LED, LOW);
  running = false;
}

void setup() {
  pinMode(PIN_RELAY, OUTPUT);
  pinMode(PIN_LED, OUTPUT);
  pinMode(PIN_BTN, INPUT_PULLUP);
  pinMode(PIN_WIND, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(PIN_WIND), windISR, FALLING);
  Serial.begin(9600);
  stopFan();
}

void loop() {
  int t = readTempC();
  bool w = windOk();

  if (digitalRead(PIN_BTN) == LOW) {
    delay(30);
    if (digitalRead(PIN_BTN) == LOW) {
      manual = !manual;
      while (digitalRead(PIN_BTN) == LOW) delay(10);
    }
  }

  if (manual) {
    if (!running) startFan();
  } else {
    if (!running && t <= TEMP_ON && w) {
      if (!pending) { pending = true; pendingStart = millis(); }
      if (millis() - pendingStart >= START_DELAY) startFan();
    } else if (running && t >= TEMP_OFF && (millis() - runStart) > MIN_RUN) {
      stopFan();
    }
  }

  Serial.print(t); Serial.print(' ');
  Serial.print(w); Serial.print(' ');
  Serial.println(running);
  delay(200);
}

// Violin Humidifier Light
// A little light that tells you when your violin case is too dry.
// Written by a beginner, so lots of comments. Ignore the ones that say IGNORE.

// ---- Pin setup ----
// A0 reads the humidity sensor (a simple analog one, like a DHT but analog-ish).
// IGNORE: real DHT sensors need a library. This is a pretend analog humidity sensor
// that outputs 0-1023. We just map it to percent. Good enough for a test.
const int sensorPin = A0;

// LED pins. Green = fine, yellow = getting dry, red = too dry.
const int greenLed = 8;
const int yellowLed = 9;
const int redLed = 10;

// ---- Thresholds (in percent humidity) ----
// Violins like roughly 40-60% RH. Below 35% is scary.
const int dryThreshold = 35;   // below this = red
const int okThreshold = 45;    // below this (but above dry) = yellow

// ---- Timing ----
// Read the sensor every 2 seconds. No need to go faster.
const unsigned long readInterval = 2000;
unsigned long lastRead = 0;

void setup() {
  // Set the LED pins as outputs so we can turn them on and off.
  pinMode(greenLed, OUTPUT);
  pinMode(yellowLed, OUTPUT);
  pinMode(redLed, OUTPUT);

  // Serial is handy for debugging. 9600 is the classic speed.
  Serial.begin(9600);
  Serial.println("Violin humidifier light starting up...");
}

void loop() {
  // Only read every 2 seconds. millis() is like a stopwatch since power-on.
  unsigned long now = millis();
  if (now - lastRead >= readInterval) {
    lastRead = now;

    // Read the raw sensor value (0 to 1023).
    int raw = analogRead(sensorPin);

    // Map raw to a humidity percent. IGNORE: this mapping is made up,
    // but it gives us a number between 0 and 100 to work with.
    int humidity = map(raw, 0, 1023, 0, 100);

    // Print it so we can see what's going on in the Serial Monitor.
    Serial.print("Raw: ");
    Serial.print(raw);
    Serial.print("  Humidity: ");
    Serial.print(humidity);
    Serial.println("%");

    // Decide which light to show. Only one at a time.
    if (humidity < dryThreshold) {
      // Too dry! Red light.
      setLights(LOW, LOW, HIGH);
      Serial.println("TOO DRY - add water!");
    } else if (humidity < okThreshold) {
      // Getting dry. Yellow warning.
      setLights(LOW, HIGH, LOW);
      Serial.println("Getting dry...");
    } else {
      // All good. Green.
      setLights(HIGH, LOW, LOW);
      Serial.println("Humidity OK");
    }
  }

  // IGNORE: nothing else to do here. The LEDs stay on until the next read.
}

// Small helper so I don't repeat digitalWrite three times.
void setLights(int green, int yellow, int red) {
  digitalWrite(greenLed, green);
  digitalWrite(yellowLed, yellow);
  digitalWrite(redLed, red);
}

// Weather balloon cutdown timer
// Fires a nichrome cutter after a set time, or on command

const int CUT_PIN = 9;        // MOSFET gate for nichrome
const int LED_PIN = 13;       // status LED
const int BUTTON_PIN = 2;     // manual cut button

// 90 minutes flight time
const unsigned long CUT_TIME = 90UL * 60UL * 1000UL;
const unsigned long BURN_TIME = 4000;  // 4 sec burn

unsigned long startMillis;
bool cutDone = false;
bool burning = false;
unsigned long burnStart;

void setup() {
  pinMode(CUT_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  digitalWrite(CUT_PIN, LOW);
  startMillis = millis();
  // quick blink to show we booted
  for (int i = 0; i < 3; i++) {
    digitalWrite(LED_PIN, HIGH);
    delay(150);
    digitalWrite(LED_PIN, LOW);
    delay(150);
  }
}

void loop() {
  unsigned long now = millis();

  // manual cut, button pulls low
  if (digitalRead(BUTTON_PIN) == LOW && !cutDone) {
    startCut();
  }

  // timed cut
  if (!cutDone && (now - startMillis >= CUT_TIME)) {
    startCut();
  }

  // run the burn for a fixed time
  if (burning) {
    if (now - burnStart >= BURN_TIME) {
      digitalWrite(CUT_PIN, LOW);
      burning = false;
    }
  }

  // heartbeat blink, faster once cut
  static unsigned long lastBlink = 0;
  unsigned long period = cutDone ? 200 : 1000;
  if (now - lastBlink >= period) {
    lastBlink = now;
    digitalWrite(LED_PIN, !digitalRead(LED_PIN));
  }
}

void startCut() {
  digitalWrite(CUT_PIN, HIGH);
  burning = true;
  burnStart = millis();
  cutDone = true;
}

// Wind Tunnel Smoke Valve Controller
// Written by a beginner, so lots of comments. Sorry in advance.

// This is the pin the servo signal wire goes to.
// Ignore the PWM markings on pin 9 - the Servo library handles that itself.
const int SERVO_PIN = 9;

// A pushbutton to open/close the valve manually.
// We use INPUT_PULLUP so we don't need an external resistor.
// That means the button reads LOW when pressed. Confusing but normal.
const int BUTTON_PIN = 2;

// An LED so we can see if the valve is supposed to be open.
const int LED_PIN = 13;

// Servo positions. 0 = closed, 90 = fully open.
// I picked 90 because the valve arm hits the tunnel wall past that.
const int CLOSED_ANGLE = 0;
const int OPEN_ANGLE = 90;

// How long to wait after moving before we trust the position.
// The valve is a bit slow, 500 ms seemed fine in testing.
const unsigned long MOVE_TIME = 500;

bool valveOpen = false;
bool lastButtonState = HIGH;
unsigned long lastDebounceTime = 0;
const unsigned long DEBOUNCE_MS = 50;

// We can't use the Servo library? Actually we can, it's in the core.
// I'll include it here. Ignore the warning about it using Timer1.
#include <Servo.h>
Servo smokeValve;

void setup() {
  // Set up the button with the internal pull-up.
  pinMode(BUTTON_PIN, INPUT_PULLUP);

  // LED output.
  pinMode(LED_PIN, OUTPUT);

  // Attach the servo and start closed.
  smokeValve.attach(SERVO_PIN);
  smokeValve.write(CLOSED_ANGLE);

  // Start with LED off (valve closed).
  digitalWrite(LED_PIN, LOW);

  // Small delay so the servo can get to closed before we do anything.
  delay(MOVE_TIME);
}

void loop() {
  // Read the button. Remember: LOW means pressed.
  bool reading = digitalRead(BUTTON_PIN);

  // Debounce: only accept a change if it's been stable for a bit.
  if (reading != lastButtonState) {
    lastDebounceTime = millis();
  }

  if ((millis() - lastDebounceTime) > DEBOUNCE_MS) {
    // If the button is pressed (LOW) and we haven't already toggled...
    // Actually we toggle on the falling edge. Let me just check state.
    if (reading == LOW && lastButtonState == HIGH) {
      valveOpen = !valveOpen;

      if (valveOpen) {
        smokeValve.write(OPEN_ANGLE);
        digitalWrite(LED_PIN, HIGH);
      } else {
        smokeValve.write(CLOSED_ANGLE);
        digitalWrite(LED_PIN, LOW);
      }

      // Give the valve time to move so we don't spam it.
      delay(MOVE_TIME);
    }
  }

  // Save the reading for next time.
  lastButtonState = reading;
}

// Filament runout detector
// IR sensor in the filament path, buzzer + LED alarm

const int SENSOR_PIN = 2;   // IR sensor, LOW = filament present
const int BUZZER_PIN = 8;
const int LED_PIN = 13;

const unsigned long DEBOUNCE_MS = 50;
const unsigned long BEEP_ON_MS = 200;
const unsigned long BEEP_OFF_MS = 800;

bool filamentPresent = true;
bool lastReading = true;
unsigned long lastChange = 0;

bool alarmActive = false;
unsigned long lastBeep = 0;
bool buzzerOn = false;

void setup() {
  pinMode(SENSOR_PIN, INPUT_PULLUP);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(BUZZER_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
  Serial.begin(9600);
  Serial.println("Filament runout detector ready");
}

void loop() {
  // sensor reads LOW when filament is there
  bool reading = (digitalRead(SENSOR_PIN) == LOW);

  if (reading != lastReading) {
    lastChange = millis();
    lastReading = reading;
  }

  if ((millis() - lastChange) > DEBOUNCE_MS) {
    if (reading != filamentPresent) {
      filamentPresent = reading;
      if (filamentPresent) {
        Serial.println("Filament OK");
        alarmActive = false;
        digitalWrite(LED_PIN, LOW);
        digitalWrite(BUZZER_PIN, LOW);
        buzzerOn = false;
      } else {
        Serial.println("RUNOUT!");
        alarmActive = true;
        digitalWrite(LED_PIN, HIGH);
        lastBeep = millis();
        buzzerOn = true;
        digitalWrite(BUZZER_PIN, HIGH);
      }
    }
  }

  // beep pattern while alarm is on
  if (alarmActive) {
    unsigned long now = millis();
    if (buzzerOn && (now - lastBeep) >= BEEP_ON_MS) {
      digitalWrite(BUZZER_PIN, LOW);
      buzzerOn = false;
      lastBeep = now;
    } else if (!buzzerOn && (now - lastBeep) >= BEEP_OFF_MS) {
      digitalWrite(BUZZER_PIN, HIGH);
      buzzerOn = true;
      lastBeep = now;
    }
  }
}

const uint8_t ESTOP_PIN = 2;
const uint8_t RELAY_PIN = 7;
const uint8_t LED_PIN = 13;
const uint8_t BUZZER_PIN = 8;

const unsigned long DEBOUNCE_MS = 25;
const unsigned long HOLD_MS = 1500;

bool estopLatched = false;
bool lastRaw = true;
bool stableState = true;
unsigned long lastChange = 0;
unsigned long latchTime = 0;

void setup() {
  pinMode(ESTOP_PIN, INPUT_PULLUP);
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
  digitalWrite(BUZZER_PIN, LOW);
  Serial.begin(9600);
  Serial.println(F("ESTOP monitor ready"));
}

void loop() {
  bool raw = digitalRead(ESTOP_PIN);
  unsigned long now = millis();

  if (raw != lastRaw) {
    lastChange = now;
    lastRaw = raw;
  }

  if ((now - lastChange) >= DEBOUNCE_MS && raw != stableState) {
    stableState = raw;
    if (!stableState && !estopLatched) {
      estopLatched = true;
      latchTime = now;
      digitalWrite(RELAY_PIN, LOW);
      digitalWrite(BUZZER_PIN, HIGH);
      Serial.println(F("ESTOP TRIPPED"));
    }
  }

  if (estopLatched) {
    digitalWrite(LED_PIN, (now / 250) % 2);
    if (stableState && (now - latchTime) >= HOLD_MS) {
      estopLatched = false;
      digitalWrite(RELAY_PIN, HIGH);
      digitalWrite(BUZZER_PIN, LOW);
      digitalWrite(LED_PIN, HIGH);
      Serial.println(F("ESTOP CLEARED"));
    }
  } else {
    digitalWrite(LED_PIN, HIGH);
    digitalWrite(RELAY_PIN, HIGH);
    digitalWrite(BUZZER_PIN, LOW);
  }
}

// LED Bar Graph Voltmeter
// Reads a voltage on A0 and lights up more LEDs as the voltage rises.
// Written by a beginner, so lots of comments. Hope it helps someone!

// ---- Pin setup ----
// We use pins 2 through 7 for the LED bar graph, lowest LED first.
// (Ignore pins 0 and 1 - those are the serial pins and we don't need them here.)
const int firstLed = 2;
const int numLeds = 6;

// Analog input pin. A0 is the first analog pin on the Uno.
const int sensorPin = A0;

// ---- Voltage math ----
// The Uno's ADC gives us 0..1023 for 0..5V by default.
// We want to show a 0..10V range, so we use a simple 2:1 divider
// (two equal resistors) on the input. That means the pin only ever
// sees half the real voltage, so we multiply back by 2.
const float adcMax = 1023.0;
const float vRef = 5.0;
const float dividerRatio = 2.0;

// Each LED should come on at a step of this many volts.
// 10V range / 6 LEDs = about 1.67V per step.
const float voltsPerStep = 10.0 / numLeds;

void setup() {
  // Set all the LED pins as outputs.
  // (Ignore the analog pins here - they are inputs by default.)
  for (int i = 0; i < numLeds; i++) {
    pinMode(firstLed + i, OUTPUT);
    digitalWrite(firstLed + i, LOW);
  }

  // Serial is handy for debugging. 9600 baud is plenty.
  Serial.begin(9600);
}

void loop() {
  // Step 1: read the raw ADC value (0..1023).
  int raw = analogRead(sensorPin);

  // Step 2: turn that into the voltage at the pin.
  float pinVolts = (raw / adcMax) * vRef;

  // Step 3: undo the divider to get the real input voltage.
  float realVolts = pinVolts * dividerRatio;

  // Step 4: figure out how many LEDs should be lit.
  // We add a tiny bit so the first LED comes on just above 0V.
  int lit = (int)(realVolts / voltsPerStep + 0.5);

  // Clamp it so we never try to light more LEDs than we have.
  if (lit > numLeds) {
    lit = numLeds;
  }
  if (lit < 0) {
    lit = 0;
  }

  // Step 5: drive the LEDs. Light the first 'lit' of them.
  for (int i = 0; i < numLeds; i++) {
    if (i < lit) {
      digitalWrite(firstLed + i, HIGH);
    } else {
      digitalWrite(firstLed + i, LOW);
    }
  }

  // Step 6: print for debugging. Not required, but nice.
  Serial.print("raw=");
  Serial.print(raw);
  Serial.print(" volts=");
  Serial.print(realVolts, 2);
  Serial.print(" leds=");
  Serial.println(lit);

  // Small delay so the display isn't flickering like crazy.
  delay(100);
}

// Simple Morse keyer
// Press button, it beeps a dot or dash depending on hold time

const int buttonPin = 2;
const int buzzerPin = 8;

const unsigned int dotLen = 120;   // ms
const unsigned int dashLen = 360;  // ms

unsigned long pressStart = 0;
bool pressed = false;
bool wasPressed = false;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);
  pinMode(buzzerPin, OUTPUT);
  Serial.begin(9600);
  Serial.println("Morse keyer ready");
}

void loop() {
  bool now = (digitalRead(buttonPin) == LOW);

  if (now && !wasPressed) {
    // button just went down
    pressStart = millis();
    pressed = true;
  }

  if (!now && wasPressed && pressed) {
    // button released - decide dot or dash
    unsigned long held = millis() - pressStart;
    if (held < 200) {
      Serial.println(".");
      beep(dotLen);
    } else {
      Serial.println("-");
      beep(dashLen);
    }
    pressed = false;
  }

  wasPressed = now;
}

void beep(unsigned int len) {
  tone(buzzerPin, 700);
  delay(len);
  noTone(buzzerPin);
  delay(dotLen); // gap between elements
}

/*
 * PWM Dimmer with a Knob
 * -----------------------
 * Design notes:
 *   - A 10k potentiometer on A0 sets the brightness of an LED on pin 9.
 *   - Pin 9 is one of the Uno's hardware PWM pins (Timer1), so we use
 *     analogWrite() for a clean 0-255 duty cycle.
 *   - The ADC is 10-bit (0-1023); we map that range onto the PWM range.
 *   - A small deadband at the bottom keeps the LED fully off when the
 *     knob is turned all the way down, avoiding faint glow.
 *   - We only call analogWrite() when the value actually changes, which
 *     keeps loop() cheap and avoids needless timer writes.
 */

const uint8_t  KNOB_PIN      = A0;
const uint8_t  LED_PIN       = 9;
const int      ADC_MAX       = 1023;
const int      PWM_MAX       = 255;
const int      OFF_THRESHOLD = 8;   // ADC counts below this = fully off

int lastPwm = -1;  // sentinel so the first write always happens

void setup() {
  pinMode(LED_PIN, OUTPUT);
  analogWrite(LED_PIN, 0);
  Serial.begin(9600);
}

void loop() {
  int raw = analogRead(KNOB_PIN);

  int pwm;
  if (raw < OFF_THRESHOLD) {
    pwm = 0;
  } else {
    pwm = map(raw, OFF_THRESHOLD, ADC_MAX, 0, PWM_MAX);
    pwm = constrain(pwm, 0, PWM_MAX);
  }

  if (pwm != lastPwm) {
    analogWrite(LED_PIN, pwm);
    lastPwm = pwm;
    Serial.print("ADC=");
    Serial.print(raw);
    Serial.print(" PWM=");
    Serial.println(pwm);
  }

  delay(20);  // light debounce / rate limit for the knob
}

const uint8_t R = 9, G = 10, B = 11;
const uint8_t BTN = 2;

uint8_t mode = 0;
const uint8_t MODES = 4;
unsigned long last = 0;
unsigned long lastBtn = 0;
int phase = 0;

void setRGB(uint8_t r, uint8_t g, uint8_t b) {
  analogWrite(R, r);
  analogWrite(G, g);
  analogWrite(B, b);
}

void setup() {
  pinMode(R, OUTPUT);
  pinMode(G, OUTPUT);
  pinMode(B, OUTPUT);
  pinMode(BTN, INPUT_PULLUP);
  setRGB(0, 0, 0);
}

void loop() {
  if (digitalRead(BTN) == LOW && millis() - lastBtn > 250) {
    lastBtn = millis();
    mode = (mode + 1) % MODES;
    phase = 0;
  }

  unsigned long now = millis();
  if (now - last < 20) return;
  last = now;

  switch (mode) {
    case 0:
      setRGB(0, 0, 0);
      break;
    case 1:
      setRGB(255, 0, 0);
      break;
    case 2: {
      phase = (phase + 3) % 768;
      uint8_t r, g, b;
      if (phase < 256) {
        r = 255 - phase; g = phase; b = 0;
      } else if (phase < 512) {
        r = 0; g = 511 - phase; b = phase - 256;
      } else {
        r = phase - 512; g = 0; b = 767 - phase;
      }
      setRGB(r, g, b);
      break;
    }
    case 3: {
      phase = (phase + 1) % 512;
      uint8_t v = phase < 256 ? phase : 511 - phase;
      setRGB(v, v, v);
      break;
    }
  }
}

/*
 * Aquarium Heater Controller
 * ---------------------------
 * Design notes:
 *  - A DS18B20-free approach: we use a simple NTC thermistor on A0.
 *  - The heater relay is on D7 (active HIGH through a transistor).
 *  - Hysteresis prevents relay chatter: turn ON below SETPOINT - HYST,
 *    turn OFF above SETPOINT + HYST.
 *  - A safety cutoff turns the heater off if the sensor reads absurdly
 *    high (open/short sensor protection).
 *  - Status LED on D13 mirrors the relay state.
 *  - Serial prints temperature once per second for debugging.
 */

const uint8_t  THERMISTOR_PIN = A0;
const uint8_t  HEATER_PIN     = 7;
const uint8_t  STATUS_LED_PIN = 13;

const float    SETPOINT_C     = 25.0;   // target tank temperature
const float    HYSTERESIS_C   = 0.5;    // +/- band around setpoint
const float    SAFETY_MAX_C   = 35.0;   // hard cutoff

// NTC divider: 10k series resistor to 5V, thermistor to GND.
const float    SERIES_R_OHMS  = 10000.0;
const float    NOMINAL_R_OHMS = 10000.0; // thermistor R at 25C
const float    NOMINAL_T_C    = 25.0;
const float    BETA          = 3950.0;

const unsigned long PRINT_INTERVAL_MS = 1000;
unsigned long lastPrintMs = 0;

bool heaterOn = false;

float readTemperatureC() {
  int raw = analogRead(THERMISTOR_PIN);
  if (raw <= 0) raw = 1;          // avoid divide-by-zero
  if (raw >= 1023) raw = 1022;

  // Voltage divider: thermistor is the low-side element.
  float rThermistor = SERIES_R_OHMS * (float)raw / (1023.0 - (float)raw);

  // Beta equation.
  float steinhart = rThermistor / NOMINAL_R_OHMS;
  steinhart = log(steinhart);
  steinhart /= BETA;
  steinhart += 1.0 / (NOMINAL_T_C + 273.15);
  steinhart = 1.0 / steinhart;
  steinhart -= 273.15;
  return steinhart;
}

void setHeater(bool on) {
  heaterOn = on;
  digitalWrite(HEATER_PIN, on ? HIGH : LOW);
  digitalWrite(STATUS_LED_PIN, on ? HIGH : LOW);
}

void setup() {
  pinMode(HEATER_PIN, OUTPUT);
  pinMode(STATUS_LED_PIN, OUTPUT);
  setHeater(false);
  Serial.begin(9600);
  Serial.println(F("Aquarium heater controller ready"));
}

void loop() {
  float tempC = readTemperatureC();

  if (tempC > SAFETY_MAX_C) {
    setHeater(false);
  } else if (!heaterOn && tempC < (SETPOINT_C - HYSTERESIS_C)) {
    setHeater(true);
  } else if (heaterOn && tempC > (SETPOINT_C + HYSTERESIS_C)) {
    setHeater(false);
  }

  unsigned long now = millis();
  if (now - lastPrintMs >= PRINT_INTERVAL_MS) {
    lastPrintMs = now;
    Serial.print(F("Temp: "));
    Serial.print(tempC, 2);
    Serial.print(F(" C  Heater: "));
    Serial.println(heaterOn ? F("ON") : F("OFF"));
  }

  delay(50);
}

#include <Arduino.h>

const uint8_t FAN_PIN = 9;
const uint8_t SENSE_PIN = A0;
const uint8_t LED_PIN = 13;

const int ON_C = 38;
const int OFF_C = 32;
const unsigned long MIN_ON_MS = 60000UL;
const unsigned long SAMPLE_MS = 2000UL;

bool fanOn = false;
unsigned long lastSample = 0;
unsigned long fanStart = 0;

int readTempC() {
  int raw = analogRead(SENSE_PIN);
  long mv = (long)raw * 5000L / 1024L;
  return (int)((mv - 500L) / 10L);
}

void setup() {
  pinMode(FAN_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(FAN_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
  Serial.begin(9600);
}

void loop() {
  unsigned long now = millis();
  if (now - lastSample < SAMPLE_MS) return;
  lastSample = now;

  int t = readTempC();
  Serial.print("T=");
  Serial.println(t);

  if (!fanOn && t >= ON_C) {
    fanOn = true;
    fanStart = now;
    digitalWrite(FAN_PIN, HIGH);
    digitalWrite(LED_PIN, HIGH);
  } else if (fanOn && t <= OFF_C) {
    if (now - fanStart >= MIN_ON_MS) {
      fanOn = false;
      digitalWrite(FAN_PIN, LOW);
      digitalWrite(LED_PIN, LOW);
    }
  }
}

const uint8_t TRIG = 9;
const uint8_t ECHO = 10;
const uint8_t PUMP = 6;
const uint8_t LED = 13;

const unsigned long PUMP_MS = 350;
const unsigned long COOLDOWN_MS = 1200;
const int NEAR_CM = 12;

unsigned long pumpStart = 0;
unsigned long lastPump = 0;
bool pumping = false;

long readCm() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long d = pulseIn(ECHO, HIGH, 25000UL);
  if (d == 0) return 999;
  return (long)(d / 58UL);
}

void setup() {
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(PUMP, OUTPUT);
  pinMode(LED, OUTPUT);
  digitalWrite(PUMP, LOW);
  digitalWrite(LED, LOW);
  Serial.begin(9600);
}

void loop() {
  unsigned long now = millis();
  long cm = readCm();

  if (pumping) {
    if (now - pumpStart >= PUMP_MS) {
      digitalWrite(PUMP, LOW);
      digitalWrite(LED, LOW);
      pumping = false;
      lastPump = now;
    }
  } else {
    if (cm > 0 && cm < NEAR_CM && (now - lastPump) > COOLDOWN_MS) {
      digitalWrite(PUMP, HIGH);
      digitalWrite(LED, HIGH);
      pumpStart = now;
      pumping = true;
    }
  }

  Serial.print(cm);
  Serial.print("cm ");
  Serial.println(pumping ? "PUMP" : "idle");
  delay(60);
}

const uint8_t PIN_V = A0;
const uint8_t PIN_LED = 13;
const float R1 = 10000.0;
const float R2 = 4700.0;
const float VREF = 5.0;
const float LOW = 11.0;
const float CRIT = 10.5;

float vbat = 0.0;
unsigned long last = 0;
bool blink = false;

void setup() {
  pinMode(PIN_LED, OUTPUT);
  Serial.begin(9600);
  analogReference(DEFAULT);
}

float readV() {
  uint32_t acc = 0;
  for (uint8_t i = 0; i < 16; i++) {
    acc += analogRead(PIN_V);
    delay(2);
  }
  float raw = acc / 16.0;
  float v = raw * VREF / 1023.0;
  return v * (R1 + R2) / R2;
}

void loop() {
  if (millis() - last >= 500) {
    last = millis();
    vbat = readV();
    Serial.print("Vbat=");
    Serial.print(vbat, 2);
    if (vbat < CRIT) {
      Serial.println(" CRIT");
    } else if (vbat < LOW) {
      Serial.println(" LOW");
    } else {
      Serial.println(" OK");
    }
  }

  if (vbat < CRIT) {
    blink = !blink;
    digitalWrite(PIN_LED, blink);
    delay(100);
  } else if (vbat < LOW) {
    digitalWrite(PIN_LED, (millis() / 250) % 2);
  } else {
    digitalWrite(PIN_LED, LOW);
  }
}

/*
 * Bee Hive Temperature Logger
 * ---------------------------
 * Design notes:
 *  - A single DS18B20-style analog temperature sensor is read on A0.
 *  - The sensor is a TMP36: 10 mV per degree C, 500 mV offset at 0 C.
 *  - We sample once per SAMPLE_PERIOD_MS and print a CSV line over Serial.
 *  - A status LED blinks briefly on each successful sample so a field tech
 *    can see the logger is alive without opening the hive.
 *  - All magic numbers are named constants below. Keep it boring and readable.
 */

#include <Arduino.h>

// ---- Pin assignments -------------------------------------------------------
const uint8_t TEMP_SENSOR_PIN = A0;
const uint8_t STATUS_LED_PIN  = 13;

// ---- Timing ----------------------------------------------------------------
const unsigned long SAMPLE_PERIOD_MS = 60000UL;  // one reading per minute
const unsigned long LED_BLINK_MS     = 50UL;

// ---- TMP36 transfer function ----------------------------------------------
const float ADC_REFERENCE_VOLTS = 5.0;
const float ADC_MAX_COUNTS       = 1023.0;
const float TMP36_OFFSET_VOLTS   = 0.5;
const float TMP36_VOLTS_PER_C    = 0.010;

// ---- State -----------------------------------------------------------------
unsigned long lastSampleMs = 0;

float readTemperatureC() {
  int raw = analogRead(TEMP_SENSOR_PIN);
  float volts = (raw / ADC_MAX_COUNTS) * ADC_REFERENCE_VOLTS;
  float celsius = (volts - TMP36_OFFSET_VOLTS) / TMP36_VOLTS_PER_C;
  return celsius;
}

void blinkStatus() {
  digitalWrite(STATUS_LED_PIN, HIGH);
  delay(LED_BLINK_MS);
  digitalWrite(STATUS_LED_PIN, LOW);
}

void setup() {
  pinMode(STATUS_LED_PIN, OUTPUT);
  digitalWrite(STATUS_LED_PIN, LOW);
  Serial.begin(9600);
  Serial.println(F("ms,temp_c"));
  lastSampleMs = millis();
}

void loop() {
  unsigned long now = millis();
  if (now - lastSampleMs >= SAMPLE_PERIOD_MS) {
    lastSampleMs = now;
    float t = readTemperatureC();
    Serial.print(now);
    Serial.print(',');
    Serial.println(t, 2);
    blinkStatus();
  }
}

/*
 * Bench Power Supply Monitor
 * --------------------------
 * Reads the supply's output voltage and current sense amplifier on two
 * analog inputs and reports both over the serial port once per second.
 *
 * Design notes:
 *  - Voltage divider on A0: 10k / 2.2k, so Vout = Vadc * (12.2 / 2.2).
 *  - Current sense on A1: 0.1 ohm shunt into a x50 amp, so 1 A -> 5 V.
 *  - ADC reference is the default 5 V rail; we assume it is well regulated.
 *  - A simple moving average (8 samples) smooths the noisy readings.
 *  - Overcurrent LED on D13 lights above 1.5 A (bench limit).
 */

const uint8_t  VOLT_PIN      = A0;
const uint8_t  CURR_PIN      = A1;
const uint8_t  OCP_LED_PIN   = 13;

const float    ADC_MAX       = 1023.0;
const float    VREF          = 5.0;

// Voltage divider: Rtop = 10k, Rbot = 2.2k
const float    DIV_RTOP      = 10000.0;
const float    DIV_RBOT      = 2200.0;
const float    DIV_RATIO     = (DIV_RTOP + DIV_RBOT) / DIV_RBOT;

// Current sense: 0.1 ohm shunt, gain 50 -> 5 V per amp
const float    SHUNT_OHMS    = 0.1;
const float    AMP_GAIN      = 50.0;
const float    VOLTS_PER_AMP = SHUNT_OHMS * AMP_GAIN;

const float    OCP_LIMIT_A   = 1.5;
const uint16_t REPORT_MS     = 1000;
const uint8_t  AVG_SAMPLES   = 8;

unsigned long lastReport = 0;

float readAveraged(uint8_t pin) {
  uint32_t sum = 0;
  for (uint8_t i = 0; i < AVG_SAMPLES; i++) {
    sum += analogRead(pin);
    delay(2);
  }
  return (float)sum / AVG_SAMPLES;
}

void setup() {
  pinMode(OCP_LED_PIN, OUTPUT);
  digitalWrite(OCP_LED_PIN, LOW);
  Serial.begin(9600);
  Serial.println(F("Bench Power Supply Monitor"));
}

void loop() {
  unsigned long now = millis();
  if (now - lastReport < REPORT_MS) {
    return;
  }
  lastReport = now;

  float vAdc = readAveraged(VOLT_PIN);
  float cAdc = readAveraged(CURR_PIN);

  float vPin  = vAdc * (VREF / ADC_MAX);
  float cPin  = cAdc * (VREF / ADC_MAX);

  float volts = vPin * DIV_RATIO;
  float amps  = cPin / VOLTS_PER_AMP;

  bool overCurrent = amps > OCP_LIMIT_A;
  digitalWrite(OCP_LED_PIN, overCurrent ? HIGH : LOW);

  Serial.print(F("V="));
  Serial.print(volts, 2);
  Serial.print(F(" V  I="));
  Serial.print(amps, 3);
  Serial.print(F(" A"));
  if (overCurrent) {
    Serial.print(F("  [OCP]"));
  }
  Serial.println();
}

