  Serial.begin(9600);
}

void loop() {
  // read buttons. LOW means pressed because of the pull-up.
  bool leftPressed = (digitalRead(LEFT_BTN) == LOW);
  bool rightPressed = (digitalRead(RIGHT_BTN) == LOW);

  // left button: turn left blinker on, or off if already on
  if (leftPressed) {
    if (mode == 1) {
      mode = 0;   // same button again = cancel
    } else {
      mode = 1;   // switch to left
    }
    delay(250);   // crude debounce, ignore for now
  }

  // right button: same idea
  if (rightPressed) {
    if (mode == 2) {
      mode = 0;
    } else {
      mode = 2;
    }
    delay(250);
  }

  // if nothing is selected, make sure both LEDs are off
  if (mode == 0) {
    digitalWrite(LEFT_LED, LOW);
    digitalWrite(RIGHT_LED, LOW);
    ledOn = false;
    return;   // nothing else to do this pass
  }

  // blink the selected side every BLINK_MS
  unsigned long now = millis();
  if (now - lastBlink >= BLINK_MS) {
    lastBlink = now;
    ledOn = !ledOn;   // flip on/off

    if (mode == 1) {
      digitalWrite(LEFT_LED, ledOn ? HIGH : LOW);
      digitalWrite(RIGHT_LED, LOW);
    } else if (mode == 2) {
      digitalWrite(RIGHT_LED, ledOn ? HIGH : LOW);
      digitalWrite(LEFT_LED, LOW);
    }
  }

  // debug print - ignore this, it's only for the serial monitor
  // Serial.println(mode);
}

// bottle counter
// counts bottles on a conveyor with a beam break sensor

const int sensorPin = 2;      // IR beam sensor, goes LOW when blocked
const int ledPin = 13;        // onboard LED blinks per bottle
const int resetPin = 4;       // button to reset count, wired to GND

int count = 0;
int lastState = HIGH;
unsigned long lastDebounce = 0;
const unsigned long debounceMs = 30;

void setup() {
  pinMode(sensorPin, INPUT_PULLUP);
  pinMode(resetPin, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);
  Serial.begin(9600);
  Serial.println("Bottle counter ready");
}

void loop() {
  int state = digitalRead(sensorPin);

  // beam just got blocked -> one more bottle
  if (state == LOW && lastState == HIGH) {
    if (millis() - lastDebounce > debounceMs) {
      count++;
      lastDebounce = millis();
      digitalWrite(ledPin, HIGH);
      Serial.print("Bottles: ");
      Serial.println(count);
    }
  }

  // beam clear again, turn LED off
  if (state == HIGH) {
    digitalWrite(ledPin, LOW);
  }

  lastState = state;

  // reset button
  if (digitalRead(resetPin) == LOW) {
    delay(20); // cheap debounce
    if (digitalRead(resetPin) == LOW) {
      count = 0;
      Serial.println("Count reset");
      while (digitalRead(resetPin) == LOW) {
        // wait for release
      }
    }
  }
}

/*
 * Capacitor Charge Timer
 * -----------------------
 * Measures the time for a capacitor to charge through a known resistor
 * from 0 V up to the digital input threshold, using a single digital pin.
 *
 * Design:
 *   - The capacitor is discharged by driving the pin LOW as an output.
 *   - The pin is then switched to INPUT (high impedance) and the capacitor
 *     charges through R toward 5 V.
 *   - We poll the pin until it reads HIGH, then report the elapsed time.
 *   - With R = 100k and C = 1uF, tau = 0.1 s; the ~2.5 V threshold is
 *     reached at about 0.69 * tau, i.e. roughly 70 ms.
 *
 * Only the Arduino core is used. Results go out over Serial at 9600 baud.
 */

const uint8_t  SENSE_PIN        = 2;      // junction of R and C
const uint8_t  DISCHARGE_MS     = 50;     // long enough for 5*tau
const uint16_t SETTLE_MS        = 5;      // let the pin settle after mode change
const uint16_t TIMEOUT_MS       = 2000;   // give up if it never charges
const uint16_t SAMPLE_PERIOD_MS = 1000;   // one measurement per second

unsigned long lastSample = 0;

void dischargeCapacitor() {
  pinMode(SENSE_PIN, OUTPUT);
  digitalWrite(SENSE_PIN, LOW);
  delay(DISCHARGE_MS);
}

unsigned long measureChargeTime() {
  // Release the pin and start timing.
  pinMode(SENSE_PIN, INPUT);
  delay(SETTLE_MS);

  unsigned long start = millis();
  while (digitalRead(SENSE_PIN) == LOW) {
    if (millis() - start > TIMEOUT_MS) {
      return 0;  // 0 signals a timeout
    }
  }
  return millis() - start;
}

void setup() {
  Serial.begin(9600);
  Serial.println(F("Capacitor charge timer ready"));
  dischargeCapacitor();
}

void loop() {
  if (millis() - lastSample < SAMPLE_PERIOD_MS) {
    return;
  }
  lastSample = millis();

  dischargeCapacitor();
  unsigned long chargeTime = measureChargeTime();

  if (chargeTime == 0) {
    Serial.println(F("TIMEOUT: capacitor did not charge"));
  } else {
    Serial.print(F("Charge time: "));
    Serial.print(chargeTime);
    Serial.println(F(" ms"));
  }
}

// Cat Flap Counter
// Written by a beginner. This counts how many times the cat goes through the flap.
// I'm using a magnetic reed switch on the flap and a little button to reset the count.
// The count shows on the Serial Monitor. I know a display would be nicer but this is v1.

// ---- Pin setup ----
// The reed switch is on pin 2. I picked 2 because it can do interrupts.
// The switch connects the pin to GND when the magnet is near, so we use INPUT_PULLUP.
const int REED_PIN = 2;

// Reset button on pin 4, also to GND, also INPUT_PULLUP.
const int RESET_PIN = 4;

// ---- Variables ----
// This holds how many passes we've seen.
volatile unsigned int passCount = 0;

// The reed switch is bouncy (it's mechanical), so I ignore extra edges
// that happen within 300 ms of the last one. A cat can't go through
// twice that fast anyway, so this is safe.
volatile unsigned long lastEdgeMs = 0;
const unsigned long DEBOUNCE_MS = 300;

// For the reset button I do a simple debounce in loop().
int lastResetReading = HIGH;
unsigned long lastResetChangeMs = 0;
const unsigned long RESET_DEBOUNCE_MS = 50;

void setup() {
  // Serial at 9600 so the Serial Monitor can read it.
  Serial.begin(9600);

  // Both switches pull to ground, so enable the internal pull-ups.
  pinMode(REED_PIN, INPUT_PULLUP);
  pinMode(RESET_PIN, INPUT_PULLUP);

  // Count on the falling edge: that's when the magnet leaves the switch
  // as the flap swings. I ignore the rising edge on purpose, otherwise
  // one pass would count twice (once going in, once coming back).
  attachInterrupt(digitalPinToInterrupt(REED_PIN), onReedEdge, FALLING);

  Serial.println("Cat flap counter ready");
  Serial.println("Passes: 0");
}

// This runs every time the reed switch closes.
void onReedEdge() {
  unsigned long now = millis();

  // Ignore edges that come too soon after the last one (switch bounce).
  if (now - lastEdgeMs < DEBOUNCE_MS) {
    return;
  }
  lastEdgeMs = now;

  passCount++;
}

void loop() {
  // Read the reset button. LOW means pressed because of the pull-up.
  int reading = digitalRead(RESET_PIN);

  // If the reading changed, remember when. This is the debounce timer.
  if (reading != lastResetReading) {
    lastResetChangeMs = millis();
  }

  // Only act if the reading has been stable for 50 ms.
  if ((millis() - lastResetChangeMs) > RESET_DEBOUNCE_MS) {
    if (reading == LOW) {
      // Button is held down and stable: reset the count.
      // I turn interrupts off for a moment so the count can't change
      // while I'm writing zero to it.
      noInterrupts();
      passCount = 0;
      interrupts();

      Serial.println("Count reset");
      Serial.println("Passes: 0");

      // Wait for the button to be released so we don't reset over and over.
      while (digitalRead(RESET_PIN) == LOW) {
        delay(10);
      }
    }
  }

  lastResetReading = reading;

  // Print the count whenever it changes. I keep a copy of the last
  // printed value so we don't spam the Serial Monitor every loop.
  static unsigned int lastPrinted = 0;
  unsigned int current;
  noInterrupts();
  current = passCount;
  interrupts();

  if (current != lastPrinted) {
    Serial.print("Passes: ");
    Serial.println(current);
    lastPrinted = current;
  }

  // Small delay so the loop isn't spinning at full speed.
  delay(5);
}

/*
 * Chicken Coop Door Controller
 * ----------------------------
 * Design notes:
 *  - A DC gear motor drives the door up/down via an H-bridge (L293D style).
 *  - Two limit switches (top = fully open, bottom = fully closed) stop motion.
 *  - A pushbutton toggles the door; each press reverses direction.
 *  - A photocell decides morning/evening, but the button always wins.
 *  - Motor runs are time-limited so a stuck door can't burn the motor.
 *  - All timings are in milliseconds; keep them as named constants.
 */

const uint8_t PIN_MOTOR_A   = 5;   // H-bridge input 1
const uint8_t PIN_MOTOR_B   = 6;   // H-bridge input 2
const uint8_t PIN_LIMIT_TOP = 2;   // switch to GND, INPUT_PULLUP
const uint8_t PIN_LIMIT_BOT = 3;   // switch to GND, INPUT_PULLUP
const uint8_t PIN_BUTTON    = 4;   // button to GND, INPUT_PULLUP
const uint8_t PIN_LIGHT     = A0;  // photocell divider

const int  LIGHT_DARK_THRESHOLD = 300;  // below this = night
const unsigned long DEBOUNCE_MS      = 30;
const unsigned long MAX_TRAVEL_MS    = 12000; // full door travel budget
const unsigned long SETTLE_MS        = 250;   // pause before reversing

enum DoorState { DOOR_STOPPED, DOOR_OPENING, DOOR_CLOSING };

DoorState state = DOOR_STOPPED;
bool doorIsOpen = false;          // best guess of where the door is
unsigned long moveStart = 0;
unsigned long lastButtonChange = 0;
bool lastButtonReading = HIGH;
bool buttonStable = HIGH;

void motorStop() {
  digitalWrite(PIN_MOTOR_A, LOW);
  digitalWrite(PIN_MOTOR_B, LOW);
}

void motorOpen() {
  digitalWrite(PIN_MOTOR_A, HIGH);
  digitalWrite(PIN_MOTOR_B, LOW);
}

void motorClose() {
  digitalWrite(PIN_MOTOR_A, LOW);
  digitalWrite(PIN_MOTOR_B, HIGH);
}

bool topHit() { return digitalRead(PIN_LIMIT_TOP) == LOW; }
bool botHit() { return digitalRead(PIN_LIMIT_BOT) == LOW; }

void startOpening() {
  if (topHit()) { doorIsOpen = true; return; }
  motorOpen();
  state = DOOR_OPENING;
  moveStart = millis();
}

void startClosing() {
  if (botHit()) { doorIsOpen = false; return; }
  motorClose();
  state = DOOR_CLOSING;
  moveStart = millis();
}

void readButton() {
  bool reading = digitalRead(PIN_BUTTON);
  if (reading != lastButtonReading) {
    lastButtonChange = millis();
    lastButtonReading = reading;
  }
  if ((millis() - lastButtonChange) > DEBOUNCE_MS && reading != buttonStable) {
    buttonStable = reading;
    if (buttonStable == LOW && state == DOOR_STOPPED) {
      // Button toggles: if open, close; otherwise open.
      if (doorIsOpen) startClosing(); else startOpening();
    }
  }
}

void setup() {
  pinMode(PIN_MOTOR_A, OUTPUT);
  pinMode(PIN_MOTOR_B, OUTPUT);
  pinMode(PIN_LIMIT_TOP, INPUT_PULLUP);
  pinMode(PIN_LIMIT_BOT, INPUT_PULLUP);
  pinMode(PIN_BUTTON, INPUT_PULLUP);
  motorStop();
}

void loop() {
  readButton();

  if (state == DOOR_OPENING) {
    if (topHit() || (millis() - moveStart) > MAX_TRAVEL_MS) {
      motorStop();
      state = DOOR_STOPPED;
      doorIsOpen = true;
      delay(SETTLE_MS);
    }
  } else if (state == DOOR_CLOSING) {
    if (botHit() || (millis() - moveStart) > MAX_TRAVEL_MS) {
      motorStop();
      state = DOOR_STOPPED;
      doorIsOpen = false;
      delay(SETTLE_MS);
    }
  } else {
    // Idle: let light level drive the door when nobody is pressing buttons.
    int light = analogRead(PIN_LIGHT);
    if (light < LIGHT_DARK_THRESHOLD && doorIsOpen) {
      startClosing();
    } else if (light >= LIGHT_DARK_THRESHOLD && !doorIsOpen) {
      startOpening();
    }
  }
}

// Clap Switch - turns an LED on/off when it hears a clap
// Written by a beginner, so lots of comments. Read them, they help!

// ---- Pin setup ----
// The sound sensor's digital output goes to pin 2.
// (Ignore the sensor's analog pin for this project - we only
// need a simple HIGH/LOW "was that loud?" signal.)
const int SOUND_PIN = 2;

// The LED is on pin 13. That's also the onboard LED on the Uno,
// so you can test without wiring anything extra.
const int LED_PIN = 13;

// ---- State variables ----
// This remembers whether the light is currently on or off.
bool ledOn = false;

// This remembers the last time we reacted to a clap, so one clap
// doesn't get counted many times in a row.
unsigned long lastClapTime = 0;

// How long to wait after a clap before listening again (milliseconds).
// 300 ms feels about right - long enough to skip the echo of one clap,
// short enough that a quick double-clap still works.
const unsigned long DEBOUNCE_MS = 300;

void setup() {
  // The sensor output is a plain digital signal, so we read it.
  pinMode(SOUND_PIN, INPUT);

  // The LED is an output because we drive it.
  pinMode(LED_PIN, OUTPUT);

  // Start with the LED off.
  digitalWrite(LED_PIN, LOW);

  // Open the serial port so we can watch what's happening.
  // (Ignore this if you're not watching the Serial Monitor.)
  Serial.begin(9600);
  Serial.println("Clap switch ready!");
}

void loop() {
  // Read the sensor. Most sound modules go HIGH when it's loud.
  int soundState = digitalRead(SOUND_PIN);

  // Only act if we hear a clap AND enough time has passed
  // since the last one we counted.
  if (soundState == HIGH && (millis() - lastClapTime) > DEBOUNCE_MS) {
    // Flip the state: off becomes on, on becomes off.
    ledOn = !ledOn;

    // Actually drive the LED to match our state variable.
    digitalWrite(LED_PIN, ledOn ? HIGH : LOW);

    // Remember when this happened so we can debounce.
    lastClapTime = millis();

    // Tell the human what we did.
    Serial.print("Clap! LED is now ");
    Serial.println(ledOn ? "ON" : "OFF");
  }

  // Nothing else to do. The loop just keeps checking.
  // (Ignore any temptation to add delay() here - it would make
  // us miss quick claps.)
}

/*
 * Conveyor Jam Detector
 * ---------------------
 * Design notes:
 *  - A slotted opto sensor on the conveyor drive shaft pulses once per
 *    revolution. If the belt is moving, pulses arrive regularly.
 *  - A jam is declared when no pulse has been seen for JAM_TIMEOUT_MS.
 *  - The motor is cut via a relay on MOTOR_PIN (active HIGH).
 *  - A red LED latches on during a jam; the operator clears it with the
 *    reset button, but only if the shaft is turning again.
 *  - Sensor input uses INPUT_PULLUP; the slot sensor pulls the pin LOW.
 */

const uint8_t SENSOR_PIN     = 2;   // shaft pulse, active LOW
const uint8_t MOTOR_PIN      = 7;   // relay, HIGH = run
const uint8_t JAM_LED_PIN    = 8;   // red LED
const uint8_t RESET_BTN_PIN  = 9;   // to GND, INPUT_PULLUP

const unsigned long JAM_TIMEOUT_MS = 1500;  // ~2 missed pulses at 80 RPM
const unsigned long DEBOUNCE_MS    = 20;

bool jammed = false;
unsigned long lastPulseMs = 0;
unsigned long lastEdgeMs  = 0;
int lastSensorState = HIGH;

void setup() {
  pinMode(SENSOR_PIN, INPUT_PULLUP);
  pinMode(RESET_BTN_PIN, INPUT_PULLUP);
  pinMode(MOTOR_PIN, OUTPUT);
  pinMode(JAM_LED_PIN, OUTPUT);

  digitalWrite(MOTOR_PIN, HIGH);
  digitalWrite(JAM_LED_PIN, LOW);
  lastPulseMs = millis();
}

void loop() {
  unsigned long now = millis();

  // --- Shaft pulse detection with simple debounce ---
  int state = digitalRead(SENSOR_PIN);
  if (state != lastSensorState && (now - lastEdgeMs) > DEBOUNCE_MS) {
    lastEdgeMs = now;
    lastSensorState = state;
    if (state == LOW) {
      lastPulseMs = now;   // a real pulse: belt is moving
    }
  }

  // --- Jam detection ---
  if (!jammed && (now - lastPulseMs) > JAM_TIMEOUT_MS) {
    jammed = true;
    digitalWrite(MOTOR_PIN, LOW);
    digitalWrite(JAM_LED_PIN, HIGH);
  }

  // --- Operator reset: only if shaft has pulsed recently ---
  if (jammed && digitalRead(RESET_BTN_PIN) == LOW) {
    if ((now - lastPulseMs) < JAM_TIMEOUT_MS) {
      jammed = false;
      digitalWrite(MOTOR_PIN, HIGH);
      digitalWrite(JAM_LED_PIN, LOW);
    }
  }
}

// Dog Water Bowl Refiller
// Written by a beginner, so lots of comments. Read them!
// Goal: keep the dog's bowl full by turning on a little pump when the water gets low.

// ---- Pin setup ----
// We use pin 7 for the float switch. A float switch is just a switch that
// closes when the water level drops. We wire it so the pin reads LOW when dry.
const int FLOAT_PIN = 7;

// The pump is switched by a relay module on pin 9.
// IMPORTANT: most relay boards are ACTIVE LOW, meaning LOW = pump ON.
// If your relay is active high, swap the HIGH/LOW below. Ignore this if unsure.
const int PUMP_PIN = 9;

// ---- Timing ----
// How long to run the pump once we notice the bowl is low.
// 4000 ms is a guess for a small pump. Tune it so the bowl doesn't overflow.
const unsigned long PUMP_RUN_MS = 4000;

// After pumping, wait this long before checking again. This lets the water
// settle so the float switch isn't fooled by sloshing. Ignore the exact value.
const unsigned long SETTLE_MS = 5000;

// ---- State ----
// We remember when the pump started so we can stop it without delay().
unsigned long pumpStartedAt = 0;
bool pumping = false;

void setup() {
  // Serial is only for watching what happens in the Serial Monitor.
  // It does not affect the dog. You can ignore it.
  Serial.begin(9600);
  Serial.println("Dog bowl refiller starting up");

  // Float switch uses the built-in pull-up resistor, so no external resistor
  // is needed. When the switch closes to ground, the pin reads LOW.
  pinMode(FLOAT_PIN, INPUT_PULLUP);

  // Start with the pump OFF. Remember: active-low relay, so HIGH = off.
  pinMode(PUMP_PIN, OUTPUT);
  digitalWrite(PUMP_PIN, HIGH);
}

void loop() {
  // Read the float switch. LOW means the water is low (switch closed).
  bool waterIsLow = (digitalRead(FLOAT_PIN) == LOW);

  if (!pumping) {
    // Not pumping right now. Should we start?
    if (waterIsLow) {
      Serial.println("Water low - starting pump");
      digitalWrite(PUMP_PIN, LOW);   // LOW turns the relay/pump ON
      pumpStartedAt = millis();
      pumping = true;
    }
  } else {
    // We are pumping. Stop after PUMP_RUN_MS milliseconds.
    // Using millis() instead of delay() keeps the sketch responsive.
    if (millis() - pumpStartedAt >= PUMP_RUN_MS) {
      Serial.println("Pump done - stopping");
      digitalWrite(PUMP_PIN, HIGH);  // HIGH turns the relay/pump OFF
      pumping = false;

      // Small settle pause. This is the one place delay() is okay because
      // nothing else needs to happen during it.
      delay(SETTLE_MS);
    }
  }

  // Tiny delay so the loop doesn't spin at full speed. Not critical.
  delay(50);
}

// Doorbell chime
// Press button -> play a little ding-dong on a piezo

const int BUTTON_PIN = 2;
const int BUZZER_PIN = 8;

int lastButtonState = HIGH;
unsigned long lastDebounceTime = 0;
const unsigned long debounceDelay = 50;

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(BUZZER_PIN, OUTPUT);
  Serial.begin(9600);
  Serial.println("Doorbell ready");
}

void loop() {
  int reading = digitalRead(BUTTON_PIN);

  // debounce
  if (reading != lastButtonState) {
    lastDebounceTime = millis();
  }

  if ((millis() - lastDebounceTime) > debounceDelay) {
    if (reading == LOW) {
      // button is pressed (pullup, so LOW)
      playDingDong();
      // wait for release so we don't retrigger
      while (digitalRead(BUTTON_PIN) == LOW) {
        delay(10);
      }
    }
  }

  lastButtonState = reading;
}

void playDingDong() {
  Serial.println("Ding");
  tone(BUZZER_PIN, 659, 400);  // E5
  delay(450);
  Serial.println("Dong");
  tone(BUZZER_PIN, 523, 600);  // C5
  delay(650);
  noTone(BUZZER_PIN);
}

#include <LiquidCrystal.h>

LiquidCrystal lcd(12, 11, 5, 4, 3, 2);
const uint8_t BTN = 7;
const uint8_t BUZ = 9;
const uint8_t LED = 13;

const uint16_t PRESETS[] = {180, 300, 420, 600};
const uint8_t NPRESET = 4;

uint8_t presetIdx = 0;
uint16_t remaining = 0;
bool running = false;
bool done = false;
uint32_t lastTick = 0;
bool lastBtn = HIGH;
uint32_t btnDownAt = 0;

void showTime(uint16_t s) {
  lcd.setCursor(0, 1);
  uint8_t m = s / 60;
  uint8_t sec = s % 60;
  if (m < 10) lcd.print(' ');
  lcd.print(m);
  lcd.print(':');
  if (sec < 10) lcd.print('0');
  lcd.print(sec);
  lcd.print("   ");
}

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  pinMode(BUZ, OUTPUT);
  pinMode(LED, OUTPUT);
  lcd.begin(16, 2);
  lcd.print("Egg Timer");
  remaining = PRESETS[presetIdx];
  showTime(remaining);
  lastTick = millis();
}

void loop() {
  bool btn = digitalRead(BTN);
  uint32_t now = millis();

  if (lastBtn == HIGH && btn == LOW) {
    btnDownAt = now;
  }
  if (lastBtn == LOW && btn == HIGH) {
    uint32_t held = now - btnDownAt;
    if (held > 800) {
      presetIdx = (presetIdx + 1) % NPRESET;
      remaining = PRESETS[presetIdx];
      running = false;
      done = false;
      lcd.setCursor(0, 0);
      lcd.print("Preset ");
      lcd.print(presetIdx + 1);
      lcd.print("   ");
      showTime(remaining);
    } else {
      if (done) {
        done = false;
        remaining = PRESETS[presetIdx];
        showTime(remaining);
      } else if (running) {
        running = false;
      } else {
        running = true;
        lastTick = now;
      }
    }
  }
  lastBtn = btn;

  if (running && now - lastTick >= 1000) {
    lastTick += 1000;
    if (remaining > 0) {
      remaining--;
      showTime(remaining);
    }
    if (remaining == 0) {
      running = false;
      done = true;
    }
  }

  if (done) {
    digitalWrite(LED, (now / 250) % 2);
    if ((now / 500) % 2) tone(BUZ, 2000);
    else noTone(BUZ);
  } else {
    digitalWrite(LED, running ? HIGH : LOW);
    noTone(BUZ);
  }
}

/*
 * Electronic Dice
 * -----------------
 * Press the button, the die "rolls" for a short time, then the result
 * (1..6) is shown on six LEDs arranged like the pips of a real die.
 *
 * Design notes:
 *  - The roll animation just flashes random faces for ROLL_DURATION_MS.
 *  - A simple debounce (DEBOUNCE_MS) keeps one press from re-triggering.
 *  - randomSeed() is fed from a floating analog pin so each power-up differs.
 *  - Pip LEDs are wired active-HIGH through 220 ohm resistors.
 */

const uint8_t BUTTON_PIN = 2;
const uint8_t SEED_PIN   = A0;

// Pip LEDs: index 0..5 -> top-left, top-right, mid-left, mid-right, bot-left, bot-right
const uint8_t PIP_PINS[6] = {3, 4, 5, 6, 7, 8};

const unsigned long DEBOUNCE_MS      = 30;
const unsigned long ROLL_DURATION_MS = 900;
const unsigned long ROLL_STEP_MS     = 70;

// Bitmask of which pips are lit for each face 1..6.
// Bit order matches PIP_PINS: bit0=TL, bit1=TR, bit2=ML, bit3=MR, bit4=BL, bit5=BR
const uint8_t FACE_MASKS[7] = {
  0b000000, // unused (face 0)
  0b000100, // 1: center-ish (mid-right used as center pip)
  0b100001, // 2: TL + BR
  0b100101, // 3: TL + center + BR
  0b110011, // 4: four corners
  0b110111, // 5: four corners + center
  0b111111  // 6: all six
};

bool          lastButtonState = HIGH;
unsigned long lastDebounceTime = 0;

void showFace(uint8_t face) {
  uint8_t mask = FACE_MASKS[face];
  for (uint8_t i = 0; i < 6; i++) {
    digitalWrite(PIP_PINS[i], (mask >> i) & 0x01);
  }
}

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  for (uint8_t i = 0; i < 6; i++) {
    pinMode(PIP_PINS[i], OUTPUT);
    digitalWrite(PIP_PINS[i], LOW);
  }
  randomSeed(analogRead(SEED_PIN));
  showFace(1);
}

void loop() {
  bool reading = digitalRead(BUTTON_PIN);

  if (reading != lastButtonState) {
    lastDebounceTime = millis();
  }

  if ((millis() - lastDebounceTime) > DEBOUNCE_MS) {
    if (reading == LOW) {           // pressed (pull-up)
      rollDice();
      // wait for release so we don't immediately re-roll
      while (digitalRead(BUTTON_PIN) == LOW) { delay(5); }
    }
  }
  lastButtonState = reading;
}

void rollDice() {
  unsigned long start = millis();
  while (millis() - start < ROLL_DURATION_MS) {
    showFace(random(1, 7));
    delay(ROLL_STEP_MS);
  }
  showFace(random(1, 7));
}

/*
 * Elevator Model Controller
 * --------------------------
 * A 3-floor elevator model driven by a single DC gearmotor with two
 * limit switches (bottom and top) and one floor sensor per level.
 *
 * Design notes:
 *  - The cabin moves between FLOOR_1 (bottom) and FLOOR_3 (top).
 *  - A request is queued by pressing a call button; the cabin travels
 *    toward the requested floor and stops when that floor sensor trips.
 *  - Limit switches are safety backstops: if one opens while moving in
 *    that direction, the motor is cut immediately.
 *  - Direction is set by two motor pins (IN1/IN2); a single PWM pin
 *    controls speed. We run at a fixed, gentle speed.
 *
 * Written by a tidy engineer. Keep it simple; the model is small.
 */

// ---- Pin assignments ----
const uint8_t PIN_MOTOR_IN1   = 4;   // direction A
const uint8_t PIN_MOTOR_IN2   = 5;   // direction B
const uint8_t PIN_MOTOR_PWM   = 6;   // speed (enable)

const uint8_t PIN_FLOOR_1     = 7;   // bottom floor sensor
const uint8_t PIN_FLOOR_2     = 8;   // middle floor sensor
const uint8_t PIN_FLOOR_3     = 9;   // top floor sensor

const uint8_t PIN_LIMIT_BOT   = 10;  // bottom limit switch (LOW = pressed)
const uint8_t PIN_LIMIT_TOP   = 11;  // top limit switch (LOW = pressed)

const uint8_t PIN_CALL_1      = 2;   // call button for floor 1
const uint8_t PIN_CALL_2      = 3;   // call button for floor 2
const uint8_t PIN_CALL_3      = 12;  // call button for floor 3

// ---- Tuning constants ----
const uint8_t  MOTOR_SPEED    = 180; // PWM duty, 0..255
const uint16_t DEBOUNCE_MS    = 30;  // button debounce window

// ---- State ----
int8_t  currentFloor = 1;            // 1..3, best guess
int8_t  targetFloor  = 1;            // where we want to be
bool    moving       = false;

void setup() {
  pinMode(PIN_MOTOR_IN1, OUTPUT);
  pinMode(PIN_MOTOR_IN2, OUTPUT);
  pinMode(PIN_MOTOR_PWM, OUTPUT);

  pinMode(PIN_FLOOR_1, INPUT_PULLUP);
  pinMode(PIN_FLOOR_2, INPUT_PULLUP);
  pinMode(PIN_FLOOR_3, INPUT_PULLUP);
  pinMode(PIN_LIMIT_BOT, INPUT_PULLUP);
  pinMode(PIN_LIMIT_TOP, INPUT_PULLUP);

  pinMode(PIN_CALL_1, INPUT_PULLUP);
  pinMode(PIN_CALL_2, INPUT_PULLUP);
  pinMode(PIN_CALL_3, INPUT_PULLUP);

  stopMotor();
}

void loop() {
  readCalls();
  readFloorSensors();

  if (moving) {
    runMotor();
  } else if (targetFloor != currentFloor) {
    moving = true;
  } else {
    stopMotor();
  }
}

// Latch the most recent call as the target.
void readCalls() {
  if (buttonPressed(PIN_CALL_1)) targetFloor = 1;
  if (buttonPressed(PIN_CALL_2)) targetFloor = 2;
  if (buttonPressed(PIN_CALL_3)) targetFloor = 3;
}

// Update currentFloor from whichever sensor is active.
void readFloorSensors() {
  if (digitalRead(PIN_FLOOR_1) == LOW) currentFloor = 1;
  if (digitalRead(PIN_FLOOR_2) == LOW) currentFloor = 2;
  if (digitalRead(PIN_FLOOR_3) == LOW) currentFloor = 3;
}

// Drive toward target, honoring limits and arrival.
void runMotor() {
  if (targetFloor > currentFloor) {
    if (digitalRead(PIN_LIMIT_TOP) == LOW) { stopMotor(); moving = false; return; }
    driveUp();
  } else if (targetFloor < currentFloor) {
    if (digitalRead(PIN_LIMIT_BOT) == LOW) { stopMotor(); moving = false; return; }
    driveDown();
  } else {
    stopMotor();
    moving = false;
  }
}

void driveUp() {
  digitalWrite(PIN_MOTOR_IN1, HIGH);
  digitalWrite(PIN_MOTOR_IN2, LOW);
  analogWrite(PIN_MOTOR_PWM, MOTOR_SPEED);
}

void driveDown() {
  digitalWrite(PIN_MOTOR_IN1, LOW);
  digitalWrite(PIN_MOTOR_IN2, HIGH);
  analogWrite(PIN_MOTOR_PWM, MOTOR_SPEED);
}

void stopMotor() {
  digitalWrite(PIN_MOTOR_IN1, LOW);
  digitalWrite(PIN_MOTOR_IN2, LOW);
  analogWrite(PIN_MOTOR_PWM, 0);
}

// Simple debounce: require a stable LOW reading.
bool buttonPressed(uint8_t pin) {
  if (digitalRead(pin) != LOW) return false;
  delay(DEBOUNCE_MS);
  return digitalRead(pin) == LOW;
}

#include <EEPROM.h>

const uint8_t BTN = 2;
const uint8_t LED = 13;
const uint8_t FEED = 9;
const uint8_t POT = A0;

unsigned long lastFeed = 0;
unsigned long interval = 0;
unsigned long feedStart = 0;
bool feeding = false;
bool lastBtn = HIGH;
unsigned long btnDown = 0;

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
  pinMode(FEED, OUTPUT);
  digitalWrite(FEED, LOW);
  Serial.begin(9600);
  uint8_t hi = EEPROM.read(0);
  uint8_t lo = EEPROM.read(1);
  uint16_t mins = (hi << 8) | lo;
  if (mins < 1 || mins > 1440) mins = 480;
  interval = (unsigned long)mins * 60000UL;
  Serial.print("interval min ");
  Serial.println(mins);
}

void loop() {
  bool b = digitalRead(BTN);
  if (b == LOW && lastBtn == HIGH) {
    btnDown = millis();
  }
  if (b == HIGH && lastBtn == LOW) {
    unsigned long held = millis() - btnDown;
    if (held > 1500) {
      uint16_t mins = map(analogRead(POT), 0, 1023, 1, 1440);
      EEPROM.write(0, mins >> 8);
      EEPROM.write(1, mins & 0xFF);
      interval = (unsigned long)mins * 60000UL;
      Serial.print("set min ");
      Serial.println(mins);
      digitalWrite(LED, HIGH);
      delay(300);
      digitalWrite(LED, LOW);
    } else if (held > 40) {
      startFeed();
    }
  }
  lastBtn = b;

  if (feeding && millis() - feedStart >= 2000) {
    digitalWrite(FEED, LOW);
    feeding = false;
    lastFeed = millis();
  }

  if (!feeding && millis() - lastFeed >= interval) {
    startFeed();
  }

  digitalWrite(LED, feeding ? HIGH : LOW);
}

void startFeed() {
  digitalWrite(FEED, HIGH);
  feeding = true;
  feedStart = millis();
  Serial.println("feed");
}

/*
 * Freezer Over-Temperature Alarm
 * --------------------------------
 * Design notes:
 *  - A thermistor (NTC, 10k) in a divider with a 10k resistor to 5V.
 *  - We read the divider with the ADC and convert to Celsius.
 *  - If the freezer stays warmer than -15 C for more than 60 seconds,
 *    the piezo buzzer sounds and the red LED lights.
 *  - Acknowledge button silences the buzzer for 5 minutes (LED stays on).
 *  - Serial prints temperature once per second for debugging.
 *
 * Written by a tidy engineer. Arduino core only.
 */

// ---- Pin assignments ----
const uint8_t PIN_THERMISTOR = A0;
const uint8_t PIN_BUZZER     = 8;
const uint8_t PIN_LED        = 9;
const uint8_t PIN_ACK_BUTTON = 2;

// ---- Thermistor / divider constants ----
const float SERIES_RESISTANCE = 10000.0;  // 10k to 5V
const float NOMINAL_RESISTANCE = 10000.0; // 10k at 25 C
const float NOMINAL_TEMPERATURE = 25.0;   // C
const float BETA = 3950.0;                // thermistor beta
const float SUPPLY_VOLTAGE = 5.0;
const float ADC_MAX = 1023.0;

// ---- Alarm thresholds and timings ----
const float ALARM_TEMPERATURE_C = -15.0;
const unsigned long ALARM_DELAY_MS = 60000UL;   // 60 s above threshold
const unsigned long ACK_SILENCE_MS = 300000UL;  // 5 min buzzer silence
const unsigned long SERIAL_PERIOD_MS = 1000UL;

// ---- State ----
bool alarmActive = false;
bool buzzerSilenced = false;
unsigned long overTempSince = 0;
unsigned long ackTime = 0;
unsigned long lastSerialPrint = 0;

float readTemperatureC() {
  int raw = analogRead(PIN_THERMISTOR);
  if (raw <= 0) raw = 1;  // avoid divide-by-zero
  float voltage = raw * (SUPPLY_VOLTAGE / ADC_MAX);
  // Thermistor is on the low side of the divider.
  float resistance = SERIES_RESISTANCE * (voltage / (SUPPLY_VOLTAGE - voltage));
  float steinhart = resistance / NOMINAL_RESISTANCE;
  steinhart = log(steinhart);
  steinhart /= BETA;
  steinhart += 1.0 / (NOMINAL_TEMPERATURE + 273.15);
  steinhart = 1.0 / steinhart;
  return steinhart - 273.15;
}

void setup() {
  pinMode(PIN_BUZZER, OUTPUT);
  pinMode(PIN_LED, OUTPUT);
  pinMode(PIN_ACK_BUTTON, INPUT_PULLUP);
  digitalWrite(PIN_BUZZER, LOW);
  digitalWrite(PIN_LED, LOW);
  Serial.begin(9600);
  Serial.println(F("Freezer alarm ready"));
}

void loop() {
  unsigned long now = millis();
  float tempC = readTemperatureC();

  // Track how long we have been too warm.
  if (tempC > ALARM_TEMPERATURE_C) {
    if (overTempSince == 0) {
      overTempSince = now;
    }
    if (!alarmActive && (now - overTempSince >= ALARM_DELAY_MS)) {
      alarmActive = true;
      buzzerSilenced = false;
    }
  } else {
    overTempSince = 0;
    alarmActive = false;
    buzzerSilenced = false;
  }

  // Acknowledge button silences the buzzer for a while.
  if (digitalRead(PIN_ACK_BUTTON) == LOW && alarmActive) {
    buzzerSilenced = true;
    ackTime = now;
  }
  if (buzzerSilenced && (now - ackTime >= ACK_SILENCE_MS)) {
    buzzerSilenced = false;
  }

  // Drive outputs.
  digitalWrite(PIN_LED, alarmActive ? HIGH : LOW);
  bool soundBuzzer = alarmActive && !buzzerSilenced;
  digitalWrite(PIN_BUZZER, soundBuzzer ? HIGH : LOW);

  // Debug output once per second.
  if (now - lastSerialPrint >= SERIAL_PERIOD_MS) {
    lastSerialPrint = now;
    Serial.print(F("Temp: "));
    Serial.print(tempC, 2);
    Serial.print(F(" C  Alarm: "));
    Serial.println(alarmActive ? F("YES") : F("no"));
  }
}

// Fridge door alarm
// Buzzer on pin 8, reed switch on pin 2 to GND (closed = door shut)

const int REED_PIN = 2;
const int BUZZER_PIN = 8;
const unsigned long ALARM_DELAY = 30000; // 30 sec before beeping
const unsigned long BEEP_ON = 200;
const unsigned long BEEP_OFF = 800;

bool doorOpen = false;
unsigned long openSince = 0;
unsigned long lastBeep = 0;
bool buzzerOn = false;

void setup() {
  pinMode(REED_PIN, INPUT_PULLUP);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(BUZZER_PIN, LOW);
  Serial.begin(9600);
  Serial.println("Fridge alarm ready");
}

void loop() {
  // reed switch pulls to GND when door is closed
  bool closed = (digitalRead(REED_PIN) == LOW);

  if (!closed && !doorOpen) {
    // door just opened
    doorOpen = true;
    openSince = millis();
    Serial.println("Door opened");
  } else if (closed && doorOpen) {
    // door shut again, reset everything
    doorOpen = false;
    buzzerOn = false;
    digitalWrite(BUZZER_PIN, LOW);
    Serial.println("Door closed");
  }

  if (doorOpen) {
    unsigned long elapsed = millis() - openSince;
    if (elapsed >= ALARM_DELAY) {
      // beep pattern
      unsigned long now = millis();
      if (buzzerOn) {
        if (now - lastBeep >= BEEP_ON) {
          digitalWrite(BUZZER_PIN, LOW);
          buzzerOn = false;
          lastBeep = now;
        }
      } else {
        if (now - lastBeep >= BEEP_OFF) {
          digitalWrite(BUZZER_PIN, HIGH);
          buzzerOn = true;
          lastBeep = now;
        }
      }
    }
  }

  delay(10);
}

/*
 * Fume Extractor Fan Controller
 * -----------------------------
 * A tidy little controller for a soldering fume extractor.
 *
 * Design:
 *   - A push button toggles the fan on and off (debounced, active LOW
 *     with the internal pull-up, so the button shorts to GND).
 *   - A potentiometer sets the fan speed when the fan is running.
 *   - The fan is driven through a logic-level N-MOSFET on a PWM pin.
 *   - A status LED mirrors the fan state (on when running).
 *   - The fan never runs below MIN_DUTY, so a stalled motor can't
 *     overheat the FET; below that we just turn it off.
 *
 * Written by a tidy engineer. Arduino core only, no libraries.
 */

const uint8_t BUTTON_PIN   = 2;   // to GND, internal pull-up
const uint8_t POT_PIN      = A0;  // wiper of 10k pot across 5V/GND
const uint8_t FAN_PIN      = 9;   // PWM -> MOSFET gate
const uint8_t STATUS_LED   = 13;  // onboard LED as status

const unsigned long DEBOUNCE_MS = 30;
const int  MIN_DUTY        = 40;   // below this the fan may stall
const int  MAX_DUTY        = 255;

bool fanOn = false;
int  lastButtonReading = HIGH;
int  stableButtonState = HIGH;
unsigned long lastDebounceTime = 0;

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(FAN_PIN, OUTPUT);
  pinMode(STATUS_LED, OUTPUT);
  digitalWrite(FAN_PIN, LOW);
  digitalWrite(STATUS_LED, LOW);
  Serial.begin(9600);
  Serial.println(F("Fume extractor ready."));
}

void loop() {
  handleButton();
  updateFan();
}

// Debounce the toggle button and flip fanOn on a falling edge.
void handleButton() {
  int reading = digitalRead(BUTTON_PIN);

  if (reading != lastButtonReading) {
    lastDebounceTime = millis();
  }

  if ((millis() - lastDebounceTime) > DEBOUNCE_MS) {
    if (reading != stableButtonState) {
      stableButtonState = reading;
      if (stableButtonState == LOW) {
        fanOn = !fanOn;
        Serial.print(F("Fan "));
        Serial.println(fanOn ? F("ON") : F("OFF"));
      }
    }
  }

  lastButtonReading = reading;
}

// Map the pot to a duty cycle and drive the fan + status LED.
void updateFan() {
  if (!fanOn) {
    analogWrite(FAN_PIN, 0);
    digitalWrite(STATUS_LED, LOW);
    return;
  }

  int potValue = analogRead(POT_PIN);          // 0..1023
  int duty = map(potValue, 0, 1023, MIN_DUTY, MAX_DUTY);

  // Guard against a stalled fan at very low settings.
  if (duty < MIN_DUTY) {
    duty = 0;
  }

  analogWrite(FAN_PIN, duty);
  digitalWrite(STATUS_LED, HIGH);
}

// Garage door safety beam
// IR beam across the door opening, blocks closing if broken

const int BEAM_PIN = 2;      // IR receiver output, LOW when beam broken
const int RELAY_PIN = 8;     // relay to door opener, HIGH = allow close
const int LED_PIN = 13;      // onboard LED, on when beam broken

const unsigned long DEBOUNCE_MS = 30;
const unsigned long BEEP_MS = 500;

bool beamBroken = false;
bool lastRaw = true;
unsigned long lastChange = 0;
unsigned long brokenSince = 0;

void setup() {
  pinMode(BEAM_PIN, INPUT_PULLUP);
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, HIGH); // allow closing by default
  Serial.begin(9600);
  Serial.println("Safety beam ready");
}

void loop() {
  bool raw = digitalRead(BEAM_PIN); // true = beam clear

  // debounce the beam input
  if (raw != lastRaw) {
    lastChange = millis();
    lastRaw = raw;
  }

  if ((millis() - lastChange) > DEBOUNCE_MS) {
    bool nowBroken = !raw;
    if (nowBroken != beamBroken) {
      beamBroken = nowBroken;
      if (beamBroken) {
        brokenSince = millis();
        Serial.println("Beam BROKEN - stop door");
      } else {
        Serial.println("Beam clear");
      }
    }
  }

  // drive outputs
  if (beamBroken) {
    digitalWrite(RELAY_PIN, LOW);  // cut the close signal
    digitalWrite(LED_PIN, HIGH);
  } else {
    digitalWrite(RELAY_PIN, HIGH);
    digitalWrite(LED_PIN, LOW);
  }

  // if broken too long, blink LED as a warning
  if (beamBroken && (millis() - brokenSince) > BEEP_MS) {
    digitalWrite(LED_PIN, (millis() / 250) % 2);
  }

  delay(5);
}

// Gas leak buzzer
// MQ-2 sensor on A0, buzzer on pin 8

const int sensorPin = A0;
const int buzzerPin = 8;
const int threshold = 400;  // adjust this

int reading = 0;

void setup() {
  Serial.begin(9600);
  pinMode(buzzerPin, OUTPUT);
  digitalWrite(buzzerPin, LOW);
  Serial.println("Gas detector ready");
}

void loop() {
  reading = analogRead(sensorPin);
  Serial.print("Gas level: ");
  Serial.println(reading);

  if (reading > threshold) {
    // gas detected, sound the alarm
    tone(buzzerPin, 1000);
    delay(200);
    noTone(buzzerPin);
    delay(200);
  } else {
    noTone(buzzerPin);
    digitalWrite(buzzerPin, LOW);
    delay(500);
  }
}

// Greenhouse Vent Opener
// Written by a beginner. This opens a vent when it gets too hot
// and closes it when it cools down. Read the comments!

// ---- Pin setup ----
// Pin 9 drives the motor through a transistor (ignore the transistor
// wiring details, just know HIGH = motor runs).
const int MOTOR_PIN = 9;

// Pin 2 is the button. We use INPUT_PULLUP so no resistor needed.
// Pressing the button connects to GND, so pressed = LOW.
const int BUTTON_PIN = 2;

// Pin A0 reads the temperature sensor (LM35 style, 10mV per degree C).
const int SENSOR_PIN = A0;

// ---- Settings ----
// Above this temperature we open the vent.
const float HOT_C = 28.0;
// Below this temperature we close it again.
const float COOL_C = 22.0;

// How long the motor runs to fully open or close (milliseconds).
// I guessed 8 seconds. Change this if your vent needs more time.
const unsigned long TRAVEL_MS = 8000;

// ---- State ----
// true means the vent is open (or trying to be).
bool ventOpen = false;

void setup() {
  // Motor pin is an output. Start it off.
  pinMode(MOTOR_PIN, OUTPUT);
  digitalWrite(MOTOR_PIN, LOW);

  // Button pin is an input with the internal pull-up on.
  pinMode(BUTTON_PIN, INPUT_PULLUP);

  // Serial is just for watching numbers in the monitor.
  // You can ignore it if you want, it does not affect the vent.
  Serial.begin(9600);
}

void loop() {
  // Read the sensor. analogRead gives 0..1023.
  // 5V / 1024 steps = about 0.00488 V per step.
  // LM35 gives 0.01 V per degree, so each step is about 0.488 C.
  int raw = analogRead(SENSOR_PIN);
  float volts = raw * (5.0 / 1024.0);
  float tempC = volts * 100.0;

  Serial.print("Temp C: ");
  Serial.println(tempC);

  // Manual override: if the button is held, just stop everything.
  // This is handy if the motor is stuck. Ignore the vent logic then.
  if (digitalRead(BUTTON_PIN) == LOW) {
    digitalWrite(MOTOR_PIN, LOW);
    delay(200);
    return;
  }

  // Too hot and vent is closed? Open it.
  if (tempC > HOT_C && !ventOpen) {
    Serial.println("Hot! Opening vent.");
    runMotor(TRAVEL_MS);
    ventOpen = true;
  }
  // Cool enough and vent is open? Close it.
  else if (tempC < COOL_C && ventOpen) {
    Serial.println("Cool. Closing vent.");
    runMotor(TRAVEL_MS);
    ventOpen = false;
  }

  // Check twice a second. No need to be faster than that.
  delay(500);
}

// Run the motor for a set time, then stop it.
// We do not know direction here (one motor, one pin in this simple build),
// so this just runs it. A real build would use two pins for direction.
void runMotor(unsigned long ms) {
  digitalWrite(MOTOR_PIN, HIGH);
  delay(ms);
  digitalWrite(MOTOR_PIN, LOW);
}

/*
 * Hallway Motion Light
 * ---------------------
 * Turns on a lamp when a PIR sensor sees motion, and keeps it on for a
 * hold time after the last motion so you are not left in the dark while
 * walking. A small amount of hysteresis is added so that noise on the
 * analog input does not retrigger the timer.
 *
 * Wiring:
 *   PIR OUT  -> D2  (digital input, HIGH when motion)
 *   LAMP     -> D9  (digital output, drives a relay module)
 *   LDR      -> A0  (optional ambient light sensor, 10k divider to GND)
 *
 * The lamp is only allowed to turn on when the room is dark enough,
 * so the hallway light does not switch on in daylight.
 */

const uint8_t PIR_PIN   = 2;
const uint8_t LAMP_PIN  = 9;
const uint8_t LDR_PIN   = A0;

const unsigned long HOLD_TIME_MS   = 30000UL;  // 30 s after last motion
const unsigned long SAMPLE_PERIOD  = 50UL;     // debounce / poll period

const int DARK_THRESHOLD = 400;  // below this ADC value = dark
const int LIGHT_HYST     = 40;   // hysteresis band around threshold

bool lampOn = false;
unsigned long lastMotionMs = 0;
unsigned long lastSampleMs = 0;

void setup() {
  pinMode(PIR_PIN, INPUT);
  pinMode(LAMP_PIN, OUTPUT);
  digitalWrite(LAMP_PIN, LOW);
  Serial.begin(9600);
  Serial.println(F("Hallway motion light ready"));
}

bool isDark() {
  int level = analogRead(LDR_PIN);
  // Hysteresis: once dark, require a bit more light to leave dark state.
  static bool darkState = true;
  if (darkState) {
    if (level > DARK_THRESHOLD + LIGHT_HYST) darkState = false;
  } else {
    if (level < DARK_THRESHOLD - LIGHT_HYST) darkState = true;
  }
  return darkState;
}

void loop() {
  unsigned long now = millis();

  if (now - lastSampleMs >= SAMPLE_PERIOD) {
    lastSampleMs = now;

    if (digitalRead(PIR_PIN) == HIGH && isDark()) {
      lastMotionMs = now;
      if (!lampOn) {
        lampOn = true;
        digitalWrite(LAMP_PIN, HIGH);
        Serial.println(F("Motion: lamp on"));
      }
    }
  }

  if (lampOn && (now - lastMotionMs >= HOLD_TIME_MS)) {
    lampOn = false;
    digitalWrite(LAMP_PIN, LOW);
    Serial.println(F("Timeout: lamp off"));
  }
}

/*
 * Hand Sanitizer Pump Controller
 * --------------------------------
 * Design: an IR reflective sensor detects a hand in front of the
 * dispenser. When a hand is present for DEBOUNCE_MS, we drive a
 * small peristaltic pump (via a MOSFET) for PUMP_MS to dispense a
 * dose. A minimum gap of COOLDOWN_MS between doses prevents
 * double-dispensing. A status LED mirrors pump activity.
 *
 * Wiring:
 *   D2  - IR sensor output (active LOW when hand detected)
 *   D9  - Pump MOSFET gate (HIGH = pump on)
 *   D13 - Status LED (onboard)
 */

const uint8_t  SENSOR_PIN   = 2;
const uint8_t  PUMP_PIN     = 9;
const uint8_t  LED_PIN      = 13;

const uint16_t DEBOUNCE_MS  = 50;    // hand must be steady this long
const uint16_t PUMP_MS      = 400;   // dose duration
const uint16_t COOLDOWN_MS  = 1500;  // min gap between doses

bool          handLatched = false;
unsigned long handSince   = 0;
unsigned long lastDose    = 0;

void setup() {
  pinMode(SENSOR_PIN, INPUT_PULLUP);
  pinMode(PUMP_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(PUMP_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
}

void loop() {
  bool handPresent = (digitalRead(SENSOR_PIN) == LOW);

  // Track how long the hand has been continuously present.
  if (handPresent && !handLatched) {
    handLatched = true;
    handSince = millis();
  } else if (!handPresent) {
    handLatched = false;
  }

  bool steady = handLatched && (millis() - handSince >= DEBOUNCE_MS);
  bool cooled = (millis() - lastDose >= COOLDOWN_MS);

  if (steady && cooled) {
    dispense();
    lastDose = millis();
    handLatched = false;  // require hand removal before next dose
  }
}

void dispense() {
  digitalWrite(PUMP_PIN, HIGH);
  digitalWrite(LED_PIN, HIGH);
  delay(PUMP_MS);
  digitalWrite(PUMP_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
}

// Hot Tub Temperature Guard
// Written by a beginner. This keeps an eye on the hot tub water
// and turns on a warning buzzer if it gets too hot or too cold.
// I used only the Arduino core, no extra libraries, because
// installing libraries confused me at first.

// ---- Pin setup ----
// A10 is an analog input. On the Uno the analog pins can also be
// used as digital, but here we read a real voltage.
const int SENSOR_PIN = A0;

// Buzzer on pin 8. It is a plain piezo, so we just toggle it.
const int BUZZER_PIN = 8;

// Green LED on pin 7 means "all good".
const int OK_LED_PIN = 7;

// ---- Temperature limits (in degrees C) ----
// Hot tubs are usually kept around 37-39 C. I picked 40 as too hot
// and 30 as too cold. Change these numbers if you like.
const float TOO_HOT_C = 40.0;
const float TOO_COLD_C = 30.0;

// The sensor is a TMP36-style analog sensor. It outputs 0.5V at 0 C
// and 10mV per degree C. The Uno reads 0-1023 over 0-5V.
const float VOLTS_PER_COUNT = 5.0 / 1024.0;

// We only check every 2 seconds. Reading faster just makes noise.
const unsigned long CHECK_INTERVAL_MS = 2000;
unsigned long lastCheck = 0;

void setup() {
  // Serial is handy for debugging. Ignore it in normal use.
  Serial.begin(9600);

  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(OK_LED_PIN, OUTPUT);

  // Start with everything off so we do not beep on power-up.
  digitalWrite(BUZZER_PIN, LOW);
  digitalWrite(OK_LED_PIN, LOW);
}

void loop() {
  // millis() rolls over after about 49 days. The subtraction below
  // still works across the rollover, so do not worry about it.
  unsigned long now = millis();
  if (now - lastCheck < CHECK_INTERVAL_MS) {
    return;  // not time yet, skip this loop
  }
  lastCheck = now;

  // Read the sensor. analogRead returns 0-1023.
  int raw = analogRead(SENSOR_PIN);

  // Convert counts to volts, then volts to degrees C.
  float volts = raw * VOLTS_PER_COUNT;
  float tempC = (volts - 0.5) * 100.0;

  // Print for debugging. You can ignore this in the final build.
  Serial.print("raw=");
  Serial.print(raw);
  Serial.print(" tempC=");
  Serial.println(tempC);

  // Decide if we are in range. Note: if the sensor is unplugged
  // the reading floats and may look cold. That is a known flaw.
  if (tempC > TOO_HOT_C || tempC < TOO_COLD_C) {
    // Out of range: beep and keep the green LED off.
    digitalWrite(OK_LED_PIN, LOW);
    tone(BUZZER_PIN, 1000);  // 1 kHz beep
  } else {
    // In range: silence the buzzer and light the green LED.
    noTone(BUZZER_PIN);
    digitalWrite(OK_LED_PIN, HIGH);
  }
}

// Bathroom fan - turns on when it gets steamy
// DHT22 on pin 2, relay on pin 8

#include <DHT.h>

#define DHTPIN 2
#define DHTTYPE DHT22
#define RELAY 8
#define LED 13

DHT dht(DHTPIN, DHTTYPE);

const int onHumidity = 65;   // turn fan on above this
const int offHumidity = 55;  // turn off below this
const unsigned long minRunTime = 120000UL; // keep fan on at least 2 min

bool fanOn = false;
unsigned long fanStart = 0;
unsigned long lastRead = 0;

void setup() {
  Serial.begin(9600);
  pinMode(RELAY, OUTPUT);
  pinMode(LED, OUTPUT);
  digitalWrite(RELAY, LOW); // relay off
  digitalWrite(LED, LOW);
  dht.begin();
  Serial.println("Bathroom fan ready");
}

void loop() {
  // read sensor every 2 seconds
  if (millis() - lastRead >= 2000) {
    lastRead = millis();

    float h = dht.readHumidity();
    float t = dht.readTemperature();

    if (isnan(h) || isnan(t)) {
      Serial.println("DHT read failed");
      return;
    }

    Serial.print("Humidity: ");
    Serial.print(h);
    Serial.print(" %  Temp: ");
    Serial.print(t);
    Serial.println(" C");

    if (!fanOn && h > onHumidity) {
      fanOn = true;
      fanStart = millis();
      digitalWrite(RELAY, HIGH);
      digitalWrite(LED, HIGH);
      Serial.println("Fan ON");
    }
    else if (fanOn && h < offHumidity) {
      // only stop if it has run long enough
      if (millis() - fanStart > minRunTime) {
        fanOn = false;
        digitalWrite(RELAY, LOW);
        digitalWrite(LED, LOW);
        Serial.println("Fan OFF");
      }
    }
  }
}

// Egg turner for incubator
// Turns tray left/right every 2 hours using a geared motor
// Hobbyist build - Arduino Uno

const int motorPin1 = 8;   // motor driver IN1
const int motorPin2 = 9;   // motor driver IN2
const int ledPin = 13;     // onboard LED = status

const unsigned long turnInterval = 7200000UL; // 2 hours in ms
const unsigned long runTime = 4000;           // motor runs 4 sec per turn

unsigned long lastTurn = 0;
bool turning = false;
bool direction = true; // true = one way, false = other
unsigned long turnStart = 0;

void setup() {
  pinMode(motorPin1, OUTPUT);
  pinMode(motorPin2, OUTPUT);
  pinMode(ledPin, OUTPUT);
  stopMotor();
  lastTurn = millis();
}

void loop() {
  unsigned long now = millis();

  if (!turning && (now - lastTurn >= turnInterval)) {
    startTurn();
    turning = true;
    turnStart = now;
    lastTurn = now;
  }

  if (turning && (now - turnStart >= runTime)) {
    stopMotor();
    turning = false;
    direction = !direction; // flip for next time
  }
}

void startTurn() {
  digitalWrite(ledPin, HIGH);
  if (direction) {
    digitalWrite(motorPin1, HIGH);
    digitalWrite(motorPin2, LOW);
  } else {
    digitalWrite(motorPin1, LOW);
    digitalWrite(motorPin2, HIGH);
  }
}

void stopMotor() {
  digitalWrite(motorPin1, LOW);
  digitalWrite(motorPin2, LOW);
  digitalWrite(ledPin, LOW);
}

// Kitchen timer - counts down and beeps
// Arduino Uno, 16x2 LCD, 3 buttons, buzzer

#include <LiquidCrystal.h>

LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

const int btnUp = 6;
const int btnDown = 7;
const int btnStart = 8;
const int buzzer = 9;

long setSeconds = 300;   // default 5 min
long remaining = 0;
bool running = false;
unsigned long lastTick = 0;

void showTime(long s) {
  int m = s / 60;
  int sec = s % 60;
  lcd.setCursor(0, 1);
  if (m < 10) lcd.print('0');
  lcd.print(m);
  lcd.print(':');
  if (sec < 10) lcd.print('0');
  lcd.print(sec);
  lcd.print("   ");
}

void setup() {
  lcd.begin(16, 2);
  pinMode(btnUp, INPUT_PULLUP);
  pinMode(btnDown, INPUT_PULLUP);
  pinMode(btnStart, INPUT_PULLUP);
  pinMode(buzzer, OUTPUT);
  lcd.print("Kitchen Timer");
  showTime(setSeconds);
}

void loop() {
  // adjust the set time when not running
  if (!running) {
    if (digitalRead(btnUp) == LOW) {
      setSeconds += 30;
      if (setSeconds > 5999) setSeconds = 5999;
      showTime(setSeconds);
      delay(200);
    }
    if (digitalRead(btnDown) == LOW) {
      setSeconds -= 30;
      if (setSeconds < 30) setSeconds = 30;
      showTime(setSeconds);
      delay(200);
    }
  }

  // start / stop
  if (digitalRead(btnStart) == LOW) {
    if (!running) {
      remaining = setSeconds;
      running = true;
      lastTick = millis();
      lcd.setCursor(0, 0);
      lcd.print("Counting...     ");
    } else {
      running = false;
      lcd.setCursor(0, 0);
      lcd.print("Paused          ");
    }
    delay(300);
  }

  // countdown
  if (running) {
    if (millis() - lastTick >= 1000) {
      lastTick += 1000;
      remaining--;
      showTime(remaining);
      if (remaining <= 0) {
        running = false;
        lcd.setCursor(0, 0);
        lcd.print("DONE!           ");
        for (int i = 0; i < 5; i++) {
          tone(buzzer, 2000);
          delay(300);
          noTone(buzzer);
          delay(200);
        }
        lcd.setCursor(0, 0);
        lcd.print("Kitchen Timer   ");
        showTime(setSeconds);
      }
    }
  }
}

// Laser Cutter Lid Interlock
// Written by a beginner. This sketch watches a lid switch and a laser
// "armed" button. If the lid opens while armed, it cuts the laser enable
// line and sounds a buzzer until the operator resets it.

// ---- Pin map (change these if you rewire) ----
const int LID_SWITCH_PIN = 2;   // lid switch to GND when lid is CLOSED
const int ARM_BUTTON_PIN = 3;   // momentary button to GND, arms the laser
const int RESET_BUTTON_PIN = 4; // momentary button to GND, clears a fault
const int LASER_ENABLE_PIN = 8; // goes HIGH to allow the laser to fire
const int BUZZER_PIN = 9;       // piezo buzzer, other leg to GND
const int GREEN_LED_PIN = 10;   // armed and safe indicator
const int RED_LED_PIN = 11;     // fault indicator

// ---- State variables ----
bool armed = false;
bool fault = false;

void setup() {
  // Inputs use the internal pull-ups, so a pressed switch reads LOW.
  // Ignore the fact that this means a broken wire looks like pressed.
  pinMode(LID_SWITCH_PIN, INPUT_PULLUP);
  pinMode(ARM_BUTTON_PIN, INPUT_PULLUP);
  pinMode(RESET_BUTTON_PIN, INPUT_PULLUP);

  // Outputs start safe: laser disabled, no noise, red light on.
  pinMode(LASER_ENABLE_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(GREEN_LED_PIN, OUTPUT);
  pinMode(RED_LED_PIN, OUTPUT);

  digitalWrite(LASER_ENABLE_PIN, LOW);
  digitalWrite(BUZZER_PIN, LOW);
  digitalWrite(GREEN_LED_PIN, LOW);
  digitalWrite(RED_LED_PIN, HIGH);

  // Serial is only for debugging; you can ignore it in normal use.
  Serial.begin(9600);
  Serial.println("Lid interlock ready");
}

void loop() {
  // A closed lid pulls the pin to GND, so LOW means closed.
  bool lidClosed = (digitalRead(LID_SWITCH_PIN) == LOW);

  // If the lid opens while armed, latch a fault. The laser enable
  // line is dropped immediately, before anything else happens.
  if (armed && !lidClosed) {
    armed = false;
    fault = true;
    digitalWrite(LASER_ENABLE_PIN, LOW);
    Serial.println("FAULT: lid opened while armed");
  }

  // Arm button only works when the lid is closed and there is no fault.
  // The 200 ms delay is a crude debounce; it also slows the whole loop.
  if (digitalRead(ARM_BUTTON_PIN) == LOW && lidClosed && !fault) {
    delay(200);
    if (digitalRead(ARM_BUTTON_PIN) == LOW) {
      armed = true;
      Serial.println("Armed");
    }
  }

  // Reset clears the fault, but only if the lid is closed again.
  if (digitalRead(RESET_BUTTON_PIN) == LOW && lidClosed) {
    delay(200);
    if (digitalRead(RESET_BUTTON_PIN) == LOW) {
      fault = false;
      Serial.println("Fault cleared");
    }
  }

  // Drive the outputs from the current state.
  if (fault) {
    digitalWrite(LASER_ENABLE_PIN, LOW);
    digitalWrite(GREEN_LED_PIN, LOW);
    digitalWrite(RED_LED_PIN, HIGH);
    tone(BUZZER_PIN, 1000); // 1 kHz alarm
  } else if (armed) {
    digitalWrite(LASER_ENABLE_PIN, HIGH);
    digitalWrite(GREEN_LED_PIN, HIGH);
    digitalWrite(RED_LED_PIN, LOW);
    noTone(BUZZER_PIN);
  } else {
    digitalWrite(LASER_ENABLE_PIN, LOW);
    digitalWrite(GREEN_LED_PIN, LOW);
    digitalWrite(RED_LED_PIN, HIGH);
    noTone(BUZZER_PIN);
  }
}

// Simple metronome
// pot on A0 sets tempo, button on D2 taps start/stop
// piezo on D8 clicks, LED on D13 blinks on beat

const int POT_PIN = A0;
const int BUTTON_PIN = 2;
const int PIEZO_PIN = 8;
const int LED_PIN = 13;

bool running = false;
bool lastButton = HIGH;
unsigned long lastBeat = 0;
unsigned long beatInterval = 500; // ms, default 120 bpm

void setup() {
  pinMode(PIEZO_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  Serial.begin(9600);
}

void loop() {
  // read tempo pot: 0-1023 -> 40 to 240 bpm
  int potVal = analogRead(POT_PIN);
  int bpm = map(potVal, 0, 1023, 40, 240);
  beatInterval = 60000UL / bpm;

  // button debounce-ish
  bool button = digitalRead(BUTTON_PIN);
  if (button == LOW && lastButton == HIGH) {
    running = !running;
    lastBeat = millis();
    Serial.print("running: ");
    Serial.println(running);
    delay(20); // crude debounce
  }
  lastButton = button;

  if (running) {
    unsigned long now = millis();
    if (now - lastBeat >= beatInterval) {
      lastBeat = now;
      click();
    }
  } else {
    digitalWrite(LED_PIN, LOW);
  }
}

void click() {
  digitalWrite(LED_PIN, HIGH);
  tone(PIEZO_PIN, 2000, 15);
  delay(15);
  digitalWrite(LED_PIN, LOW);
}

// parking distance beeper
// HC-SR04 + buzzer

const int TRIG = 9;
const int ECHO = 10;
const int BUZZ = 8;

void setup() {
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(BUZZ, OUTPUT);
  Serial.begin(9600);
}

// read distance in cm
long getDistance() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);

  long dur = pulseIn(ECHO, HIGH, 30000);
  if (dur == 0) return -1; // no echo
  return dur / 58;
}

void loop() {
  long cm = getDistance();
  Serial.print("dist: ");
  Serial.println(cm);

  if (cm < 0) {
    // nothing seen, stay quiet
    noTone(BUZZ);
  }
  else if (cm < 10) {
    // very close - fast beep
    tone(BUZZ, 2000);
    delay(80);
    noTone(BUZZ);
    delay(80);
  }
  else if (cm < 30) {
    // getting close - medium beep
    tone(BUZZ, 1500);
    delay(120);
    noTone(BUZZ);
    delay(250);
  }
  else if (cm < 60) {
    // warning zone - slow beep
    tone(BUZZ, 1000);
    delay(100);
    noTone(BUZZ);
    delay(600);
  }
  else {
    // clear
    noTone(BUZZ);
    delay(100);
  }
}

const uint8_t PIN_GATE = 2;
const uint8_t PIN_LED = 13;

volatile uint32_t riseUs = 0;
volatile uint32_t fallUs = 0;
volatile bool riseSeen = false;
volatile bool fallSeen = false;

void onRise() {
  if (!riseSeen) {
    riseUs = micros();
    riseSeen = true;
    fallSeen = false;
  }
}

void onFall() {
  if (riseSeen && !fallSeen) {
    fallUs = micros();
    fallSeen = true;
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(PIN_GATE, INPUT_PULLUP);
  pinMode(PIN_LED, OUTPUT);
  digitalWrite(PIN_LED, LOW);
  attachInterrupt(digitalPinToInterrupt(PIN_GATE), onRise, FALLING);
  Serial.println(F("photo gate ready"));
}

void loop() {
  static bool lastFall = false;
  if (fallSeen && !lastFall) {
    uint32_t dt = fallUs - riseUs;
    Serial.print(F("block_us="));
    Serial.println(dt);
    digitalWrite(PIN_LED, HIGH);
    delay(50);
    digitalWrite(PIN_LED, LOW);
    riseSeen = false;
    fallSeen = false;
  }
  lastFall = fallSeen;

  if (riseSeen && !fallSeen) {
    uint32_t now = micros();
    if (now - riseUs > 2000000UL) {
      Serial.println(F("timeout"));
      riseSeen = false;
    }
  }
}

// Pinball Score Counter
// Written by a beginner, so I'm explaining everything!
// This counts points when you hit the targets and shows the score on Serial.

// ---- Pin setup ----
// Target switch on pin 2. We use INPUT_PULLUP so the switch just
// connects the pin to ground when hit. No external resistor needed.
const int targetPin = 2;

// Bumper switch on pin 3, same idea.
const int bumperPin = 3;

// ---- Score values ----
// Hitting a target is worth 100 points.
const int targetPoints = 100;
// Hitting a bumper is worth 250 points.
const int bumperPoints = 250;

// ---- State tracking ----
// We remember the last reading so we only score on a fresh press,
// not while the switch is held down. (Ignore the bouncing for now,
// a real machine would add debounce but let's keep it simple.)
int lastTarget = HIGH;
int lastBumper = HIGH;

// The running score. Use unsigned long so it can get big.
unsigned long score = 0;

void setup() {
  // Switches read as HIGH when not pressed because of the pullup.
  pinMode(targetPin, INPUT_PULLUP);
  pinMode(bumperPin, INPUT_PULLUP);

  // Start the serial monitor so we can watch the score.
  Serial.begin(9600);
  Serial.println("Pinball ready! Score starts at 0.");
}

void loop() {
  // Read both switches every pass through the loop.
  int targetNow = digitalRead(targetPin);
  int bumperNow = digitalRead(bumperPin);

  // A press is when it goes from HIGH (open) to LOW (closed).
  if (lastTarget == HIGH && targetNow == LOW) {
    score = score + targetPoints;
    Serial.print("Target hit! +");
    Serial.print(targetPoints);
    Serial.print("  Score: ");
    Serial.println(score);
  }

  if (lastBumper == HIGH && bumperNow == LOW) {
    score = score + bumperPoints;
    Serial.print("Bumper hit! +");
    Serial.print(bumperPoints);
    Serial.print("  Score: ");
    Serial.println(score);
  }

  // Save the readings for next time so we can detect the edge.
  lastTarget = targetNow;
  lastBumper = bumperNow;

  // Tiny delay so the serial output doesn't flood.
  delay(10);
}

// Plant light scheduler
// Turns a grow light on in the morning and off at night
// Uses a relay on pin 7 and a pot to set the on-hour

const int RELAY_PIN = 7;
const int POT_PIN = A0;

// light schedule in hours (24h clock)
int onHour = 8;
int offHour = 20;

unsigned long lastCheck = 0;
const unsigned long CHECK_MS = 1000;

// fake clock for testing without an RTC
unsigned long secondsSinceBoot = 0;
int currentHour = 0;

void setup() {
  pinMode(RELAY_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, LOW);
  Serial.begin(9600);
  Serial.println("Plant light scheduler ready");
}

void loop() {
  // advance our simple clock
  if (millis() - lastCheck >= CHECK_MS) {
    lastCheck = millis();
    secondsSinceBoot++;
    if (secondsSinceBoot >= 3600UL) {
      secondsSinceBoot = 0;
      currentHour++;
      if (currentHour >= 24) currentHour = 0;
    }
  }

  // read pot to adjust on-hour, 0-23
  int potVal = analogRead(POT_PIN);
  onHour = map(potVal, 0, 1023, 0, 23);
  offHour = onHour + 12;
  if (offHour >= 24) offHour -= 24;

  // decide if light should be on
  bool lightOn = false;
  if (onHour < offHour) {
    lightOn = (currentHour >= onHour && currentHour < offHour);
  } else {
    // wraps past midnight
    lightOn = (currentHour >= onHour || currentHour < offHour);
  }

  digitalWrite(RELAY_PIN, lightOn ? HIGH : LOW);

  // print status every so often
  static unsigned long lastPrint = 0;
  if (millis() - lastPrint > 5000) {
    lastPrint = millis();
    Serial.print("hour=");
    Serial.print(currentHour);
    Serial.print(" on=");
    Serial.print(onHour);
    Serial.print(" off=");
    Serial.print(offHour);
    Serial.print(" light=");
    Serial.println(lightOn ? "ON" : "OFF");
  }
}

#include <EEPROM.h>

const uint8_t ON_PIN = 8;
const uint8_t OFF_PIN = 9;
const uint8_t RELAY_PIN = 7;
const uint8_t LED_PIN = 13;
const uint8_t POT_PIN = A0;

const int EEPROM_MAGIC_ADDR = 0;
const int EEPROM_ON_ADDR = 2;
const int EEPROM_OFF_ADDR = 4;
const uint16_t MAGIC = 0xA5C3;

uint16_t onMin = 9 * 60;
uint16_t offMin = 17 * 60;
bool pumpOn = false;
unsigned long lastBlink = 0;
bool ledState = false;

uint16_t readMin(int addr) {
  uint16_t v = EEPROM.read(addr);
  v |= (uint16_t)EEPROM.read(addr + 1) << 8;
  return v;
}

void writeMin(int addr, uint16_t v) {
  EEPROM.write(addr, v & 0xFF);
  EEPROM.write(addr + 1, v >> 8);
}

void loadSettings() {
  uint16_t m = readMin(EEPROM_MAGIC_ADDR);
  if (m == MAGIC) {
    onMin = readMin(EEPROM_ON_ADDR);
    offMin = readMin(EEPROM_OFF_ADDR);
    if (onMin > 1439) onMin = 540;
    if (offMin > 1439) offMin = 1020;
  }
}

void saveSettings() {
  writeMin(EEPROM_MAGIC_ADDR, MAGIC);
  writeMin(EEPROM_ON_ADDR, onMin);
  writeMin(EEPROM_OFF_ADDR, offMin);
}

void setRelay(bool on) {
  pumpOn = on;
  digitalWrite(RELAY_PIN, on ? HIGH : LOW);
}

void setup() {
  pinMode(ON_PIN, INPUT_PULLUP);
  pinMode(OFF_PIN, INPUT_PULLUP);
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, LOW);
  loadSettings();
  Serial.begin(9600);
}

void loop() {
  static unsigned long lastBtn = 0;
  static bool prevOn = HIGH, prevOff = HIGH;

  bool bOn = digitalRead(ON_PIN);
  bool bOff = digitalRead(OFF_PIN);

  if (bOn == LOW && prevOn == HIGH && millis() - lastBtn > 250) {
    lastBtn = millis();
    onMin = map(analogRead(POT_PIN), 0, 1023, 0, 1439);
    saveSettings();
  }
  if (bOff == LOW && prevOff == HIGH && millis() - lastBtn > 250) {
    lastBtn = millis();
    offMin = map(analogRead(POT_PIN), 0, 1023, 0, 1439);
    saveSettings();
  }
  prevOn = bOn;
  prevOff = bOff;

  unsigned long secs = millis() / 1000UL;
  uint16_t nowMin = (secs / 60UL) % 1440;

  bool shouldRun;
  if (onMin <= offMin) {
    shouldRun = (nowMin >= onMin && nowMin < offMin);
  } else {
    shouldRun = (nowMin >= onMin || nowMin < offMin);
  }

  if (shouldRun != pumpOn) setRelay(shouldRun);

  if (millis() - lastBlink >= (pumpOn ? 1000 : 250)) {
    lastBlink = millis();
    ledState = !ledState;
    digitalWrite(LED_PIN, ledState);
  }
}

const uint8_t BTN[4] = {2, 3, 4, 5};
const uint8_t LED[4] = {8, 9, 10, 11};
const uint8_t BUZZ = 12;
const uint8_t RESET = 6;
const uint8_t ARM = 7;

bool locked = false;
int8_t winner = -1;
bool armed = false;

void setup() {
  for (uint8_t i = 0; i < 4; i++) {
    pinMode(BTN[i], INPUT_PULLUP);
    pinMode(LED[i], OUTPUT);
    digitalWrite(LED[i], LOW);
  }
  pinMode(BUZZ, OUTPUT);
  pinMode(RESET, INPUT_PULLUP);
  pinMode(ARM, INPUT_PULLUP);
  Serial.begin(9600);
}

void loop() {
  if (digitalRead(RESET) == LOW) {
    locked = false;
    winner = -1;
    armed = false;
    for (uint8_t i = 0; i < 4; i++) digitalWrite(LED[i], LOW);
    digitalWrite(BUZZ, LOW);
    delay(200);
  }

  if (digitalRead(ARM) == LOW) {
    armed = true;
    delay(200);
  }

  if (!armed || locked) return;

  for (uint8_t i = 0; i < 4; i++) {
    if (digitalRead(BTN[i]) == LOW) {
      winner = i;
      locked = true;
      digitalWrite(LED[i], HIGH);
      tone(BUZZ, 1000 + i * 200, 300);
      Serial.print("WIN ");
      Serial.println(i);
      delay(50);
      return;
    }
  }
}

const uint8_t RED=8, AMBER=9, GREEN=10;
const uint8_t SENSOR_A=2, SENSOR_B=3;
const uint8_t SERVO_PIN=5;
const uint8_t BUZZER=6;

bool trainPresent=false;
bool lastA=false, lastB=false;
unsigned long lastEdge=0;
unsigned long blinkTimer=0;
bool blinkState=false;

void setup(){
  pinMode(RED,OUTPUT);
  pinMode(AMBER,OUTPUT);
  pinMode(GREEN,OUTPUT);
  pinMode(BUZZER,OUTPUT);
  pinMode(SENSOR_A,INPUT_PULLUP);
  pinMode(SENSOR_B,INPUT_PULLUP);
  pinMode(SERVO_PIN,OUTPUT);
  digitalWrite(GREEN,HIGH);
  digitalWrite(RED,LOW);
  digitalWrite(AMBER,LOW);
  digitalWrite(BUZZER,LOW);
  digitalWrite(SERVO_PIN,LOW);
  Serial.begin(9600);
}

void gateDown(){
  digitalWrite(SERVO_PIN,HIGH);
}

void gateUp(){
  digitalWrite(SERVO_PIN,LOW);
}

void loop(){
  bool a=!digitalRead(SENSOR_A);
  bool b=!digitalRead(SENSOR_B);
  unsigned long now=millis();

  if(a && !lastA){
    lastEdge=now;
    if(!trainPresent){
      trainPresent=true;
      digitalWrite(GREEN,LOW);
      digitalWrite(AMBER,HIGH);
      delay(1500);
      digitalWrite(AMBER,LOW);
      gateDown();
      blinkTimer=now;
    }
  }
  if(b && !lastB){
    lastEdge=now;
    if(trainPresent){
      trainPresent=false;
      gateUp();
      digitalWrite(RED,LOW);
      digitalWrite(AMBER,LOW);
      digitalWrite(GREEN,HIGH);
      digitalWrite(BUZZER,LOW);
    }
  }
  lastA=a;
  lastB=b;

  if(trainPresent){
    if(now-blinkTimer>=400){
      blinkTimer=now;
      blinkState=!blinkState;
      digitalWrite(RED,blinkState);
      digitalWrite(BUZZER,blinkState);
    }
  }

  if(trainPresent && (now-lastEdge>20000)){
    trainPresent=false;
    gateUp();
    digitalWrite(RED,LOW);
    digitalWrite(BUZZER,LOW);
    digitalWrite(GREEN,HIGH);
  }
}

const uint8_t REED_PIN = 2;
const uint8_t LED_PIN = 13;
const unsigned long DEBOUNCE_MS = 50;
const float MM_PER_TIP = 0.2794;

volatile unsigned long tipCount = 0;
volatile unsigned long lastTipMs = 0;
unsigned long reportedCount = 0;
unsigned long lastReportMs = 0;
const unsigned long REPORT_MS = 5000;

void onTip() {
  unsigned long now = millis();
  if (now - lastTipMs >= DEBOUNCE_MS) {
    tipCount++;
    lastTipMs = now;
  }
}

void setup() {
  pinMode(REED_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
  attachInterrupt(digitalPinToInterrupt(REED_PIN), onTip, FALLING);
  Serial.println(F("rain gauge ready"));
}

void loop() {
  unsigned long now = millis();
  if (now - lastReportMs >= REPORT_MS) {
    lastReportMs = now;
    noInterrupts();
    unsigned long c = tipCount;
    interrupts();
    if (c != reportedCount) {
      reportedCount = c;
      Serial.print(F("tips="));
      Serial.print(c);
      Serial.print(F(" mm="));
      Serial.println(c * MM_PER_TIP, 2);
      digitalWrite(LED_PIN, HIGH);
      delay(20);
      digitalWrite(LED_PIN, LOW);
    }
  }
}

// Reaction Time Game
// Press the button as fast as you can after the LED lights up

const int LED_PIN = 8;
const int BUTTON_PIN = 2;

unsigned long startTime;
unsigned long reactionTime;
bool waiting = false;
bool gameActive = false;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  Serial.begin(9600);
  randomSeed(analogRead(0));
  Serial.println("Reaction Time Game");
  Serial.println("Press button to start");
}

void loop() {
  // wait for button press to start a round
  if (!gameActive && digitalRead(BUTTON_PIN) == LOW) {
    delay(50); // debounce
    if (digitalRead(BUTTON_PIN) == LOW) {
      startRound();
      while (digitalRead(BUTTON_PIN) == LOW) {
        // wait for release
      }
    }
  }

  // if we're waiting for the player to react
  if (waiting && digitalRead(BUTTON_PIN) == LOW) {
    reactionTime = millis() - startTime;
    waiting = false;
    gameActive = false;
    digitalWrite(LED_PIN, LOW);
    Serial.print("Reaction: ");
    Serial.print(reactionTime);
    Serial.println(" ms");
    delay(500);
  }
}

void startRound() {
  gameActive = true;
  digitalWrite(LED_PIN, LOW);
  Serial.println("Get ready...");

  // random delay between 1 and 4 seconds
  unsigned long waitTime = random(1000, 4000);
  delay(waitTime);

  // light the LED and start timing
  digitalWrite(LED_PIN, HIGH);
  startTime = millis();
  waiting = true;
}

// Servo Sweep Tester
// Written by a beginner. This sketch sweeps a servo back and forth
// so you can check that a servo (and its wiring) actually works.
//
// WIRING (important!):
//   Servo signal (orange/yellow wire) -> pin 9
//   Servo power (red wire)            -> 5V
//   Servo ground (brown/black wire)   -> GND
//
// NOTE: A big servo can pull more current than the Uno's 5V pin can give.
// If the servo jitters or the board resets, power the servo from a
// separate 5V supply and connect the grounds together. Ignore that
// warning at your own risk!

#include <Servo.h>  // the Servo library comes with the Arduino core

// Create a servo object. We can have up to 12 of these on an Uno,
// but one is plenty for a tester.
Servo myServo;

// The pin the servo signal wire is plugged into.
// Pin 9 is a PWM-capable pin, which is what Servo likes.
const int SERVO_PIN = 9;

// How far to sweep, in degrees. Standard hobby servos do 0 to 180.
// If your servo grinds at the ends, make these numbers smaller
// (like 10 and 170) so it doesn't push against its mechanical stops.
const int MIN_ANGLE = 0;
const int MAX_ANGLE = 180;

// How long to wait at each position, in milliseconds.
// 15 ms is fast; 50 ms is a nice lazy sweep. Try changing it.
const int STEP_DELAY_MS = 15;

// How many degrees to move per step. 1 = smooth, 10 = chunky.
const int STEP_DEGREES = 1;

void setup() {
  // Attach the servo to its pin. This tells the library to start
  // sending pulses on pin 9.
  myServo.attach(SERVO_PIN);

  // Optional: start in the middle so it doesn't jerk from wherever
  // it happened to be sitting.
  myServo.write(90);
  delay(500);  // give it half a second to get there
}

void loop() {
  // Sweep from MIN to MAX, one step at a time.
  for (int angle = MIN_ANGLE; angle <= MAX_ANGLE; angle += STEP_DEGREES) {
    myServo.write(angle);
    delay(STEP_DELAY_MS);
  }

  // Sweep back from MAX to MIN.
  // (We start at MAX - STEP_DEGREES so we don't sit at MAX twice.)
  for (int angle = MAX_ANGLE - STEP_DEGREES; angle >= MIN_ANGLE; angle -= STEP_DEGREES) {
    myServo.write(angle);
    delay(STEP_DELAY_MS);
  }

  // Then loop() runs again and it sweeps forever.
  // If you only want one sweep, move this code into setup()
  // and leave loop() empty.
}

#include <Arduino.h>

const uint8_t BTN = 2;
const uint8_t LED = 13;
const uint8_t BUZ = 9;
const uint32_t MAXMS = 300000UL;
const uint32_t WARNMS = 240000UL;

bool running = false;
bool warned = false;
uint32_t startMs = 0;
uint32_t lastBlink = 0;
bool ledState = false;

void beep(uint16_t ms) {
  tone(BUZ, 2000, ms);
}

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
  pinMode(BUZ, OUTPUT);
  digitalWrite(LED, LOW);
  Serial.begin(9600);
}

void loop() {
  static bool lastBtn = HIGH;
  bool b = digitalRead(BTN);
  if (lastBtn == HIGH && b == LOW) {
    delay(20);
    if (digitalRead(BTN) == LOW) {
      if (!running) {
        running = true;
        warned = false;
        startMs = millis();
        ledState = true;
        digitalWrite(LED, HIGH);
        beep(80);
        Serial.println(F("start"));
      } else {
        running = false;
        digitalWrite(LED, LOW);
        noTone(BUZ);
        beep(40);
        Serial.println(F("stop"));
      }
    }
  }
  lastBtn = b;

  if (!running) return;

  uint32_t el = millis() - startMs;

  if (!warned && el >= WARNMS) {
    warned = true;
    beep(300);
    Serial.println(F("warn"));
  }

  if (el >= MAXMS) {
    running = false;
    digitalWrite(LED, LOW);
    for (uint8_t i = 0; i < 3; i++) {
      tone(BUZ, 2500, 150);
      delay(250);
    }
    Serial.println(F("done"));
    return;
  }

  uint32_t period = warned ? 200 : 1000;
  if (millis() - lastBlink >= period) {
    lastBlink = millis();
    ledState = !ledState;
    digitalWrite(LED, ledState ? HIGH : LOW);
  }
}

// Smoke detector relay
// Reads an MQ-2 style analog smoke sensor and trips a relay
// when the reading stays above a threshold.

const int sensorPin = A0;
const int relayPin = 7;
const int ledPin = 13;

// threshold on 0-1023 scale
int threshold = 400;

// how long it must stay high before tripping (ms)
unsigned long tripDelay = 2000;

unsigned long highSince = 0;
bool alarm = false;

void setup() {
  pinMode(relayPin, OUTPUT);
  pinMode(ledPin, OUTPUT);
  digitalWrite(relayPin, LOW); // relay off
  digitalWrite(ledPin, LOW);
  Serial.begin(9600);
  Serial.println("Smoke relay ready");
}

void loop() {
  int reading = analogRead(sensorPin);

  if (reading > threshold) {
    if (highSince == 0) {
      highSince = millis();
    }
    // been high long enough?
    if (millis() - highSince >= tripDelay) {
      if (!alarm) {
        alarm = true;
        digitalWrite(relayPin, HIGH);
        digitalWrite(ledPin, HIGH);
        Serial.print("ALARM, reading=");
        Serial.println(reading);
      }
    }
  } else {
    highSince = 0;
    if (alarm) {
      alarm = false;
      digitalWrite(relayPin, LOW);
      digitalWrite(ledPin, LOW);
      Serial.println("Clear");
    }
  }

  delay(50);
}

// Soil moisture irrigation valve
// Reads a capacitive soil sensor on A0, opens a valve via relay on pin 7
// when the soil gets too dry. Hobbyist build, be gentle.

const int SENSOR_PIN = A0;
const int VALVE_PIN = 7;

// Calibration: raw ADC when sensor is in dry air vs in a cup of water
const int DRY_RAW = 620;   // dry-ish
const int WET_RAW = 280;   // wet-ish

// Thresholds in percent moisture
const int START_WATER = 30;  // below this -> water
const int STOP_WATER = 55;   // above this -> stop

// Safety: never water longer than this in one go
const unsigned long MAX_WATER_MS = 120000UL;  // 2 minutes
const unsigned long SAMPLE_MS = 2000UL;

bool watering = false;
unsigned long waterStart = 0;
unsigned long lastSample = 0;

void setup() {
  pinMode(VALVE_PIN, OUTPUT);
  digitalWrite(VALVE_PIN, LOW);  // relay off = valve closed
  Serial.begin(9600);
  Serial.println("Soil irrigation starting");
}

int readMoisturePercent() {
  // average a few readings to smooth out noise
  long sum = 0;
  for (int i = 0; i < 8; i++) {
    sum += analogRead(SENSOR_PIN);
    delay(10);
  }
  int raw = sum / 8;

  // map raw to percent, clamp
  int pct = map(raw, DRY_RAW, WET_RAW, 0, 100);
  if (pct < 0) pct = 0;
  if (pct > 100) pct = 100;
  return pct;
}

void openValve() {
  digitalWrite(VALVE_PIN, HIGH);
  watering = true;
  waterStart = millis();
  Serial.println("Valve OPEN");
}

void closeValve() {
  digitalWrite(VALVE_PIN, LOW);
  watering = false;
  Serial.println("Valve CLOSED");
}

void loop() {
  unsigned long now = millis();

  if (now - lastSample >= SAMPLE_MS) {
    lastSample = now;
    int moisture = readMoisturePercent();
    Serial.print("Moisture: ");
    Serial.print(moisture);
    Serial.println("%");

    if (!watering && moisture < START_WATER) {
      openValve();
    } else if (watering && moisture > STOP_WATER) {
      closeValve();
    }
  }

  // safety timeout so we don't flood the garden
  if (watering && (now - waterStart >= MAX_WATER_MS)) {
    Serial.println("Max water time hit, closing");
    closeValve();
  }
}

// Solar charger cutoff
// Reads panel/battery voltage on A0 through a divider
// Cuts the load off when battery gets low, back on when charged

const int VOLT_PIN = A0;
const int LOAD_PIN = 8;
const int LED_PIN = 13;

// divider: 10k top, 4.7k bottom -> ratio ~3.128
const float DIVIDER = (10.0 + 4.7) / 4.7;
const float VREF = 5.0;

// thresholds in volts (battery side)
const float CUTOFF = 11.8;
const float RESTORE = 12.6;

bool loadOn = true;

float readBattery() {
  // average a few samples to kill noise
  long sum = 0;
  for (int i = 0; i < 8; i++) {
    sum += analogRead(VOLT_PIN);
    delay(2);
  }
  float adc = sum / 8.0;
  float vpin = adc * VREF / 1023.0;
  return vpin * DIVIDER;
}

void setup() {
  pinMode(LOAD_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LOAD_PIN, HIGH); // load on
  digitalWrite(LED_PIN, LOW);
  Serial.begin(9600);
  Serial.println("solar cutoff ready");
}

void loop() {
  float vbat = readBattery();

  if (loadOn && vbat < CUTOFF) {
    // battery too low, disconnect load
    loadOn = false;
    digitalWrite(LOAD_PIN, LOW);
    Serial.print("cutoff at ");
    Serial.println(vbat);
  } else if (!loadOn && vbat > RESTORE) {
    // recovered, turn load back on
    loadOn = true;
    digitalWrite(LOAD_PIN, HIGH);
    Serial.print("restore at ");
    Serial.println(vbat);
  }

  // blink led when load is off
  if (!loadOn) {
    digitalWrite(LED_PIN, HIGH);
    delay(100);
    digitalWrite(LED_PIN, LOW);
  }

  delay(500);
}

// Sound level meter
// mic on A0, LED bar on pins 2..6

const int micPin = A0;
const int ledPins[] = {2, 3, 4, 5, 6};
const int numLeds = 5;

// rough calibration
const int quietLevel = 20;
const int loudLevel = 900;

int peak = 0;
unsigned long lastPrint = 0;

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < numLeds; i++) {
    pinMode(ledPins[i], OUTPUT);
  }
  Serial.println("Sound level meter ready");
}

void loop() {
  // sample fast for a short window to catch peaks
  int localPeak = 0;
  unsigned long start = millis();
  while (millis() - start < 50) {
    int v = analogRead(micPin);
    // center is ~512, measure distance from it
    int level = abs(v - 512);
    if (level > localPeak) {
      localPeak = level;
    }
  }

  // smooth a bit
  peak = (peak * 3 + localPeak) / 4;

  updateLeds(peak);

  if (millis() - lastPrint > 250) {
    lastPrint = millis();
    Serial.print("level: ");
    Serial.println(peak);
  }
}

void updateLeds(int level) {
  // map level to number of leds
  int lit = map(level, quietLevel, loudLevel, 0, numLeds);
  lit = constrain(lit, 0, numLeds);

  for (int i = 0; i < numLeds; i++) {
    if (i < lit) {
      digitalWrite(ledPins[i], HIGH);
    } else {
      digitalWrite(ledPins[i], LOW);
    }
  }
}

#include <Stepper.h>

const int stepsPerRev = 200;
Stepper motor(stepsPerRev, 8, 9, 10, 11);

const int btnFwd = 2;
const int btnRev = 3;
const int btnFast = 4;
const int led = 13;

int speedSlow = 30;
int speedFast = 120;

void setup() {
  pinMode(btnFwd, INPUT_PULLUP);
  pinMode(btnRev, INPUT_PULLUP);
  pinMode(btnFast, INPUT_PULLUP);
  pinMode(led, OUTPUT);
  motor.setSpeed(speedSlow);
  Serial.begin(9600);
}

void loop() {
  bool fwd = !digitalRead(btnFwd);
  bool rev = !digitalRead(btnRev);
  bool fast = !digitalRead(btnFast);

  if (fast) {
    motor.setSpeed(speedFast);
    digitalWrite(led, HIGH);
  } else {
    motor.setSpeed(speedSlow);
    digitalWrite(led, LOW);
  }

  if (fwd && !rev) {
