  } else if (rev && !fwd) {
    motor.step(-1);
  }

  delay(2);
}

// Sump pump controller
// Float switch on pin 2 (closed = water high)
// Pump relay on pin 8
// Buzzer on pin 9
// Status LED on pin 13

const int FLOAT_PIN = 2;
const int PUMP_PIN = 8;
const int BUZZER_PIN = 9;
const int LED_PIN = 13;

const unsigned long RUN_MIN_MS = 5000;   // run at least 5s
const unsigned long RUN_MAX_MS = 60000;  // don't run over 60s
const unsigned long ALARM_MS = 90000;    // alarm if high this long

bool pumping = false;
unsigned long pumpStart = 0;
unsigned long highSince = 0;
bool highActive = false;

void setup() {
  pinMode(FLOAT_PIN, INPUT_PULLUP);
  pinMode(PUMP_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(PUMP_PIN, LOW);
  digitalWrite(BUZZER_PIN, LOW);
  Serial.begin(9600);
  Serial.println("sump ctrl ready");
}

bool waterHigh() {
  // switch pulls to GND when float is up
  return digitalRead(FLOAT_PIN) == LOW;
}

void startPump() {
  digitalWrite(PUMP_PIN, HIGH);
  digitalWrite(LED_PIN, HIGH);
  pumping = true;
  pumpStart = millis();
  Serial.println("pump ON");
}

void stopPump() {
  digitalWrite(PUMP_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
  pumping = false;
  Serial.println("pump OFF");
}

void loop() {
  bool high = waterHigh();
  unsigned long now = millis();

  // track how long water has been high
  if (high && !highActive) {
    highActive = true;
    highSince = now;
  } else if (!high) {
    highActive = false;
  }

  if (high && !pumping) {
    startPump();
  }

  if (pumping) {
    unsigned long run = now - pumpStart;
    // stop when float drops, but respect min run time
    if (!high && run >= RUN_MIN_MS) {
      stopPump();
    }
    // safety: never run forever
    if (run >= RUN_MAX_MS) {
      stopPump();
      Serial.println("max run hit!");
    }
  }

  // alarm if water stays high too long
  if (highActive && (now - highSince) >= ALARM_MS) {
    digitalWrite(BUZZER_PIN, HIGH);
  } else {
    digitalWrite(BUZZER_PIN, LOW);
  }

  delay(50);
}

const uint8_t HALL_PIN = 2;
const uint8_t OUT_PIN = 9;
const uint16_t PULSES_PER_REV = 2;
const uint32_t WINDOW_MS = 1000;

volatile uint32_t pulseCount = 0;
volatile uint32_t lastEdgeUs = 0;
volatile uint32_t periodUs = 0;

uint32_t windowStart = 0;
float rpm = 0.0;

void onPulse() {
  uint32_t now = micros();
  uint32_t dt = now - lastEdgeUs;
  lastEdgeUs = now;
  if (dt > 200) {
    periodUs = dt;
  }
  pulseCount++;
}

void setup() {
  pinMode(HALL_PIN, INPUT_PULLUP);
  pinMode(OUT_PIN, OUTPUT);
  Serial.begin(115200);
  attachInterrupt(digitalPinToInterrupt(HALL_PIN), onPulse, FALLING);
  windowStart = millis();
}

void loop() {
  uint32_t now = millis();
  if (now - windowStart >= WINDOW_MS) {
    uint32_t count;
    uint32_t per;
    noInterrupts();
    count = pulseCount;
    per = periodUs;
    pulseCount = 0;
    interrupts();

    float revs = (float)count / (float)PULSES_PER_REV;
    float secs = (float)(now - windowStart) / 1000.0;
    rpm = (revs / secs) * 60.0;

    if (per > 0) {
      float rpmInst = 60000000.0 / ((float)per * (float)PULSES_PER_REV);
      if (rpmInst < 20000.0) {
        rpm = (rpm * 0.6) + (rpmInst * 0.4);
      }
    }

    Serial.print("RPM: ");
    Serial.print(rpm, 1);
    Serial.print("  pulses: ");
    Serial.println(count);

    windowStart = now;
  }

  int pwm = (int)(rpm / 4.0);
  if (pwm > 255) pwm = 255;
  if (pwm < 0) pwm = 0;
  analogWrite(OUT_PIN, pwm);
}

/*
 * Thermistor Data Logger
 * ----------------------
 * Reads a 10k NTC thermistor in a voltage divider against a 10k series
 * resistor, converts the ADC reading to temperature via the Beta equation,
 * and logs one sample per second over the hardware serial port at 9600 baud.
 *
 * Design notes:
 *  - The thermistor is on the high side (5V -> thermistor -> A0 -> 10k -> GND),
 *    so the ADC voltage rises as temperature rises.
 *  - We average N_AVERAGE samples to reduce ADC noise.
 *  - Beta equation is good enough for a hobby logger; no Steinhart-Hart here.
 */

#include <Arduino.h>

// ---- Hardware configuration ----
const uint8_t  THERMISTOR_PIN = A0;
const uint8_t  LED_PIN        = 13;   // onboard LED, blinks on each log

// ---- Thermistor constants (10k NTC, Beta = 3950) ----
const float SERIES_RESISTOR_OHMS = 10000.0;
const float NOMINAL_RESISTANCE   = 10000.0;  // at 25 C
const float NOMINAL_TEMPERATURE  = 25.0;     // degrees C
const float BETA_COEFFICIENT     = 3950.0;
const float ADC_MAX_COUNT        = 1023.0;
const float SUPPLY_VOLTS         = 5.0;

// ---- Sampling configuration ----
const uint8_t  N_AVERAGE        = 8;
const uint32_t SAMPLE_PERIOD_MS = 1000;

uint32_t lastSampleMs = 0;

// Average several ADC reads for a steadier value.
float readAverageVoltage() {
  uint32_t sum = 0;
  for (uint8_t i = 0; i < N_AVERAGE; i++) {
    sum += analogRead(THERMISTOR_PIN);
    delay(2);
  }
  float counts = (float)sum / (float)N_AVERAGE;
  return counts * (SUPPLY_VOLTS / ADC_MAX_COUNT);
}

// Convert divider voltage to temperature in Celsius.
float voltageToCelsius(float volts) {
  // Guard against divide-by-zero at the rails.
  if (volts <= 0.01) return -99.0;
  if (volts >= SUPPLY_VOLTS - 0.01) return 150.0;

  // Thermistor on high side: R_therm = R_series * V_therm / (V_supply - V_therm)
  float resistance = SERIES_RESISTOR_OHMS * volts / (SUPPLY_VOLTS - volts);

  // Beta equation.
  float steinhart = resistance / NOMINAL_RESISTANCE;
  steinhart = log(steinhart);
  steinhart /= BETA_COEFFICIENT;
  steinhart += 1.0 / (NOMINAL_TEMPERATURE + 273.15);
  steinhart = 1.0 / steinhart;
  return steinhart - 273.15;
}

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
  Serial.println(F("Thermistor Data Logger"));
  Serial.println(F("time_ms,temp_c"));
}

void loop() {
  uint32_t now = millis();
  if (now - lastSampleMs >= SAMPLE_PERIOD_MS) {
    lastSampleMs = now;

    digitalWrite(LED_PIN, HIGH);
    float volts = readAverageVoltage();
    float celsius = voltageToCelsius(volts);

    Serial.print(now);
    Serial.print(',');
    Serial.println(celsius, 2);

    digitalWrite(LED_PIN, LOW);
  }
}

// Tide of Light - sunrise alarm
// fades a big LED up over 30 min before wake time

const uint8_t LED_PIN = 9;      // PWM pin to LED driver
const uint8_t BUTTON_PIN = 2;   // snooze / test button

// sunrise runs 30 minutes = 1800 s
const unsigned long SUNRISE_MS = 1800UL * 1000UL;
// how often we update the brightness
const unsigned long STEP_MS = 1000UL;

// pretend wake time is 7:00 -> we just use millis offset
const unsigned long WAKE_OFFSET_MS = 60UL * 1000UL; // 1 min for testing

unsigned long startMillis = 0;
bool running = false;
bool done = false;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  Serial.begin(9600);
  Serial.println("Tide of Light ready");
  startMillis = millis();
}

void loop() {
  unsigned long now = millis();

  // button starts a manual test sunrise
  if (digitalRead(BUTTON_PIN) == LOW && !running) {
    delay(30); // crude debounce
    if (digitalRead(BUTTON_PIN) == LOW) {
      Serial.println("manual sunrise");
      startMillis = now;
      running = true;
      done = false;
    }
  }

  // auto start when we reach wake offset
  if (!running && !done && (now - startMillis >= WAKE_OFFSET_MS)) {
    Serial.println("auto sunrise");
    startMillis = now;
    running = true;
  }

  if (running) {
    unsigned long elapsed = now - startMillis;
    if (elapsed >= SUNRISE_MS) {
      analogWrite(LED_PIN, 255);
      running = false;
      done = true;
      Serial.println("sunrise done");
    } else {
      // map elapsed to 0..255
      int level = (int)((elapsed * 255UL) / SUNRISE_MS);
      analogWrite(LED_PIN, level);
    }
  }

  delay(STEP_MS);
}

